__device__ __forceinline__ float vllm_tr.text:
__device__ __forceinline__ float vllm_triton_lane8_sumsq(
    const float values[8]
);
__device__ __forceinline__ float vllm_triton_reduce_sumsq(
    float lane_sumsq,
    float *partial,
    unsigned int lane
);

// The BF16 residual carrier is rounded for the next layer, but vLLM's fused
// GemmaRMSNorm computes variance from the unrounded F32 sum of the two BF16
// inputs.  The former q262144 path incorrectly reduced the rounded carrier in
// FP64, which moves the MoE input even when the published residual is exact.
__global__ void q262144_output_bf16_residual_postnorm_bf16_kernel(
    const uint16_t *residual_inputs,
    const uint16_t *attention_updates,
    const uint16_t *norm_weights,
    uint16_t *residual_outputs,
    uint16_t *postnorm_outputs,
    unsigned int tokens
) {
    __shared__ float partial[kThreads];
    __shared__ float inv_shared;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kThreads;
    float unrounded_values[kValuesPerLane];

    const unsigned int token = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (token >= tokens || residual_inputs == nullptr ||
        attention_updates == nullptr || norm_weights == nullptr ||
        residual_outputs == nullptr || postnorm_outputs == nullptr) {
        return;
    }

    const size_t token_base =
        static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = lane * kValuesPerLane + item;
        const float unrounded_value = __fadd_rn(
            device_bf16_to_float(residual_inputs[token_base + col]),
            device_bf16_to_float(attention_updates[token_base + col])
        );
        unrounded_values[item] = unrounded_value;
        residual_outputs[token_base + col] =
            device_float_to_bf16(unrounded_value);
    }
    const float sumsq = vllm_triton_reduce_sumsq(
        vllm_triton_lane8_sumsq(unrounded_values),
        partial,
        lane
    );
    if (lane == 0u) {
        inv_shared = rsqrtf(
            sumsq / static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
            QRT_QWEN36_RMS_NORM_EPSILON
        );
    }
    __syncthreads();

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = lane * kValuesPerLane + item;
        const float value = device_bf16_to_float(
            residual_outputs[token_base + col]
        );
        const float normalized =
            value * inv_shared *
            (1.0f + device_bf16_to_float(norm_weights[col]));
        postnorm_outputs[token_base + col] =
            device_float_to_bf16(normalized);
    }
}

// Qwen3.5's vLLM GemmaRMSNorm path keeps the residual carrier in BF16 and
// evaluates the variance in FP32. TorchInductor fuses the BF16 residual add:
// it publishes and later normalizes the rounded BF16 sum, while its variance
// tree consumes the unrounded FP32 addition of the two BF16 inputs. Preserve
// that asymmetric boundary here rather than recomputing variance from the
// rounded residual carrier.
__global__ void output_bf16_residual_postnorm_vllm_kernel(
    const float *residual_inputs,
    const uint16_t *attention_updates,
    const uint16_t *norm_weights,
    float *residual_outputs,
    float *postnorm_outputs,
    unsigned int tokens,
    const uint8_t *gfx1151_sm121_rsqrt_correction,
    uint16_t *postnorm_outputs_bf16
) {
    __shared__ float partial[kThreads];
    __shared__ float inv_shared;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kThreads;
    float values[kValuesPerLane];
    float unrounded_values[kValuesPerLane];

    const unsigned int token = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (token >= tokens || residual_inputs == nullptr ||
        attention_updates == nullptr || norm_weights == nullptr ||
        residual_outputs == nullptr || postnorm_outputs == nullptr) {
        return;
    }

    const size_t token_base =
        static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = lane * kValuesPerLane + item;
        const float residual = device_bf16_round_to_float(
            residual_inputs[token_base + col]
        );
        const float update =
            device_bf16_to_float(attention_updates[token_base + col]);
        const float unrounded_value = __fadd_rn(residual, update);
        const float value = device_bf16_round_to_float(unrounded_value);
        values[item] = value;
        unrounded_values[item] = unrounded_value;
        residual_outputs[token_base + col] = value;
    }
    const float sumsq = vllm_triton_reduce_sumsq(
        vllm_triton_lane8_sumsq(unrounded_values),
        partial,
        lane
    );
    if (lane == 0u) {
        const float variance = __fadd_rn(
            sumsq / static_cast<float>(QRT_QWEN36_HIDDEN_SIZE),
            QRT_QWEN36_RMS_NORM_EPSILON
        );
        inv_shared = device_sm121_rsqrt_from_gfx1151(
            variance,
            gfx1151_sm121_rsqrt_correction
        );
    }
    __syncthreads();

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = lane * kValuesPerLane + item;
        const float normalized =
            values[item] * inv_shared *
            (1.0f + device_bf16_to_float(norm_weights[col]));
        postnorm_outputs[token_base + col] =
            device_bf16_round_to_float(normalized);
        if (postnorm_outputs_bf16 != nullptr) {
            postnorm_outputs_bf16[token_base + col] =
                device_float_to_bf16(normalized);
        }
    }
}

// Batch-one MoE preserves the original BF16 shared/routed endpoints and the
// unrounded variance carrier. Its next-layer norm uses the same reduction as
// the qualified attention residual norm, without changing prefill flags.
__global__ void q1_moe_sm121_tail_kernel(
    const uint16_t *down, const uint16_t *gate, const float *routed,
    const float *residual, float *output, const uint16_t *norm_weights,
    float *normalized, uint16_t *normalized_bf16,
    const float *sigmoid, const unsigned char *rsqrt_table, bool next_norm
) {
    __shared__ float partial[kThreads];
    __shared__ float inverse;
    constexpr unsigned items = QRT_QWEN36_HIDDEN_SIZE / kThreads;
    const unsigned lane = threadIdx.x;
    float values[items], unrounded[items];
    const float scale = device_bf16_round_to_float(sigmoid[gate[0]]);
    for (unsigned j = 0; j < items; ++j) {
        const unsigned col = lane * items + j;
        const float shared = device_bf16_round_to_float(
            __fmul_rn(scale, device_bf16_to_float(down[col])));
        const float update = device_bf16_round_to_float(
            __fadd_rn(device_bf16_round_to_float(routed[col]), shared));
        unrounded[j] = __fadd_rn(device_bf16_round_to_float(residual[col]), update);
        values[j] = device_bf16_round_to_float(unrounded[j]);
        output[col] = unrounded[j];
    }
    if (!next_norm) return;
    const float sum = vllm_triton_reduce_sumsq(
        vllm_triton_lane8_sumsq(unrounded), partial, lane);
    if (lane == 0u) inverse = qrt_sm121_rsqrt::evaluate(rsqrt_table,
        __fadd_rn(sum / float(QRT_QWEN36_HIDDEN_SIZE), QRT_QWEN36_RMS_NORM_EPSILON));
    __syncthreads();
    for (unsigned j = 0; j < items; ++j) {
        const unsigned col = lane * items + j;
        const float v = values[j] * inverse * (1.0f + device_bf16_to_float(norm_weights[col]));
        const uint16_t endpoint = device_float_to_bf16(v);
        normalized[col] = device_bf16_to_float(endpoint);
        normalized_bf16[col] = endpoint;
    }
}

// Candidate MoE corridor publishes the already-rounded postnorm endpoint to
// BF16 in the producer block.  The F32 path and its double reduction remain
// byte-for-byte the retained output_bf16_residual_postnorm arithmetic; the
// extra store replaces the following MoE input-pack launch.
__global__ void output_bf16_residual_postnorm_dual_kernel(
    const float *residual_inputs,
    const uint16_t *attention_updates,
    const uint16_t *norm_weights,
    float *residual_outputs,
    float *postnorm_outputs,
    uint16_t *postnorm_outputs_bf16,
    unsigned int tokens
) {
    __shared__ double partial[kThreads];
    __shared__ float inv_shared;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kThreads;
    float values[kValuesPerLane];

    const unsigned int token = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (token >= tokens || postnorm_outputs_bf16 == nullptr) {
        return;
    }

    const size_t token_base =
        static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    double sumsq = 0.0;
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = lane + item * kThreads;
        const float value =
            residual_inputs[token_base + col] +
            device_bf16_to_float(attention_updates[token_base + col]);
        values[item] = value;
        residual_outputs[token_base + col] = value;
        sumsq += static_cast<double>(value) * static_cast<double>(value);
    }
    partial[lane] = sumsq;
    __syncthreads();

    for (unsigned int stride = kThreads / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            partial[lane] += partial[lane + stride];
        }
        __syncthreads();
    }
    if (lane == 0u) {
        inv_shared = 1.0f / sqrtf(
            static_cast<float>(
                partial[0] /
                static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
            ) +
            QRT_QWEN36_RMS_NORM_EPSILON
        );
    }
    __syncthreads();

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = lane + item * kThreads;
        const float normalized =
            values[item] * inv_shared *
            (1.0f + device_bf16_to_float(norm_weights[col]));
        const uint16_t endpoint = device_float_to_bf16(normalized);
        postnorm_outputs[token_base + col] = device_bf16_to_float(endpoint);
        postnorm_outputs_bf16[token_base + col] = endpoint;
    }
}

__global__ void out_projection_tiled_kernel(
    const uint16_t *weights,
    const float *inputs,
    float *outputs,
    unsigned int tokens
) {
    __shared__ float input_tile[kTileTokens][kTileK];
    __shared__ float weight_tile[kTileRows][kTileK];

    const unsigned int local_row = threadIdx.x;
    const unsigned int local_token = threadIdx.y;
    const unsigned int row_base = blockIdx.x * kTileRows + local_row;
    const unsigned int token_base = blockIdx.y * kTileTokens + local_token;

    float sums[kTokenGroups][kRowGroups] = {};
    for (unsigned int k0 = 0; k0 < kValueFeatures; k0 += kTileK) {
        const unsigned int k_col = k0 + local_row;
        #pragma unroll
        for (unsigned int token_group = 0; token_group < kTokenGroups; ++token_group) {
            const unsigned int token = token_base + token_group * kThreadTileTokens;
            const unsigned int token_offset = local_token + token_group * kThreadTileTokens;
            if (local_row < kTileK) {
                if (token < tokens && k_col < kValueFeatures) {
                    input_tile[token_offset][local_row] =
                        inputs[static_cast<size_t>(token) * kValueFeatures + k_col];
                } else {
                    input_tile[token_offset][local_row] = 0.0f;
                }
            }
        }
        #pragma unroll
        for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
            const unsigned int row = blockIdx.x * kTileRows + local_token + row_group * kThreadTileRows;
            const unsigned int row_offset = local_token + row_group * kThreadTileRows;
            if (local_row < kTileK) {
                if (row < kOutProjectionRows && k_col < kValueFeatures) {
                    weight_tile[row_offset][local_row] = device_bf16_to_float(
                        weights[static_cast<size_t>(row) * kValueFeatures + k_col]
                    );
                } else {
                    weight_tile[row_offset][local_row] = 0.0f;
                }
            }
        }

        __syncthreads();

        for (unsigned int k = 0; k < kTileK; ++k) {
            float input_values[kTokenGroups];
            float weight_values[kRowGroups];
            #pragma unroll
            for (unsigned int token_group = 0; token_group < kTokenGroups; ++token_group) {
                input_values[token_group] =
                    input_tile[local_token + token_group * kThreadTileTokens][k];
            }
            #pragma unroll
            for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
                weight_values[row_group] =
                    weight_tile[local_row + row_group * kThreadTileRows][k];
            }
            #pragma unroll
            for (unsigned int token_group = 0; token_group < kTokenGroups; ++token_group) {
                #pragma unroll
                for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
                    sums[token_group][row_group] +=
                        input_values[token_group] * weight_values[row_group];
                }
            }
        }
        __syncthreads();
    }

    #pragma unroll
    for (unsigned int token_group = 0; token_group < kTokenGroups; ++token_group) {
        const unsigned int token = token_base + token_group * kThreadTileTokens;
        #pragma unroll
        for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
            const unsigned int row = row_base + row_group * kThreadTileRows;
            if (token < tokens && row < kOutProjectionRows) {
                outputs[static_cast<size_t>(token) * kOutProjectionRows + row] =
                    device_bf16_round_to_float(sums[token_group][row_group]);
            }
        }
    }
}

__global__ void out_projection_m16_exact_kernel(
    const uint16_t *weights,
    const float *inputs,
    float *outputs,
    unsigned int tokens
) {
    constexpr unsigned int kMaxTokens = 16u;
    __shared__ float partial[kMaxTokens][kThreads];

    const unsigned int row = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (row >= kOutProjectionRows || tokens == 0u || tokens > kMaxTokens) {
        return;
    }
    float sums[kMaxTokens] = {};
    const uint16_t *row_weights =
        weights + static_cast<size_t>(row) * kValueFeatures;
    for (unsigned int col = lane; col < kValueFeatures; col += blockDim.x) {
        const float weight = device_bf16_to_float(row_weights[col]);
        #pragma unroll
        for (unsigned int token = 0u; token < kMaxTokens; ++token) {
            if (token < tokens) {
                sums[token] +=
                    weight * inputs[
                        static_cast<size_t>(token) * kValueFeatures + col
                    ];
            }
        }
    }
    #pragma unroll
    for (unsigned int token = 0u; token < kMaxTokens; ++token) {
        partial[token][lane] = sums[token];
    }
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u;
         stride > 0u;
         stride >>= 1u) {
        if (lane < stride) {
            #pragma unroll
            for (unsigned int token = 0u; token < kMaxTokens; ++token) {
                partial[token][lane] += partial[token][lane + stride];
            }
        }
        __syncthreads();
    }
    if (lane == 0u) {
        #pragma unroll
        for (unsigned int token = 0u; token < kMaxTokens; ++token) {
            if (token < tokens) {
                outputs[static_cast<size_t>(token) * kOutProjectionRows + row] =
                    device_bf16_round_to_float(partial[token][0]);
            }
        }
    }
}

