            float input_values[kTokenGroups];
            float weight_values[kRowGroups];
            #pragma unroll
            for (unsigned int token_group = 0; token_group < kTokenGroups; ++token_group) {
                input_values[token_group] =
                    input_tile[local_token + token_group * kThreadTileTokens][k];
            }
            #pragma unroll
            for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
                weight_values[row_group] =
                    weight_tile[local_row + row_group * kThreadTileRows][k];
            }
            #pragma unroll
            for (unsigned int token_group = 0; token_group < kTokenGroups; ++token_group) {
                #pragma unroll
                for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
                    sums[token_group][row_group] +=
                        input_values[token_group] * weight_values[row_group];
