    for (unsigned int token_group = 0; token_group < kTokenGroups; ++token_group) {
        const unsigned int token = token_base + token_group * kThreadTileTokens;
        #pragma unroll
        for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
            const unsigned int row = row_base + row_group * kThreadTileRows;
            if (token < tokens && row < kOutProjectionRows) {
                const size_t output_index =
                    static_cast<size_t>(token) * kOutProjectionRows + row;
