template <unsigned int TokenTileTokens>
__global__ void out_projection_tiled_token_kernel(
    const uint16_t *weights,
    const float *inputs,
    float *outputs,
    unsigned int tokens
) {
    static_assert(
        TokenTileTokens % kThreadTileTokens == 0,
        "out-projection token tile must align with thread token tile"
    );
    constexpr unsigned int kLocalTokenGroups = TokenTileTokens / kThreadTileTokens;
    __shared__ float input_tile[TokenTileTokens][kTileK];
    __shared__ float weight_tile[kTileRows][kTileK];

    const unsigned int local_row = threadIdx.x;
    const unsigned int local_token = threadIdx.y;
    const unsigned int row_base = blockIdx.x * kTileRows + local_row;
    const unsigned int token_base = blockIdx.y * TokenTileTokens + local_token;

    float sums[kLocalTokenGroups][kRowGroups] = {};
    for (unsigned int k0 = 0; k0 < kValueFeatures; k0 += kTileK) {
        const unsigned int k_col = k0 + local_row;
        #pragma unroll
        for (unsigned int token_group = 0; token_group < kLocalTokenGroups; ++token_group) {
            const unsigned int token = token_base + token_group * kThreadTileTokens;
            const unsigned int token_offset = local_token + token_group * kThreadTileTokens;
            if (local_row < kTileK) {
                if (token < tokens && k_col < kValueFeatures) {
                    input_tile[token_offset][local_row] =
                        inputs[static_cast<size_t>(token) * kValueFeatures + k_col];
                } else {
                    input_tile[token_offset][local_row] = 0.0f;
                }
            }
        }
        #pragma unroll
        for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
            const unsigned int row =
                blockIdx.x * kTileRows + local_token + row_group * kThreadTileRows;
            const unsigned int row_offset = local_token + row_group * kThreadTileRows;
            if (local_row < kTileK) {
                if (row < kOutProjectionRows && k_col < kValueFeatures) {
                    weight_tile[row_offset][local_row] = device_bf16_to_float(
                        weights[static_cast<size_t>(row) * kValueFeatures + k_col]
                    );
                } else {
                    weight_tile[row_offset][local_row] = 0.0f;
                }
            }
        }

        __syncthreads();

        for (unsigned int k = 0; k < kTileK; ++k) {
            float input_values[kLocalTokenGroups];
            float weight_values[kRowGroups];
            #pragma unroll
            for (unsigned int token_group = 0; token_group < kLocalTokenGroups; ++token_group) {
                input_values[token_group] =
                    input_tile[local_token + token_group * kThreadTileTokens][k];
            }
            #pragma unroll
            for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
                weight_values[row_group] =
                    weight_tile[local_row + row_group * kThreadTileRows][k];
            }
            #pragma unroll
            for (unsigned int token_group = 0; token_group < kLocalTokenGroups; ++token_group) {
                #pragma unroll
                for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
                    sums[token_group][row_group] +=
                        input_values[token_group] * weight_values[row_group];
                }
            }
        }
        __syncthreads();
    }

    #pragma unroll
    for (unsigned int token_group = 0; token_group < kLocalTokenGroups; ++token_group) {
        const unsigned int token = token_base + token_group * kThreadTileTokens;
        #pragma unroll
        for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
            const unsigned int row = row_base + row_group * kThreadTileRows;
            if (token < tokens && row < kOutProjectionRows) {
                outputs[static_cast<size_t>(token) * kOutProjectionRows + row] =
                    device_bf16_round_to_float(sums[token_group][row_group]);
            }
        }
    }
}

// Decode owns exactly one token.  Keep the same cooperative 64-row weight
// tile and the same scalar K order as out_projection_tiled_token_kernel, but
// let only the token-zero owners retain the four row accumulators.  The other
// threads still populate the identical weight-tile layout, avoiding the
// 64/256 synthetic-token accumulator groups used by the prefill kernels.
__global__ void out_projection_q1_exact_kernel(
    const uint16_t *weights,
    const float *inputs,
    float *outputs
) {
    __shared__ float input_tile[kTileK];
    __shared__ float weight_tile[kTileRows][kTileK];

    const unsigned int local_row = threadIdx.x;
    const unsigned int local_token = threadIdx.y;
    const unsigned int row_base = blockIdx.x * kTileRows + local_row;
    float sums[kRowGroups] = {};

    for (unsigned int k0 = 0; k0 < kValueFeatures; k0 += kTileK) {
        const unsigned int k_col = k0 + local_row;
        if (local_token == 0u) {
            input_tile[local_row] = inputs[k_col];
        }
        #pragma unroll
        for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
            const unsigned int row =
                blockIdx.x * kTileRows + local_token +
                row_group * kThreadTileRows;
            const unsigned int row_offset =
                local_token + row_group * kThreadTileRows;
            weight_tile[row_offset][local_row] =
                row < kOutProjectionRows
                    ? device_bf16_to_float(
                          weights[
                              static_cast<size_t>(row) * kValueFeatures +
                              k_col
                          ]
                      )
                    : 0.0f;
        }

        __syncthreads();

        if (local_token == 0u) {
            for (unsigned int k = 0; k < kTileK; ++k) {
                const float input_value = input_tile[k];
                float weight_values[kRowGroups];
                #pragma unroll
                for (unsigned int row_group = 0;
                     row_group < kRowGroups;
                     ++row_group) {
                    weight_values[row_group] =
                        weight_tile[
                            local_row + row_group * kThreadTileRows
                        ][k];
                }
                #pragma unroll
                for (unsigned int row_group = 0;
                     row_group < kRowGroups;
                     ++row_group) {
                    sums[row_group] +=
                        input_value * weight_values[row_group];
                }
            }
        }
        __syncthreads();
    }

    if (local_token == 0u) {
        #pragma unroll
        for (unsigned int row_group = 0; row_group < kRowGroups; ++row_group) {
            const unsigned int row =
                row_base + row_group * kThreadTileRows;
            if (row < kOutProjectionRows) {
                outputs[row] =
                    device_bf16_round_to_float(sums[row_group]);
            }
        }
    }
}

// D132 keeps the terminal BF16 weights, F32 context/multiplication/
// accumulation, and BF16-rounded F32 endpoint.  It changes only the
// reduction ownership: one wave32 owns one output row instead of one thread
// retaining four scalar-K row accumulators.
constexpr unsigned int kQ1FullTerminalWaveOutThreads = 256u;
constexpr unsigned int kQ1FullTerminalWaveOutWaves =
    kQ1FullTerminalWaveOutThreads / 32u;
__device__ __forceinline__ float q1_full_terminal_wave32_sum(float value) {
#pragma unroll
    for (unsigned int offset = 16u; offset != 0u; offset >>= 1u) {
        value += __shfl_down(value, offset, 32);
    }
    return value;
}

__global__ __launch_bounds__(kQ1FullTerminalWaveOutThreads)
void out_projection_q1_wave_f32_kernel(
    const uint16_t *weights,
    const float *inputs,
    float *outputs
) {
    const unsigned int lane = threadIdx.x & 31u;
    const unsigned int wave = threadIdx.x >> 5u;
    const unsigned int row =
        blockIdx.x * kQ1FullTerminalWaveOutWaves + wave;
    if (row >= kOutProjectionRows) {
        return;
    }
    float sum = 0.0f;
#pragma unroll 1
    for (unsigned int k = lane; k < kValueFeatures; k += 32u) {
        sum += inputs[k] * device_bf16_to_float(
            weights[static_cast<size_t>(row) * kValueFeatures + k]
        );
    }
    sum = q1_full_terminal_wave32_sum(sum);
    if (lane == 0u) {
        outputs[row] = device_bf16_round_to_float(sum);
    }
}

__global__ void residual_hidden_add_kernel(
    const uint16_t *hidden,
    const float *attention_update,
    float *outputs,
    unsigned int tokens
) {
    const size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const size_t total = static_cast<size_t>(tokens) * QRT_QWEN36_HIDDEN_SIZE;
    if (idx >= total) {
        return;
    }
    outputs[idx] = device_bf16_to_float(hidden[idx]) + attention_update[idx];
}

__global__ void post_attention_rmsnorm_kernel(
    const float *residual_hidden,
    const uint16_t *norm_weights,
    float *outputs,
    unsigned int tokens
) {
    __shared__ double partial[kThreads];
    __shared__ float inv_shared;

    const unsigned int token = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (token >= tokens) {
        return;
    }

    const size_t token_base = static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    double sumsq = 0.0;
    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE; col += blockDim.x) {
        const float value = residual_hidden[token_base + col];
        sumsq += static_cast<double>(value) * static_cast<double>(value);
    }
    partial[lane] = sumsq;
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            partial[lane] += partial[lane + stride];
        }
        __syncthreads();
    }

    if (lane == 0u) {
        inv_shared = 1.0f / sqrtf(
            static_cast<float>(partial[0] / static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)) +
            QRT_QWEN36_RMS_NORM_EPSILON
        );
    }
    __syncthreads();

    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE; col += blockDim.x) {
        const float value = residual_hidden[token_base + col] *
                            inv_shared *
                            (1.0f + device_bf16_to_float(norm_weights[col]));
        outputs[token_base + col] = device_bf16_round_to_float(value);
    }
}

// F32 terminal/full-attention fallback companion for the same producer-owned
// BF16 endpoint used by the multi-row MoE corridor.
__global__ void post_attention_rmsnorm_dual_kernel(
    const float *residual_hidden,
    const uint16_t *norm_weights,
    float *outputs,
    uint16_t *outputs_bf16,
    unsigned int tokens
) {
    __shared__ double partial[kThreads];
    __shared__ float inv_shared;

    const unsigned int token = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (token >= tokens || outputs_bf16 == nullptr) {
        return;
    }

    const size_t token_base =
        static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    double sumsq = 0.0;
    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE;
         col += blockDim.x) {
        const float value = residual_hidden[token_base + col];
        sumsq += static_cast<double>(value) * static_cast<double>(value);
    }
    partial[lane] = sumsq;
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            partial[lane] += partial[lane + stride];
        }
        __syncthreads();
    }

    if (lane == 0u) {
        inv_shared = 1.0f / sqrtf(
            static_cast<float>(
                partial[0] / static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
            ) + QRT_QWEN36_RMS_NORM_EPSILON
        );
    }
    __syncthreads();

    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE;
         col += blockDim.x) {
        const float value = residual_hidden[token_base + col] *
                            inv_shared *
                            (1.0f + device_bf16_to_float(norm_weights[col]));
        const uint16_t endpoint = device_float_to_bf16(value);
        outputs[token_base + col] = device_bf16_to_float(endpoint);
        outputs_bf16[token_base + col] = endpoint;
    }
}

__global__ void moe_router_kernel(
    const float *post_attention,
    const uint16_t *router_weights,
    float *logits,
    uint32_t *topk_ids,
    float *topk_weights,
    unsigned int tokens
) {
    __shared__ float shared_logits[QRT_QWEN36_EXPERT_COUNT];

    const unsigned int token = blockIdx.x;
    const unsigned int expert = threadIdx.x;
    if (token >= tokens || expert >= QRT_QWEN36_EXPERT_COUNT) {
        return;
    }

    const float *token_input = post_attention + static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    const uint16_t *row_weights = router_weights + static_cast<size_t>(expert) * QRT_QWEN36_HIDDEN_SIZE;
    float acc = 0.0f;
    for (unsigned int col = 0; col < QRT_QWEN36_HIDDEN_SIZE; ++col) {
        acc += device_bf16_to_float(row_weights[col]) * token_input[col];
    }
    shared_logits[expert] = acc;
    logits[static_cast<size_t>(token) * QRT_QWEN36_EXPERT_COUNT + expert] = acc;
    __syncthreads();

    if (expert == 0u) {
        uint32_t best_ids[QRT_QWEN36_EXPERTS_PER_TOKEN];
        double exp_values[QRT_QWEN36_EXPERTS_PER_TOKEN];
        double max_value = -1.0e300;
        double denom = 0.0;

        for (unsigned int route = 0; route < QRT_QWEN36_EXPERTS_PER_TOKEN; ++route) {
            unsigned int best_expert = QRT_QWEN36_EXPERT_COUNT;
            for (unsigned int candidate = 0; candidate < QRT_QWEN36_EXPERT_COUNT; ++candidate) {
                bool already_selected = false;
                for (unsigned int prior = 0; prior < route; ++prior) {
                    already_selected = already_selected || best_ids[prior] == candidate;
                }
                if (already_selected) {
                    continue;
                }
                if (best_expert == QRT_QWEN36_EXPERT_COUNT ||
                    shared_logits[candidate] > shared_logits[best_expert] ||
                    (shared_logits[candidate] == shared_logits[best_expert] && candidate < best_expert)) {
                    best_expert = candidate;
                }
            }
            best_ids[route] = best_expert;
            topk_ids[static_cast<size_t>(token) * QRT_QWEN36_EXPERTS_PER_TOKEN + route] = best_expert;
            if (static_cast<double>(shared_logits[best_expert]) > max_value) {
                max_value = static_cast<double>(shared_logits[best_expert]);
            }
        }

        for (unsigned int route = 0; route < QRT_QWEN36_EXPERTS_PER_TOKEN; ++route) {
            const double value = exp(static_cast<double>(shared_logits[best_ids[route]]) - max_value);
            exp_values[route] = value;
            denom += value;
        }
        for (unsigned int route = 0; route < QRT_QWEN36_EXPERTS_PER_TOKEN; ++route) {
            const float value = static_cast<float>(exp_values[route] / denom);
            topk_weights[static_cast<size_t>(token) * QRT_QWEN36_EXPERTS_PER_TOKEN + route] = value;
        }
    }
}

__global__ void transpose_moe_router_bf16_kernel(
    const uint16_t *row_major,
    uint16_t *column_major
) {
    constexpr unsigned int kTile = 32u;
    constexpr unsigned int kBlockRows = 8u;
    __shared__ uint16_t tile[kTile][kTile + 1u];
    const unsigned int source_col = blockIdx.x * kTile + threadIdx.x;
    const unsigned int source_row = blockIdx.y * kTile + threadIdx.y;
    #pragma unroll
    for (unsigned int offset = 0u; offset < kTile;
         offset += kBlockRows) {
        if (source_col < QRT_QWEN36_HIDDEN_SIZE &&
            source_row + offset < QRT_QWEN36_EXPERT_COUNT) {
            tile[threadIdx.y + offset][threadIdx.x] = row_major[
                static_cast<size_t>(source_row + offset) *
                    QRT_QWEN36_HIDDEN_SIZE +
                source_col
            ];
        }
    }
    __syncthreads();

    const unsigned int destination_col =
        blockIdx.y * kTile + threadIdx.x;
    const unsigned int destination_row =
        blockIdx.x * kTile + threadIdx.y;
    #pragma unroll
    for (unsigned int offset = 0u; offset < kTile;
         offset += kBlockRows) {
        if (destination_col < QRT_QWEN36_EXPERT_COUNT &&
            destination_row + offset < QRT_QWEN36_HIDDEN_SIZE) {
            column_major[
                static_cast<size_t>(destination_row + offset) *
                    QRT_QWEN36_EXPERT_COUNT +
                destination_col
            ] = tile[threadIdx.x][threadIdx.y + offset];
        }
    }
}

// The transposed model-load copy keeps one thread per expert and preserves the
// legacy column-by-column accumulation order.  Only the weight address changes:
// adjacent expert threads now read adjacent BF16 values at every column.
__global__ void moe_router_transposed_kernel(
    const float *post_attention,
    const uint16_t *router_weights_transposed,
    float *logits,
    uint32_t *topk_ids,
    float *topk_weights,
    unsigned int tokens
) {
    __shared__ float shared_logits[QRT_QWEN36_EXPERT_COUNT];

    const unsigned int token = blockIdx.x;
    const unsigned int expert = threadIdx.x;
    if (token >= tokens || expert >= QRT_QWEN36_EXPERT_COUNT) {
        return;
    }

    const float *token_input = post_attention +
        static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    float acc = 0.0f;
    for (unsigned int col = 0u; col < QRT_QWEN36_HIDDEN_SIZE; ++col) {
        acc += device_bf16_to_float(
            router_weights_transposed[
                static_cast<size_t>(col) * QRT_QWEN36_EXPERT_COUNT + expert
            ]
        ) * token_input[col];
    }
    shared_logits[expert] = acc;
    logits[
        static_cast<size_t>(token) * QRT_QWEN36_EXPERT_COUNT + expert
    ] = acc;
    __syncthreads();

    if (expert == 0u) {
        uint32_t best_ids[QRT_QWEN36_EXPERTS_PER_TOKEN];
        double exp_values[QRT_QWEN36_EXPERTS_PER_TOKEN];
        double max_value = -1.0e300;
        double denom = 0.0;

        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            unsigned int best_expert = QRT_QWEN36_EXPERT_COUNT;
            for (unsigned int candidate = 0u;
                 candidate < QRT_QWEN36_EXPERT_COUNT;
                 ++candidate) {
                bool already_selected = false;
                for (unsigned int prior = 0u; prior < route; ++prior) {
                    already_selected = already_selected ||
                        best_ids[prior] == candidate;
                }
                if (already_selected) {
                    continue;
                }
                if (best_expert == QRT_QWEN36_EXPERT_COUNT ||
                    shared_logits[candidate] > shared_logits[best_expert] ||
                    (shared_logits[candidate] == shared_logits[best_expert] &&
                     candidate < best_expert)) {
                    best_expert = candidate;
                }
            }
            best_ids[route] = best_expert;
            topk_ids[
                static_cast<size_t>(token) *
                    QRT_QWEN36_EXPERTS_PER_TOKEN +
                route
            ] = best_expert;
            if (static_cast<double>(shared_logits[best_expert]) > max_value) {
                max_value = static_cast<double>(shared_logits[best_expert]);
            }
        }

        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            const double value = exp(
                static_cast<double>(shared_logits[best_ids[route]]) -
                max_value
            );
            exp_values[route] = value;
            denom += value;
        }
        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            topk_weights[
                static_cast<size_t>(token) *
                    QRT_QWEN36_EXPERTS_PER_TOKEN +
                route
            ] = static_cast<float>(exp_values[route] / denom);
        }
    }
}

