// D32 keeps the deterministic serial top-8 selection and the exact route-order
// denominator reduction, but assigns the eight independent double-precision
// exponentials to eight lanes.  Each exponential sees the same BF16-expanded
// input and shared maximum as the retained scalar implementation.
__global__ void moe_router_bf16_logits_topk_parallel_exp_kernel(
    const uint16_t *logits_bf16,
    float *logits,
    uint32_t *topk_ids,
    float *topk_weights
) {
    __shared__ float shared_logits[QRT_QWEN36_EXPERT_COUNT];
    __shared__ uint32_t shared_best_ids[QRT_QWEN36_EXPERTS_PER_TOKEN];
    __shared__ double shared_exp_values[QRT_QWEN36_EXPERTS_PER_TOKEN];
    __shared__ double shared_max_value;

    const unsigned int expert = threadIdx.x;
    if (expert >= QRT_QWEN36_EXPERT_COUNT) {
        return;
    }
    const float value = device_bf16_to_float(logits_bf16[expert]);
    shared_logits[expert] = value;
    logits[expert] = value;
    __syncthreads();

    if (expert == 0u) {
        double max_value = -1.0e300;
        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            unsigned int best_expert = QRT_QWEN36_EXPERT_COUNT;
            for (unsigned int candidate = 0u;
                 candidate < QRT_QWEN36_EXPERT_COUNT;
                 ++candidate) {
                bool already_selected = false;
                for (unsigned int prior = 0u; prior < route; ++prior) {
                    already_selected = already_selected ||
                        shared_best_ids[prior] == candidate;
                }
                if (already_selected) {
                    continue;
                }
                if (best_expert == QRT_QWEN36_EXPERT_COUNT ||
                    shared_logits[candidate] > shared_logits[best_expert] ||
                    (shared_logits[candidate] == shared_logits[best_expert] &&
                     candidate < best_expert)) {
                    best_expert = candidate;
                }
            }
            shared_best_ids[route] = best_expert;
            topk_ids[route] = best_expert;
            if (static_cast<double>(shared_logits[best_expert]) > max_value) {
                max_value = static_cast<double>(shared_logits[best_expert]);
            }
        }
        shared_max_value = max_value;
    }
    __syncthreads();

    if (expert < QRT_QWEN36_EXPERTS_PER_TOKEN) {
        shared_exp_values[expert] = exp(
            static_cast<double>(shared_logits[shared_best_ids[expert]]) -
            shared_max_value
        );
    }
    __syncthreads();

    if (expert == 0u) {
        double denom = 0.0;
        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            denom += shared_exp_values[route];
        }
        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            topk_weights[route] =
                static_cast<float>(shared_exp_values[route] / denom);
        }
    }
}

__device__ __forceinline__ bool moe_router_topk_candidate_better(
    float candidate_value,
    uint32_t candidate_id,
    float best_value,
    uint32_t best_id
) {
    if (candidate_id >= QRT_QWEN36_EXPERT_COUNT) {
        return false;
    }
    if (best_id >= QRT_QWEN36_EXPERT_COUNT) {
        return true;
    }
    return candidate_value > best_value ||
        (candidate_value == best_value && candidate_id < best_id);
}

// D33 distributes each deterministic winner search across eight logical
// 32-lane waves.  Selection remains route-by-route, with the retained
// high-logit/low-expert-id comparator.  The softmax stays serial so every
// double exp input and denominator addition keeps the original order.  NaN
// logits use the retained scalar path because its scan-order semantics are not
// representable by an associative reduction comparator.
__global__ void q1_moe_dual_router_input_pointer_table_kernel(
    const float *input0,
    const float *input1,
    uint16_t *input_bf160,
    uint16_t *input_bf161,
    const uint16_t *router_weights,
    uint16_t *router_logits_bf160,
    uint16_t *router_logits_bf161,
    const uint16_t **router_a_ptrs,
    const uint16_t **router_b_ptrs,
    uint16_t **router_d_ptrs,
    size_t input_elements
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index < input_elements) {
        input_bf160[index] = device_float_to_bf16(input0[index]);
        input_bf161[index] = device_float_to_bf16(input1[index]);
    }
    if (blockIdx.x == 0u && threadIdx.x == 0u) {
        router_a_ptrs[0u] = router_weights;
        router_a_ptrs[1u] = router_weights;
        router_b_ptrs[0u] = input_bf160;
        router_b_ptrs[1u] = input_bf161;
        router_d_ptrs[0u] = router_logits_bf160;
        router_d_ptrs[1u] = router_logits_bf161;
    }
}

__global__ void moe_router_bf16_logits_topk_parallel_selection_kernel(
    const uint16_t *logits_bf160,
    float *logits0,
    uint32_t *topk_ids0,
    float *topk_weights0,
    const uint16_t *logits_bf161,
    float *logits1,
    uint32_t *topk_ids1,
    float *topk_weights1,
    unsigned int state_count
) {
    constexpr unsigned int kLogicalWaveSize = 32u;
    constexpr unsigned int kLogicalWaveCount =
        QRT_QWEN36_EXPERT_COUNT / kLogicalWaveSize;
    __shared__ float shared_logits[QRT_QWEN36_EXPERT_COUNT];
    __shared__ float shared_wave_values[kLogicalWaveCount];
    __shared__ uint32_t shared_wave_ids[kLogicalWaveCount];
    __shared__ uint32_t shared_best_ids[QRT_QWEN36_EXPERTS_PER_TOKEN];
    __shared__ unsigned int shared_has_nan;

    const unsigned int state = blockIdx.x;
    const unsigned int expert = threadIdx.x;
    if (state >= state_count || state >= 2u ||
        expert >= QRT_QWEN36_EXPERT_COUNT) {
        return;
    }
    const uint16_t *logits_bf16 =
        state == 0u ? logits_bf160 : logits_bf161;
    float *logits = state == 0u ? logits0 : logits1;
    uint32_t *topk_ids = state == 0u ? topk_ids0 : topk_ids1;
    float *topk_weights =
        state == 0u ? topk_weights0 : topk_weights1;
    if (expert == 0u) {
        shared_has_nan = 0u;
    }
    __syncthreads();

    const float value = device_bf16_to_float(logits_bf16[expert]);
    shared_logits[expert] = value;
    logits[expert] = value;
    if (value != value) {
        atomicExch(&shared_has_nan, 1u);
    }
    __syncthreads();

    if (shared_has_nan != 0u) {
        if (expert == 0u) {
            uint32_t best_ids[QRT_QWEN36_EXPERTS_PER_TOKEN];
            double exp_values[QRT_QWEN36_EXPERTS_PER_TOKEN];
            double max_value = -1.0e300;
            double denom = 0.0;
            for (unsigned int route = 0u;
                 route < QRT_QWEN36_EXPERTS_PER_TOKEN;
                 ++route) {
                unsigned int best_expert = QRT_QWEN36_EXPERT_COUNT;
                for (unsigned int candidate = 0u;
                     candidate < QRT_QWEN36_EXPERT_COUNT;
                     ++candidate) {
                    bool already_selected = false;
                    for (unsigned int prior = 0u; prior < route; ++prior) {
                        already_selected = already_selected ||
                            best_ids[prior] == candidate;
                    }
                    if (already_selected) {
                        continue;
                    }
                    if (best_expert == QRT_QWEN36_EXPERT_COUNT ||
                        shared_logits[candidate] >
                            shared_logits[best_expert] ||
                        (shared_logits[candidate] ==
                             shared_logits[best_expert] &&
                         candidate < best_expert)) {
                        best_expert = candidate;
                    }
                }
                best_ids[route] = best_expert;
                topk_ids[route] = best_expert;
                if (static_cast<double>(shared_logits[best_expert]) >
                    max_value) {
                    max_value =
                        static_cast<double>(shared_logits[best_expert]);
                }
            }
            for (unsigned int route = 0u;
                 route < QRT_QWEN36_EXPERTS_PER_TOKEN;
                 ++route) {
                const double route_exp = exp(
                    static_cast<double>(shared_logits[best_ids[route]]) -
                    max_value
                );
                exp_values[route] = route_exp;
                denom += route_exp;
            }
            for (unsigned int route = 0u;
                 route < QRT_QWEN36_EXPERTS_PER_TOKEN;
                 ++route) {
                topk_weights[route] =
                    static_cast<float>(exp_values[route] / denom);
            }
        }
        return;
    }

    const unsigned int lane = expert & (kLogicalWaveSize - 1u);
    const unsigned int wave = expert / kLogicalWaveSize;
    bool selected = false;
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        float wave_best_value = value;
        uint32_t wave_best_id = selected
            ? QRT_QWEN36_EXPERT_COUNT
            : expert;
        for (unsigned int offset = kLogicalWaveSize / 2u;
             offset > 0u;
             offset /= 2u) {
            const float other_value = __shfl_down(
                wave_best_value,
                offset,
                kLogicalWaveSize
            );
            const uint32_t other_id = __shfl_down(
                wave_best_id,
                offset,
                kLogicalWaveSize
            );
            if (lane + offset < kLogicalWaveSize &&
                moe_router_topk_candidate_better(
                    other_value,
                    other_id,
                    wave_best_value,
                    wave_best_id
                )) {
                wave_best_value = other_value;
                wave_best_id = other_id;
            }
        }
        if (lane == 0u) {
            shared_wave_values[wave] = wave_best_value;
            shared_wave_ids[wave] = wave_best_id;
        }
        __syncthreads();

        if (wave == 0u) {
            float block_best_value = lane < kLogicalWaveCount
                ? shared_wave_values[lane]
                : 0.0f;
            uint32_t block_best_id = lane < kLogicalWaveCount
                ? shared_wave_ids[lane]
                : QRT_QWEN36_EXPERT_COUNT;
            for (unsigned int offset = kLogicalWaveCount / 2u;
                 offset > 0u;
                 offset /= 2u) {
                const float other_value = __shfl_down(
                    block_best_value,
                    offset,
                    kLogicalWaveSize
                );
                const uint32_t other_id = __shfl_down(
                    block_best_id,
                    offset,
                    kLogicalWaveSize
                );
                if (lane + offset < kLogicalWaveCount &&
                    moe_router_topk_candidate_better(
                        other_value,
                        other_id,
                        block_best_value,
                        block_best_id
                    )) {
                    block_best_value = other_value;
                    block_best_id = other_id;
                }
            }
            if (lane == 0u) {
                shared_best_ids[route] = block_best_id;
                topk_ids[route] = block_best_id;
            }
        }
        __syncthreads();
        selected = selected || expert == shared_best_ids[route];
    }

    if (expert == 0u) {
        double exp_values[QRT_QWEN36_EXPERTS_PER_TOKEN];
        double max_value = -1.0e300;
        double denom = 0.0;
        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            const uint32_t best_expert = shared_best_ids[route];
            if (static_cast<double>(shared_logits[best_expert]) > max_value) {
                max_value = static_cast<double>(shared_logits[best_expert]);
            }
        }
        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            const double route_exp = exp(
                static_cast<double>(
                    shared_logits[shared_best_ids[route]]
                ) - max_value
            );
            exp_values[route] = route_exp;
            denom += route_exp;
        }
        for (unsigned int route = 0u;
             route < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route) {
            topk_weights[route] =
                static_cast<float>(exp_values[route] / denom);
        }
    }
}

// Pair every primary route with exactly one alternate route.  Matching expert
// IDs take priority regardless of rank; the remaining disjoint routes are
// paired in their original relative order.  The selected gate/up kernel can
// then reuse a weight row across rank changes while still storing each
// alternate activation in its original route slot.
__global__ void q1_moe_paired_route_permutation_kernel(
    const uint32_t *topk0_ids,
    const uint32_t *topk1_ids,
    uint32_t *route1_for_route0
) {
    if (blockIdx.x != 0u || threadIdx.x != 0u) {
        return;
    }
    bool route1_used[QRT_QWEN36_EXPERTS_PER_TOKEN] = {};
    for (unsigned int route0 = 0u;
         route0 < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route0) {
        route1_for_route0[route0] = UINT_MAX;
        for (unsigned int route1 = 0u;
             route1 < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route1) {
            if (!route1_used[route1] &&
                topk0_ids[route0] == topk1_ids[route1]) {
                route1_for_route0[route0] = route1;
                route1_used[route1] = true;
                break;
            }
        }
    }
    unsigned int next_unused_route1 = 0u;
    for (unsigned int route0 = 0u;
         route0 < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route0) {
        if (route1_for_route0[route0] != UINT_MAX) {
            continue;
        }
        while (next_unused_route1 < QRT_QWEN36_EXPERTS_PER_TOKEN &&
               route1_used[next_unused_route1]) {
            ++next_unused_route1;
        }
        if (next_unused_route1 < QRT_QWEN36_EXPERTS_PER_TOKEN) {
            route1_for_route0[route0] = next_unused_route1;
            route1_used[next_unused_route1] = true;
        }
    }
}

__global__ void routed_expert_gate_up_activation_kernel(
    const float *selected_inputs,
    const uint16_t *gate_up_weights,
    const uint32_t *route_expert_slot_indices,
    const float *topk_weights,
    float *activated,
    unsigned int route_count,
    int scale_after_down,
    int cpu_reference_arithmetic,
    int disable_fma
) {
    __shared__ float gate_partial[kThreads];
    __shared__ float up_partial[kThreads];

    const unsigned int route_index = blockIdx.x;
    const unsigned int inter = blockIdx.y;
    const unsigned int lane = threadIdx.x;
    if (route_index >= route_count || inter >= QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) {
        return;
    }

    const unsigned int token_index = route_index / QRT_QWEN36_EXPERTS_PER_TOKEN;
    const unsigned int expert_slot = route_expert_slot_indices[route_index];
    const float *input = selected_inputs + static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE;
    const uint16_t *gate_up_base =
        gate_up_weights +
        static_cast<size_t>(expert_slot) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint16_t *gate_row = gate_up_base + static_cast<size_t>(inter) * QRT_QWEN36_HIDDEN_SIZE;
    const uint16_t *up_row =
        gate_up_base +
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter) *
            QRT_QWEN36_HIDDEN_SIZE;

    if (cpu_reference_arithmetic) {
        float gate_acc = 0.0f;
        float up_acc = 0.0f;
        if (lane < kRoutedCpuReferenceAccumulatorLanes) {
            for (unsigned int col = lane;
                 col < QRT_QWEN36_HIDDEN_SIZE;
                 col += kRoutedCpuReferenceAccumulatorLanes) {
                const float input_value = input[col];
                const float gate_weight = device_bf16_to_float(gate_row[col]);
                const float up_weight = device_bf16_to_float(up_row[col]);
                (void)disable_fma;
                gate_acc = device_mul_add_separate(gate_acc, input_value, gate_weight);
                up_acc = device_mul_add_separate(up_acc, input_value, up_weight);
            }
        }
        gate_partial[lane] = gate_acc;
        up_partial[lane] = up_acc;
        __syncthreads();

        if (lane == 0u) {
            float gate = 0.0f;
            float up = 0.0f;
            for (unsigned int idx = 0; idx < kRoutedCpuReferenceAccumulatorLanes; ++idx) {
                gate += gate_partial[idx];
                up += up_partial[idx];
            }
            const float value = device_cpu_reference_silu_times_up(gate, up);
            activated[static_cast<size_t>(route_index) *
                          QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                      inter] =
                scale_after_down ? value : topk_weights[route_index] * value;
        }
        return;
    }

    float gate_acc = 0.0f;
    float up_acc = 0.0f;
    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE; col += blockDim.x) {
        const float input_value = input[col];
        gate_acc += input_value * device_bf16_to_float(gate_row[col]);
        up_acc += input_value * device_bf16_to_float(up_row[col]);
    }
    gate_partial[lane] = gate_acc;
    up_partial[lane] = up_acc;
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            gate_partial[lane] += gate_partial[lane + stride];
            up_partial[lane] += up_partial[lane + stride];
        }
        __syncthreads();
    }

    if (lane == 0u) {
        const float value = device_silu_f32(gate_partial[0]) * up_partial[0];
        activated[static_cast<size_t>(route_index) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter] =
            scale_after_down ? value : topk_weights[route_index] * value;
    }
}

