                    device_bf16_to_float(gate_weight)
                );
                up_acc = device_mul_add_separate(
                    up_acc,
                    input_value,
                    device_bf16_to_float(up_weight)
                );
            }
        }
        gate_partial[local_inter][k_lane] = gate_acc;
        up_partial[local_inter][k_lane] = up_acc;
        __syncthreads();

        if (k_lane == 0u) {
            float gate = 0.0f;
            float up = 0.0f;
            for (unsigned int idx = 0; idx < kRoutedCpuReferenceAccumulatorLanes; ++idx) {
                gate += gate_partial[local_inter][idx];
                up += up_partial[local_inter][idx];
            }
            const float value = device_cpu_reference_silu_times_up(gate, up);
            activated[static_cast<size_t>(route_index) *
                          QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                      inter] =
                scale_after_down ? value : topk_weights[route_index] * value;
        }
        return;
    }

    float gate_acc = 0.0f;
    float up_acc = 0.0f;
    for (unsigned int col_base = 0;
         col_base < QRT_QWEN36_HIDDEN_SIZE;
         col_base += kRoutedGateUpKThreads) {
        const unsigned int col = col_base + k_lane;
        if (col < QRT_QWEN36_HIDDEN_SIZE) {
            const float input_value = input[col];
            const uint32_t packed_weights = gate_up_row[col];
            const uint16_t gate_weight =
                static_cast<uint16_t>(packed_weights & 0xffffu);
            const uint16_t up_weight =
                static_cast<uint16_t>(packed_weights >> 16);
            gate_acc += input_value * device_bf16_to_float(gate_weight);
            up_acc += input_value * device_bf16_to_float(up_weight);
        }
    }

    gate_partial[local_inter][k_lane] = gate_acc;
    up_partial[local_inter][k_lane] = up_acc;
    __syncthreads();

    for (unsigned int stride = kRoutedGateUpKThreads / 2u;
         stride > 0u;
         stride >>= 1u) {
        if (k_lane < stride) {
            gate_partial[local_inter][k_lane] +=
                gate_partial[local_inter][k_lane + stride];
            up_partial[local_inter][k_lane] +=
                up_partial[local_inter][k_lane + stride];
        }
        __syncthreads();
    }

    if (k_lane == 0u) {
        const float value =
            device_silu_f32(gate_partial[local_inter][0]) *
            up_partial[local_inter][0];
        activated[static_cast<size_t>(route_index) *
                      QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                      inter] =
            scale_after_down ? value : topk_weights[route_index] * value;
    }
}

__global__ void routed_expert_gate_up_activation_exact_route_tile_pair_ptr_kernel(
    const float *__restrict__ selected_inputs,
    const uint32_t *const *__restrict__ gate_up_weight_pair_ptrs,
    const uint32_t *__restrict__ gate_up_route_indices,
    const uint32_t *__restrict__ route_expert_slot_indices,
    const float *__restrict__ topk_weights,
    float *__restrict__ activated,
    unsigned int route_count,
    int scale_after_down,
    int disable_fma
) {
    const unsigned int local_route = threadIdx.x;
    const unsigned int local_inter = threadIdx.y;
    const unsigned int route_order_index =
        blockIdx.x * kRoutedExactGateUpRouteTile + local_route;
    const unsigned int inter =
        blockIdx.y * kRoutedGateUpTileRows + local_inter;
    if (route_order_index >= route_count ||
        inter >= QRT_QWEN36_MOE_EXPERT_INTERMEDIATE ||
        local_route >= kRoutedExactGateUpRouteTile ||
        local_inter >= kRoutedGateUpTileRows) {
        return;
    }

    const unsigned int route_index = gate_up_route_indices[route_order_index];
    const unsigned int token_index = route_index / QRT_QWEN36_EXPERTS_PER_TOKEN;
    const unsigned int expert_slot = route_expert_slot_indices[route_index];
    const uint32_t *gate_up_base = gate_up_weight_pair_ptrs[expert_slot];
    if (gate_up_base == nullptr) {
        return;
    }

    const float *input =
        selected_inputs + static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE;
    const uint32_t *gate_up_row =
        gate_up_base + static_cast<size_t>(inter) * QRT_QWEN36_HIDDEN_SIZE;
    float gate_acc = 0.0f;
    float up_acc = 0.0f;
    for (unsigned int col = 0; col < QRT_QWEN36_HIDDEN_SIZE; ++col) {
        const float input_value = input[col];
        const uint32_t packed_weights = gate_up_row[col];
        const uint16_t gate_weight =
            static_cast<uint16_t>(packed_weights & 0xffffu);
        const uint16_t up_weight =
            static_cast<uint16_t>(packed_weights >> 16);
        (void)disable_fma;
        gate_acc = device_mul_add_separate(
            gate_acc,
            input_value,
            device_bf16_to_float(gate_weight)
        );
        up_acc = device_mul_add_separate(
            up_acc,
            input_value,
            device_bf16_to_float(up_weight)
        );
    }
    const float value = device_cpu_reference_silu_times_up(gate_acc, up_acc);
    activated[
        static_cast<size_t>(route_index) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
        inter
    ] = scale_after_down ? value : topk_weights[route_index] * value;
}

__global__ void routed_expert_down_accumulate_kernel(
    const float *activated,
    const uint16_t *down_weights,
    const uint32_t *route_expert_slot_indices,
    const float *topk_weights,
    float *outputs,
    unsigned int selected_token_count,
    int scale_after_down,
    int cpu_reference_arithmetic,
    int disable_fma
) {
    __shared__ float partial[kThreads];

    const unsigned int token_index = blockIdx.x;
    const unsigned int row = blockIdx.y;
    const unsigned int lane = threadIdx.x;
    if (token_index >= selected_token_count || row >= QRT_QWEN36_HIDDEN_SIZE) {
        return;
    }

    if (cpu_reference_arithmetic) {
        float total = 0.0f;
        for (unsigned int route = 0; route < QRT_QWEN36_EXPERTS_PER_TOKEN; ++route) {
            const unsigned int route_index =
                token_index * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
            const unsigned int expert_slot = route_expert_slot_indices[route_index];
            float route_sum = 0.0f;
            if (lane < kRoutedCpuReferenceAccumulatorLanes) {
                for (unsigned int inter = lane;
                     inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
                     inter += kRoutedCpuReferenceAccumulatorLanes) {
                    const float activated_value =
                        activated[static_cast<size_t>(route_index) *
                                      QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                                  inter];
                    const uint16_t weight_bits =
                        down_weights[
                            static_cast<size_t>(expert_slot) *
                                QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT +
                            static_cast<size_t>(row) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ];
                    const float weight = device_bf16_to_float(weight_bits);
                    (void)disable_fma;
                    route_sum =
                        device_mul_add_separate(route_sum, activated_value, weight);
                }
            }
            partial[lane] = route_sum;
            __syncthreads();

            if (lane == 0u) {
                float route_total = 0.0f;
                for (unsigned int idx = 0; idx < kRoutedCpuReferenceAccumulatorLanes; ++idx) {
                    route_total += partial[idx];
                }
                if (scale_after_down) {
#if QRT_X86_AVX2_ENABLED
                    total = device_mul_add_separate(
                        total,
                        topk_weights[route_index],
                        route_total
                    );
#else
                    total += static_cast<float>(
                        static_cast<double>(topk_weights[route_index]) *
                        static_cast<double>(route_total)
                    );
#endif
                } else {
                    total += route_total;
                }
            }
            __syncthreads();
        }

        if (lane == 0u) {
            outputs[static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row] =
                total;
        }
        return;
    }

    float sum = 0.0f;
    const unsigned int route_intermediate_count =
        QRT_QWEN36_EXPERTS_PER_TOKEN * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    for (unsigned int idx = lane; idx < route_intermediate_count; idx += blockDim.x) {
        const unsigned int route = idx / QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const unsigned int inter = idx % QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const unsigned int route_index = token_index * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
        const unsigned int expert_slot = route_expert_slot_indices[route_index];
        const float activated_value =
            activated[static_cast<size_t>(route_index) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter];
        const float scaled_activated =
            scale_after_down ? topk_weights[route_index] * activated_value : activated_value;
        const uint16_t weight_bits =
            down_weights[
                static_cast<size_t>(expert_slot) *
                    QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT +
                static_cast<size_t>(row) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                inter
            ];
        sum += scaled_activated * device_bf16_to_float(weight_bits);
    }
    partial[lane] = sum;
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            partial[lane] += partial[lane + stride];
        }
        __syncthreads();
    }

    if (lane == 0u) {
        outputs[static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row] =
            partial[0];
    }
}

// Exact early-layer F32 routed MoE with one independent output row per
// thread.  Each row preserves the legacy scalar column/route order and
// separate multiply/add operations; only the ownership of independent rows
// changes, eliminating the 255 idle lanes in every legacy block.
__global__ void routed_expert_gate_up_activation_exact_f32_row_tile_kernel(
    const float *__restrict__ selected_input,
    const uint16_t *__restrict__ gate_up_weights,
    const uint32_t *__restrict__ route_expert_slot_indices,
    const float *__restrict__ topk_weights,
    float *__restrict__ activated,
    unsigned int route_count,
    int scale_after_down
) {
    const unsigned int route_index = blockIdx.x;
    const unsigned int inter =
        blockIdx.y * blockDim.x + threadIdx.x;
    if (route_index >= route_count ||
        inter >= QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) {
        return;
    }

    const unsigned int expert_slot =
        route_expert_slot_indices[route_index];
    const uint16_t *gate_up_base =
        gate_up_weights +
        static_cast<size_t>(expert_slot) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint16_t *gate_row =
        gate_up_base +
        static_cast<size_t>(inter) * QRT_QWEN36_HIDDEN_SIZE;
    const uint16_t *up_row =
        gate_up_base +
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter) *
            QRT_QWEN36_HIDDEN_SIZE;
    float gate = 0.0f;
    float up = 0.0f;
    for (unsigned int col = 0u;
         col < QRT_QWEN36_HIDDEN_SIZE;
         ++col) {
        const float input_value = selected_input[col];
        gate = device_mul_add_separate(
            gate,
            input_value,
            device_bf16_to_float(gate_row[col])
        );
        up = device_mul_add_separate(
            up,
            input_value,
            device_bf16_to_float(up_row[col])
        );
    }
    const float value = device_cpu_reference_silu_times_up(gate, up);
    activated[
        static_cast<size_t>(route_index) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
        inter
    ] = scale_after_down ? value : topk_weights[route_index] * value;
}

__global__ void routed_expert_down_accumulate_exact_f32_row_tile_kernel(
    const float *__restrict__ activated,
    const uint16_t *__restrict__ down_weights,
    const uint32_t *__restrict__ route_expert_slot_indices,
    const float *__restrict__ topk_weights,
    float *__restrict__ outputs,
    unsigned int route_count,
    int scale_after_down
) {
    const unsigned int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= QRT_QWEN36_HIDDEN_SIZE) {
        return;
    }

    float total = 0.0f;
    for (unsigned int route = 0u; route < route_count; ++route) {
        const unsigned int expert_slot =
            route_expert_slot_indices[route];
        const float *route_activated =
            activated +
            static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const uint16_t *down_row =
            down_weights +
            static_cast<size_t>(expert_slot) *
                QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT +
            static_cast<size_t>(row) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        float route_total = 0.0f;
        for (unsigned int inter = 0u;
             inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
             ++inter) {
            route_total = device_mul_add_separate(
                route_total,
                route_activated[inter],
                device_bf16_to_float(down_row[inter])
            );
        }
        if (scale_after_down) {
#if QRT_X86_AVX2_ENABLED
            total = device_mul_add_separate(
                total,
                topk_weights[route],
                route_total
            );
#else
            total += static_cast<float>(
                static_cast<double>(topk_weights[route]) *
                static_cast<double>(route_total)
            );
#endif
        } else {
            total += route_total;
        }
    }
    outputs[row] = total;
}

