__global__ void routed_expert_down_accumulate_row_tile_kernel(
    const float *__restrict__ activated,
    const uint32_t *__restrict__ down_weight_row_pairs,
    const uint32_t *__restrict__ route_expert_slot_indices,
    const uint32_t *__restrict__ down_token_indices,
    const uint32_t *__restrict__ down_route_indices,
    const float *topk_weights,
    float *__restrict__ outputs,
    unsigned int selected_token_count,
    int scale_after_down,
    int cpu_reference_arithmetic,
    int disable_fma
) {
    __shared__ float cpu_route_sum0[kThreadTileRows][kRoutedDownTileK];
    __shared__ float cpu_route_sum1[kThreadTileRows][kRoutedDownTileK];
    __shared__ float cpu_route_sum2[kThreadTileRows][kRoutedDownTileK];
    __shared__ float cpu_route_sum3[kThreadTileRows][kRoutedDownTileK];

    const unsigned int k_lane = threadIdx.x;
    const unsigned int local_row = threadIdx.y;
    const unsigned int row0 = blockIdx.x * kRoutedDownTileRows + local_row;
    const unsigned int row1 = row0 + kThreadTileRows;
    const unsigned int row2 = row0 + 2u * kThreadTileRows;
    const unsigned int row3 = row0 + 3u * kThreadTileRows;
    const unsigned int token_order_index = blockIdx.y;
    if (token_order_index >= selected_token_count ||
        local_row >= kThreadTileRows ||
        k_lane >= kRoutedDownTileK) {
        return;
    }

    const unsigned int token_index = down_token_indices[token_order_index];
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    float sum2 = 0.0f;
    float sum3 = 0.0f;
    const uint32_t *token_route_order =
        down_route_indices +
        static_cast<size_t>(token_index) * QRT_QWEN36_EXPERTS_PER_TOKEN;
    if (cpu_reference_arithmetic) {
        for (unsigned int route_order = 0;
             route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route_order) {
            const unsigned int route = token_route_order[route_order];
            const unsigned int route_index =
                token_index * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
            const unsigned int expert_slot = route_expert_slot_indices[route_index];
            const size_t packed_base0 =
                static_cast<size_t>(expert_slot) * kRoutedDownPackedPairsPerExpert +
                ((static_cast<size_t>(blockIdx.x) *
                      kRoutedDownPackedRowPairGroups *
                      kThreadTileRows) +
                 local_row) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            const size_t packed_base1 =
                packed_base0 +
                static_cast<size_t>(kThreadTileRows) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            float route_sum0 = 0.0f;
            float route_sum1 = 0.0f;
            float route_sum2 = 0.0f;
            float route_sum3 = 0.0f;
            if (k_lane < kRoutedCpuReferenceAccumulatorLanes) {
                for (unsigned int inter = k_lane;
                     inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
                     inter += kRoutedCpuReferenceAccumulatorLanes) {
                    const float activated_value =
                        activated[
                            static_cast<size_t>(route_index) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ];
                    const uint32_t packed_weights0 =
                        down_weight_row_pairs[packed_base0 + inter];
                    const uint32_t packed_weights1 =
                        down_weight_row_pairs[packed_base1 + inter];
                    const uint16_t weight0 =
                        static_cast<uint16_t>(packed_weights0 & 0xffffu);
                    const uint16_t weight1 =
                        static_cast<uint16_t>(packed_weights0 >> 16);
                    const uint16_t weight2 =
                        static_cast<uint16_t>(packed_weights1 & 0xffffu);
                    const uint16_t weight3 =
                        static_cast<uint16_t>(packed_weights1 >> 16);
                    const float weight_value0 = device_bf16_to_float(weight0);
                    const float weight_value1 = device_bf16_to_float(weight1);
                    const float weight_value2 = device_bf16_to_float(weight2);
                    const float weight_value3 = device_bf16_to_float(weight3);
                    (void)disable_fma;
                    route_sum0 = device_mul_add_separate(
                        route_sum0,
                        activated_value,
                        weight_value0
                    );
                    route_sum1 = device_mul_add_separate(
                        route_sum1,
                        activated_value,
                        weight_value1
                    );
                    route_sum2 = device_mul_add_separate(
                        route_sum2,
                        activated_value,
                        weight_value2
                    );
                    route_sum3 = device_mul_add_separate(
                        route_sum3,
                        activated_value,
                        weight_value3
                    );
                }
            }
            cpu_route_sum0[local_row][k_lane] = route_sum0;
            cpu_route_sum1[local_row][k_lane] = route_sum1;
            cpu_route_sum2[local_row][k_lane] = route_sum2;
            cpu_route_sum3[local_row][k_lane] = route_sum3;
            __syncthreads();

            if (k_lane == 0u) {
                float route_total0 = 0.0f;
                float route_total1 = 0.0f;
                float route_total2 = 0.0f;
                float route_total3 = 0.0f;
                for (unsigned int idx = 0; idx < kRoutedCpuReferenceAccumulatorLanes; ++idx) {
                    route_total0 += cpu_route_sum0[local_row][idx];
                    route_total1 += cpu_route_sum1[local_row][idx];
                    route_total2 += cpu_route_sum2[local_row][idx];
                    route_total3 += cpu_route_sum3[local_row][idx];
                }
                const float scale = topk_weights[route_index];
                if (scale_after_down) {
#if QRT_X86_AVX2_ENABLED
                    sum0 = device_mul_add_separate(
                        sum0,
                        scale,
                        route_total0
                    );
                    sum1 = device_mul_add_separate(
                        sum1,
                        scale,
                        route_total1
                    );
                    sum2 = device_mul_add_separate(
                        sum2,
                        scale,
                        route_total2
                    );
                    sum3 = device_mul_add_separate(
                        sum3,
                        scale,
                        route_total3
