                sum3 = device_mul_add_separate(
                    sum3,
                    activated_value,
                    weights1.y
                );
            }
        }
        __syncthreads();
    }

    if (route_valid) {
        route_outputs[
            static_cast<size_t>(route_index) * QRT_QWEN36_HIDDEN_SIZE + row0
        ] = sum0;
        route_outputs[
            static_cast<size_t>(route_index) * QRT_QWEN36_HIDDEN_SIZE + row1
        ] = sum1;
        route_outputs[
            static_cast<size_t>(route_index) * QRT_QWEN36_HIDDEN_SIZE + row2
        ] = sum2;
        route_outputs[
            static_cast<size_t>(route_index) * QRT_QWEN36_HIDDEN_SIZE + row3
        ] = sum3;
    }
}

__global__ void routed_expert_down_route_output_exact_combine_kernel(
    const float *__restrict__ route_outputs,
    const uint32_t *__restrict__ down_route_indices,
    const float *__restrict__ topk_weights,
    float *__restrict__ outputs,
    unsigned int selected_token_count,
    int scale_after_down
) {
    const size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const size_t total_elements =
        static_cast<size_t>(selected_token_count) * QRT_QWEN36_HIDDEN_SIZE;
    if (idx >= total_elements) {
        return;
    }
    const unsigned int token_index =
        static_cast<unsigned int>(idx / QRT_QWEN36_HIDDEN_SIZE);
    const unsigned int row =
        static_cast<unsigned int>(idx - static_cast<size_t>(token_index) *
            QRT_QWEN36_HIDDEN_SIZE);
    float total = 0.0f;
    for (unsigned int route_order = 0u;
         route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route_order) {
        const unsigned int route =
            down_route_indices[
                static_cast<size_t>(token_index) *
                    QRT_QWEN36_EXPERTS_PER_TOKEN +
                route_order
            ];
        const unsigned int route_index =
            token_index * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
        const float route_total =
            route_outputs[
                static_cast<size_t>(route_index) * QRT_QWEN36_HIDDEN_SIZE +
                row
            ];
        if (scale_after_down) {
#if QRT_X86_AVX2_ENABLED
            total = device_mul_add_separate(
                total,
                topk_weights[route_index],
                route_total
            );
#else
            total += static_cast<float>(
                static_cast<double>(topk_weights[route_index]) *
                static_cast<double>(route_total)
            );
#endif
        } else {
            total += route_total;
        }
    }
    outputs[idx] = total;
}

__global__ void routed_expert_down_route_order_grouped_exact_pair_ptr_kernel(
    const float *__restrict__ activated,
    const uint32_t *const *__restrict__ down_weight_pair_ptrs,
    const uint32_t *__restrict__ route_order_route_indices,
    const uint32_t *__restrict__ route_order_tile_expert_slots,
    const uint32_t *__restrict__ route_order_tile_route_offsets,
    const uint32_t *__restrict__ route_order_tile_route_counts,
    const float *__restrict__ topk_weights,
    float *__restrict__ outputs,
    unsigned int group_tile_offset,
    unsigned int group_tile_count,
    unsigned int route_order,
    int scale_after_down,
    int disable_fma
) {
    __shared__ uint32_t weight_tile0[kThreadTileRows][kRoutedGroupedExactKTile];
    __shared__ uint32_t weight_tile1[kThreadTileRows][kRoutedGroupedExactKTile];

    const unsigned int local_route = threadIdx.x;
    const unsigned int local_row = threadIdx.y;
    const unsigned int group_tile = group_tile_offset + blockIdx.x;
    const unsigned int row0 = blockIdx.y * kRoutedDownTileRows + local_row;
    const unsigned int row1 = row0 + kThreadTileRows;
    const unsigned int row2 = row0 + 2u * kThreadTileRows;
    const unsigned int row3 = row0 + 3u * kThreadTileRows;
    if (blockIdx.x >= group_tile_count ||
        local_route >= kRoutedGroupedExactRouteTile ||
        local_row >= kThreadTileRows) {
        return;
    }

    const unsigned int expert_slot =
        route_order_tile_expert_slots[group_tile];
    const unsigned int tile_route_count =
        route_order_tile_route_counts[group_tile];
    const bool route_valid = local_route < tile_route_count;
    const unsigned int route_order_index =
        route_order_tile_route_offsets[group_tile] + local_route;
    const unsigned int route_index =
        route_valid ? route_order_route_indices[route_order_index] : 0u;
    const unsigned int token_index =
        route_valid ? route_index / QRT_QWEN36_EXPERTS_PER_TOKEN : 0u;
    const uint32_t *down_base = down_weight_pair_ptrs[expert_slot];
    if (down_base == nullptr) {
        return;
    }
    const size_t packed_base0 =
        ((static_cast<size_t>(blockIdx.y) *
              kRoutedDownPackedRowPairGroups *
              kThreadTileRows) +
         local_row) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const size_t packed_base1 =
        packed_base0 +
        static_cast<size_t>(kThreadTileRows) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;

    float sum0 = 0.0f;
    float sum1 = 0.0f;
    float sum2 = 0.0f;
    float sum3 = 0.0f;
    for (unsigned int inter_base = 0u;
         inter_base < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
         inter_base += kRoutedGroupedExactKTile) {
        const unsigned int inter_for_weight = inter_base + local_route;
        weight_tile0[local_row][local_route] =
            down_base[packed_base0 + inter_for_weight];
        weight_tile1[local_row][local_route] =
            down_base[packed_base1 + inter_for_weight];
        __syncthreads();

        if (route_valid) {
            #pragma unroll
            for (unsigned int k = 0u; k < kRoutedGroupedExactKTile; ++k) {
                const unsigned int inter = inter_base + k;
                const float activated_value =
                    activated[
                        static_cast<size_t>(route_index) *
                            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                        inter
                    ];
                const uint32_t packed_weights0 = weight_tile0[local_row][k];
                const uint32_t packed_weights1 = weight_tile1[local_row][k];
                const uint16_t weight0 =
                    static_cast<uint16_t>(packed_weights0 & 0xffffu);
                const uint16_t weight1 =
                    static_cast<uint16_t>(packed_weights0 >> 16);
                const uint16_t weight2 =
                    static_cast<uint16_t>(packed_weights1 & 0xffffu);
                const uint16_t weight3 =
                    static_cast<uint16_t>(packed_weights1 >> 16);
                (void)disable_fma;
                sum0 = device_mul_add_separate(
                    sum0,
                    activated_value,
                    device_bf16_to_float(weight0)
                );
                sum1 = device_mul_add_separate(
                    sum1,
                    activated_value,
                    device_bf16_to_float(weight1)
                );
                sum2 = device_mul_add_separate(
                    sum2,
                    activated_value,
                    device_bf16_to_float(weight2)
                );
                sum3 = device_mul_add_separate(
                    sum3,
                    activated_value,
                    device_bf16_to_float(weight3)
                );
            }
        }
        __syncthreads();
    }

    if (!route_valid) {
        return;
    }

    const float scale = topk_weights[route_index];
    const size_t output_base =
        static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE;
    const size_t output_index0 = output_base + row0;
    const size_t output_index1 = output_base + row1;
    const size_t output_index2 = output_base + row2;
    const size_t output_index3 = output_base + row3;
    if (scale_after_down) {
        if (route_order == 0u) {
            outputs[output_index0] =
                device_mul_add_separate(0.0f, scale, sum0);
            outputs[output_index1] =
                device_mul_add_separate(0.0f, scale, sum1);
            outputs[output_index2] =
                device_mul_add_separate(0.0f, scale, sum2);
            outputs[output_index3] =
                device_mul_add_separate(0.0f, scale, sum3);
        } else {
            outputs[output_index0] =
                device_mul_add_separate(outputs[output_index0], scale, sum0);
            outputs[output_index1] =
                device_mul_add_separate(outputs[output_index1], scale, sum1);
            outputs[output_index2] =
                device_mul_add_separate(outputs[output_index2], scale, sum2);
            outputs[output_index3] =
                device_mul_add_separate(outputs[output_index3], scale, sum3);
        }
    } else if (route_order == 0u) {
        outputs[output_index0] = sum0;
        outputs[output_index1] = sum1;
        outputs[output_index2] = sum2;
        outputs[output_index3] = sum3;
    } else {
        outputs[output_index0] += sum0;
        outputs[output_index1] += sum1;
        outputs[output_index2] += sum2;
        outputs[output_index3] += sum3;
    }
}

__global__ void routed_expert_down_accumulate_row_tile_ptr_kernel(
    const float *__restrict__ activated,
    const uint16_t *const *__restrict__ down_weight_ptrs,
    const uint32_t *__restrict__ route_expert_slot_indices,
    const uint32_t *__restrict__ down_token_indices,
    const uint32_t *__restrict__ down_route_indices,
    const float *topk_weights,
    float *__restrict__ outputs,
    unsigned int selected_token_count,
    int scale_after_down,
    int cpu_reference_arithmetic,
    int disable_fma
) {
    __shared__ float cpu_route_sum0[kThreadTileRows][kRoutedDownTileK];
    __shared__ float cpu_route_sum1[kThreadTileRows][kRoutedDownTileK];
    __shared__ float cpu_route_sum2[kThreadTileRows][kRoutedDownTileK];
    __shared__ float cpu_route_sum3[kThreadTileRows][kRoutedDownTileK];

    const unsigned int k_lane = threadIdx.x;
    const unsigned int local_row = threadIdx.y;
    const unsigned int row0 = blockIdx.x * kRoutedDownTileRows + local_row;
    const unsigned int row1 = row0 + kThreadTileRows;
    const unsigned int row2 = row0 + 2u * kThreadTileRows;
    const unsigned int row3 = row0 + 3u * kThreadTileRows;
    const unsigned int token_order_index = blockIdx.y;
    if (token_order_index >= selected_token_count ||
        local_row >= kThreadTileRows ||
        k_lane >= kRoutedDownTileK) {
        return;
    }

    const unsigned int token_index = down_token_indices[token_order_index];
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    float sum2 = 0.0f;
    float sum3 = 0.0f;
    const uint32_t *token_route_order =
        down_route_indices +
        static_cast<size_t>(token_index) * QRT_QWEN36_EXPERTS_PER_TOKEN;
    if (cpu_reference_arithmetic) {
        for (unsigned int route_order = 0;
             route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route_order) {
            const unsigned int route = token_route_order[route_order];
            const unsigned int route_index =
                token_index * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
            const unsigned int expert_slot = route_expert_slot_indices[route_index];
            const uint16_t *down_base = down_weight_ptrs[expert_slot];
            float route_sum0 = 0.0f;
            float route_sum1 = 0.0f;
            float route_sum2 = 0.0f;
            float route_sum3 = 0.0f;
            if (k_lane < kRoutedCpuReferenceAccumulatorLanes) {
                for (unsigned int inter = k_lane;
                     inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
                     inter += kRoutedCpuReferenceAccumulatorLanes) {
                    const float activated_value =
                        activated[
                            static_cast<size_t>(route_index) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ];
                    const float weight_value0 = device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row0) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                    const float weight_value1 = device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row1) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                    const float weight_value2 = device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row2) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                    const float weight_value3 = device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row3) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                    (void)disable_fma;
                    route_sum0 = device_mul_add_separate(
                        route_sum0,
                        activated_value,
                        weight_value0
                    );
                    route_sum1 = device_mul_add_separate(
                        route_sum1,
                        activated_value,
                        weight_value1
                    );
                    route_sum2 = device_mul_add_separate(
                        route_sum2,
                        activated_value,
                        weight_value2
                    );
                    route_sum3 = device_mul_add_separate(
                        route_sum3,
                        activated_value,
                        weight_value3
                    );
                }
            }
            cpu_route_sum0[local_row][k_lane] = route_sum0;
            cpu_route_sum1[local_row][k_lane] = route_sum1;
            cpu_route_sum2[local_row][k_lane] = route_sum2;
            cpu_route_sum3[local_row][k_lane] = route_sum3;
            __syncthreads();

            if (k_lane == 0u) {
                float route_total0 = 0.0f;
                float route_total1 = 0.0f;
                float route_total2 = 0.0f;
                float route_total3 = 0.0f;
                for (unsigned int idx = 0; idx < kRoutedCpuReferenceAccumulatorLanes; ++idx) {
                    route_total0 += cpu_route_sum0[local_row][idx];
                    route_total1 += cpu_route_sum1[local_row][idx];
                    route_total2 += cpu_route_sum2[local_row][idx];
                    route_total3 += cpu_route_sum3[local_row][idx];
                }
                const float scale = topk_weights[route_index];
                if (scale_after_down) {
#if QRT_X86_AVX2_ENABLED
                    sum0 = device_mul_add_separate(sum0, scale, route_total0);
                    sum1 = device_mul_add_separate(sum1, scale, route_total1);
                    sum2 = device_mul_add_separate(sum2, scale, route_total2);
                    sum3 = device_mul_add_separate(sum3, scale, route_total3);
#else
                    sum0 += static_cast<float>(
                        static_cast<double>(scale) *
                        static_cast<double>(route_total0)
                    );
                    sum1 += static_cast<float>(
                        static_cast<double>(scale) *
                        static_cast<double>(route_total1)
                    );
                    sum2 += static_cast<float>(
                        static_cast<double>(scale) *
                        static_cast<double>(route_total2)
                    );
                    sum3 += static_cast<float>(
                        static_cast<double>(scale) *
                        static_cast<double>(route_total3)
                    );
#endif
                } else {
                    sum0 += route_total0;
                    sum1 += route_total1;
                    sum2 += route_total2;
                    sum3 += route_total3;
                }
            }
            __syncthreads();
        }
    } else if (scale_after_down) {
        for (unsigned int route_order = 0;
             route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route_order) {
            const unsigned int route = token_route_order[route_order];
            const unsigned int route_index =
                token_index * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
            const unsigned int expert_slot = route_expert_slot_indices[route_index];
            const uint16_t *down_base = down_weight_ptrs[expert_slot];
            float route_sum0 = 0.0f;
            float route_sum1 = 0.0f;
            float route_sum2 = 0.0f;
            float route_sum3 = 0.0f;
            for (unsigned int inter_base = 0;
                 inter_base < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
                 inter_base += kRoutedDownTileK) {
                const unsigned int inter = inter_base + k_lane;
                const float activated_value =
                    activated[
                        static_cast<size_t>(route_index) *
                            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                        inter
                    ];
                route_sum0 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row0) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                route_sum1 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row1) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                route_sum2 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row2) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                route_sum3 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row3) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
            }
            const float route_total0 = device_routed_down_lane_sum(route_sum0);
            const float route_total1 = device_routed_down_lane_sum(route_sum1);
            const float route_total2 = device_routed_down_lane_sum(route_sum2);
            const float route_total3 = device_routed_down_lane_sum(route_sum3);
            if (k_lane == 0u) {
                const float scale = topk_weights[route_index];
                sum0 += static_cast<float>(
                    static_cast<double>(scale) * static_cast<double>(route_total0)
                );
                sum1 += static_cast<float>(
                    static_cast<double>(scale) * static_cast<double>(route_total1)
                );
                sum2 += static_cast<float>(
                    static_cast<double>(scale) * static_cast<double>(route_total2)
                );
                sum3 += static_cast<float>(
                    static_cast<double>(scale) * static_cast<double>(route_total3)
                );
            }
        }
    } else {
        for (unsigned int route_order = 0;
             route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route_order) {
            const unsigned int route = token_route_order[route_order];
            const unsigned int route_index =
                token_index * QRT_QWEN36_EXPERTS_PER_TOKEN + route;
            const unsigned int expert_slot = route_expert_slot_indices[route_index];
            const uint16_t *down_base = down_weight_ptrs[expert_slot];
            for (unsigned int inter_base = 0;
                 inter_base < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
                 inter_base += kRoutedDownTileK) {
                const unsigned int inter = inter_base + k_lane;
                const float activated_value =
                    activated[
                        static_cast<size_t>(route_index) *
                            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                        inter
                    ];
                sum0 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row0) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                sum1 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row1) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                sum2 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row2) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
                sum3 += activated_value *
                    device_bf16_to_float(
                        down_base[
                            static_cast<size_t>(row3) *
                                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                            inter
                        ]
                    );
            }
        }
    }

    float total0 = sum0;
    float total1 = sum1;
    float total2 = sum2;
    float total3 = sum3;
    if (!scale_after_down) {
        total0 = device_routed_down_lane_sum(sum0);
        total1 = device_routed_down_lane_sum(sum1);
        total2 = device_routed_down_lane_sum(sum2);
        total3 = device_routed_down_lane_sum(sum3);
    }
    if (k_lane == 0u) {
        outputs[static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row0] =
            total0;
        outputs[static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row1] =
            total1;
        outputs[static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row2] =
            total2;
        outputs[static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row3] =
            total3;
    }
}

__global__ void routed_expert_gate_up_activation_row_tile_probe_kernel(
    const float *selected_inputs,
    const uint32_t *__restrict__ gate_up_weight_pairs,
    const uint32_t *__restrict__ gate_up_route_indices,
    const uint32_t *route_expert_slot_indices,
    const float *topk_weights,
    float *gate_outputs,
    float *up_outputs,
    float *activated,
    unsigned int route_count,
    int cpu_reference_arithmetic,
    int disable_fma
) {
    __shared__ float gate_partial[kRoutedGateUpTileRows][kRoutedGateUpKThreads];
    __shared__ float up_partial[kRoutedGateUpTileRows][kRoutedGateUpKThreads];

    const unsigned int k_lane = threadIdx.x;
    const unsigned int local_inter = threadIdx.y;
    const unsigned int route_order_index = blockIdx.x;
    const unsigned int inter =
        blockIdx.y * kRoutedGateUpTileRows + local_inter;
    if (route_order_index >= route_count ||
        inter >= QRT_QWEN36_MOE_EXPERT_INTERMEDIATE ||
        k_lane >= kRoutedGateUpKThreads ||
        local_inter >= kRoutedGateUpTileRows) {
        return;
    }

    const unsigned int route_index = gate_up_route_indices[route_order_index];
    const unsigned int token_index = route_index / QRT_QWEN36_EXPERTS_PER_TOKEN;
    const unsigned int expert_slot = route_expert_slot_indices[route_index];
    const float *input =
        selected_inputs + static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE;
    const uint32_t *gate_up_row =
        gate_up_weight_pairs +
        static_cast<size_t>(expert_slot) * kRoutedGateUpPackedPairsPerExpert +
        static_cast<size_t>(inter) * QRT_QWEN36_HIDDEN_SIZE;

    if (cpu_reference_arithmetic) {
        float gate_acc = 0.0f;
        float up_acc = 0.0f;
        if (k_lane < kRoutedCpuReferenceAccumulatorLanes) {
            for (unsigned int col = k_lane;
                 col < QRT_QWEN36_HIDDEN_SIZE;
                 col += kRoutedCpuReferenceAccumulatorLanes) {
                const float input_value = input[col];
                const uint32_t packed_weights = gate_up_row[col];
                const uint16_t gate_weight =
                    static_cast<uint16_t>(packed_weights & 0xffffu);
                const uint16_t up_weight =
                    static_cast<uint16_t>(packed_weights >> 16);
                (void)disable_fma;
                gate_acc = device_mul_add_separate(
                    gate_acc,
                    input_value,
                    device_bf16_to_float(gate_weight)
                );
                up_acc = device_mul_add_separate(
                    up_acc,
                    input_value,
                    device_bf16_to_float(up_weight)
                );
            }
        }
        gate_partial[local_inter][k_lane] = gate_acc;
        up_partial[local_inter][k_lane] = up_acc;
        __syncthreads();

        if (k_lane == 0u) {
            float gate = 0.0f;
            float up = 0.0f;
            for (unsigned int idx = 0; idx < kRoutedCpuReferenceAccumulatorLanes; ++idx) {
                gate += gate_partial[local_inter][idx];
                up += up_partial[local_inter][idx];
            }
            const size_t output_index =
                static_cast<size_t>(route_index) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                inter;
            gate_outputs[output_index] = gate;
            up_outputs[output_index] = up;
            activated[output_index] = device_cpu_reference_silu_times_up(gate, up);
        }
        return;
    }

    float gate_acc = 0.0f;
    float up_acc = 0.0f;
    for (unsigned int col_base = 0;
         col_base < QRT_QWEN36_HIDDEN_SIZE;
         col_base += kRoutedGateUpKThreads) {
        const unsigned int col = col_base + k_lane;
        if (col < QRT_QWEN36_HIDDEN_SIZE) {
            const float input_value = input[col];
            const uint32_t packed_weights = gate_up_row[col];
            const uint16_t gate_weight =
                static_cast<uint16_t>(packed_weights & 0xffffu);
            const uint16_t up_weight =
                static_cast<uint16_t>(packed_weights >> 16);
            gate_acc += input_value * device_bf16_to_float(gate_weight);
            up_acc += input_value * device_bf16_to_float(up_weight);
        }
    }

    gate_partial[local_inter][k_lane] = gate_acc;
    up_partial[local_inter][k_lane] = up_acc;
    __syncthreads();

    for (unsigned int stride = kRoutedGateUpKThreads / 2u;
         stride > 0u;
         stride >>= 1u) {
        if (k_lane < stride) {
            gate_partial[local_inter][k_lane] +=
                gate_partial[local_inter][k_lane + stride];
            up_partial[local_inter][k_lane] +=
                up_partial[local_inter][k_lane + stride];
        }
        __syncthreads();
    }

    if (k_lane == 0u) {
        const size_t output_index =
            static_cast<size_t>(route_index) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
            inter;
        const float gate = gate_partial[local_inter][0];
        const float up = up_partial[local_inter][0];
        const float value = device_silu_f32(gate) * up;
        gate_outputs[output_index] = gate;
        up_outputs[output_index] = up;
        activated[output_index] = topk_weights[route_index] * value;
    }
}

__global__ void shared_expert_gate_kernel(
    const float *selected_inputs,
    const uint16_t *gate_weight,
    float *gate_logits,
    float *gate_scales,
    unsigned int selected_token_count
) {
    __shared__ float partial[kThreads];

    const unsigned int token_index = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (token_index >= selected_token_count) {
        return;
    }

    const float *input =
        selected_inputs + static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE;
    float sum = 0.0f;
    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE; col += blockDim.x) {
        sum += input[col] * device_bf16_to_float(gate_weight[col]);
    }
    partial[lane] = sum;
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            partial[lane] += partial[lane + stride];
        }
        __syncthreads();
    }

    if (lane == 0u) {
        const float gate_logit = partial[0];
        gate_logits[token_index] = gate_logit;
        gate_scales[token_index] = 1.0f / (1.0f + expf(-gate_logit));
    }
}

