__global__ void shared_expert_down_combine_kernel(
    const float *activated,
    const float *gate_scales,
    const uint16_t *down_weight,
    const float *routed_inputs,
    float *shared_outputs,
    float *combined_outputs,
    unsigned int selected_token_count,
    bool vllm_bf16_endpoints
) {
    __shared__ float partial[kThreads];

    const unsigned int token_index = blockIdx.x;
    const unsigned int row = blockIdx.y;
    const unsigned int lane = threadIdx.x;
    if (token_index >= selected_token_count || row >= QRT_QWEN36_HIDDEN_SIZE) {
        return;
    }

    const float *activated_token =
        activated + static_cast<size_t>(token_index) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const uint16_t *down_row =
        down_weight + static_cast<size_t>(row) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;

    float sum = 0.0f;
    for (unsigned int inter = lane; inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE; inter += blockDim.x) {
        sum += activated_token[inter] * device_bf16_to_float(down_row[inter]);
    }
    partial[lane] = sum;
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            partial[lane] += partial[lane + stride];
        }
        __syncthreads();
    }

    if (lane == 0u) {
        const size_t output_index =
            static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row;
        const float gate_scale = vllm_bf16_endpoints
            ? device_bf16_round_to_float(gate_scales[token_index])
            : gate_scales[token_index];
        const float down = vllm_bf16_endpoints
            ? device_bf16_round_to_float(partial[0])
            : partial[0];
        const float shared_value = gate_scale * down;
        const float shared = vllm_bf16_endpoints
            ? device_bf16_round_to_float(shared_value)
            : shared_value;
        const float routed = vllm_bf16_endpoints
            ? device_bf16_round_to_float(routed_inputs[output_index])
            : routed_inputs[output_index];
        shared_outputs[output_index] = shared;
        const float combined = routed + shared;
        combined_outputs[output_index] = vllm_bf16_endpoints
            ? device_bf16_round_to_float(combined)
            : combined;
    }
}

__global__ void shared_expert_down_combine_row_tile_kernel(
    const float *__restrict__ activated,
    const float *__restrict__ gate_scales,
    const uint32_t *__restrict__ down_weight_row_pairs,
    const float *__restrict__ routed_inputs,
    float *__restrict__ shared_outputs,
    float *__restrict__ combined_outputs,
    unsigned int selected_token_count
) {
    const unsigned int k_lane = threadIdx.x;
    const unsigned int local_row = threadIdx.y;
    const unsigned int row0 = blockIdx.x * kRoutedDownTileRows + local_row;
    const unsigned int row1 = row0 + kThreadTileRows;
    const unsigned int row2 = row0 + 2u * kThreadTileRows;
    const unsigned int row3 = row0 + 3u * kThreadTileRows;
    const unsigned int token_index = blockIdx.y;
    if (token_index >= selected_token_count ||
        local_row >= kThreadTileRows ||
        k_lane >= kRoutedDownTileK) {
        return;
    }

    const float *activated_token =
        activated + static_cast<size_t>(token_index) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const size_t packed_base0 =
        ((static_cast<size_t>(blockIdx.x) *
              kRoutedDownPackedRowPairGroups *
              kThreadTileRows) +
         local_row) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const size_t packed_base1 =
        packed_base0 +
        static_cast<size_t>(kThreadTileRows) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    float sum2 = 0.0f;
    float sum3 = 0.0f;
    for (unsigned int inter_base = 0;
         inter_base < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
         inter_base += kRoutedDownTileK) {
        const unsigned int inter = inter_base + k_lane;
        const uint32_t packed_weights0 = down_weight_row_pairs[packed_base0 + inter];
        const uint32_t packed_weights1 = down_weight_row_pairs[packed_base1 + inter];
        const uint16_t weight0 = static_cast<uint16_t>(packed_weights0 & 0xffffu);
        const uint16_t weight1 = static_cast<uint16_t>(packed_weights0 >> 16);
        const uint16_t weight2 = static_cast<uint16_t>(packed_weights1 & 0xffffu);
        const uint16_t weight3 = static_cast<uint16_t>(packed_weights1 >> 16);
        const float activated_value = activated_token[inter];
        sum0 += activated_value * device_bf16_to_float(weight0);
        sum1 += activated_value * device_bf16_to_float(weight1);
        sum2 += activated_value * device_bf16_to_float(weight2);
        sum3 += activated_value * device_bf16_to_float(weight3);
    }

    const float total0 = device_routed_down_lane_sum(sum0);
    const float total1 = device_routed_down_lane_sum(sum1);
    const float total2 = device_routed_down_lane_sum(sum2);
    const float total3 = device_routed_down_lane_sum(sum3);
    if (k_lane == 0u) {
        const float gate_scale = gate_scales[token_index];
        const size_t output_base =
            static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE;
        const size_t output_index0 = output_base + row0;
        const size_t output_index1 = output_base + row1;
        const size_t output_index2 = output_base + row2;
        const size_t output_index3 = output_base + row3;
        const float shared0 = gate_scale * total0;
        const float shared1 = gate_scale * total1;
        const float shared2 = gate_scale * total2;
        const float shared3 = gate_scale * total3;
        shared_outputs[output_index0] = shared0;
        shared_outputs[output_index1] = shared1;
        shared_outputs[output_index2] = shared2;
        shared_outputs[output_index3] = shared3;
        combined_outputs[output_index0] = routed_inputs[output_index0] + shared0;
        combined_outputs[output_index1] = routed_inputs[output_index1] + shared1;
        combined_outputs[output_index2] = routed_inputs[output_index2] + shared2;
        combined_outputs[output_index3] = routed_inputs[output_index3] + shared3;
    }
}

__global__ void shared_expert_down_combine_cpu_order_kernel(
    const float *activated,
    const float *gate_scales,
    const uint16_t *down_weight,
    const float *routed_inputs,
    float *shared_outputs,
    float *combined_outputs,
    unsigned int selected_token_count
) {
    const unsigned int token_index = blockIdx.y;
    const unsigned int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (token_index >= selected_token_count || row >= QRT_QWEN36_HIDDEN_SIZE) {
        return;
    }

    const float *activated_token =
        activated + static_cast<size_t>(token_index) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const uint16_t *down_row =
        down_weight + static_cast<size_t>(row) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    float value = 0.0f;
    for (unsigned int inter = 0u;
         inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
         ++inter) {
        value = device_mul_add_separate(
            value,
            activated_token[inter],
            device_bf16_to_float(down_row[inter])
        );
    }

    const size_t output_index =
        static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row;
    const float shared = device_mul_add_separate(
        0.0f,
        gate_scales[token_index],
        value
    );
    shared_outputs[output_index] = shared;
    combined_outputs[output_index] = device_mul_add_separate(
        routed_inputs[output_index],
        1.0f,
        shared
    );
}

__global__ void shared_expert_gate_exact_batched_kernel(
    const float *selected_inputs,
    const uint16_t *gate_weight,
    float *gate_logits,
    float *gate_scales,
    unsigned int selected_token_count
) {
    const unsigned int token_index =
        blockIdx.x * blockDim.x + threadIdx.x;
    if (token_index >= selected_token_count) {
        return;
    }

    const float *input =
        selected_inputs +
        static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE;
    float gate_logit = 0.0f;
    for (unsigned int col = 0u; col < QRT_QWEN36_HIDDEN_SIZE; ++col) {
        gate_logit = device_mul_add_separate(
            gate_logit,
            input[col],
            device_bf16_to_float(gate_weight[col])
        );
    }
    gate_logits[token_index] = gate_logit;
    gate_scales[token_index] = 1.0f / (1.0f + expf(-gate_logit));
}

__global__ void shared_expert_gate_up_activation_exact_tiled_kernel(
    const float *selected_inputs,
    const uint16_t *gate_proj_weight,
    const uint16_t *up_proj_weight,
    float *activated,
    unsigned int selected_token_count
) {
    __shared__ float input_tile[kSharedExactTileTokens][kSharedExactTileK];
    __shared__ uint16_t
        gate_weight_tile[kSharedExactTileRows][kSharedExactTileK];
    __shared__ uint16_t
        up_weight_tile[kSharedExactTileRows][kSharedExactTileK];

    const unsigned int row_lane = threadIdx.x;
    const unsigned int token_lane = threadIdx.y;
    const unsigned int inter =
        blockIdx.x * kSharedExactTileRows + row_lane;
    const unsigned int token_index =
        blockIdx.y * kSharedExactTileTokens + token_lane;
    const unsigned int linear_thread =
        token_lane * kSharedExactTileRows + row_lane;
    constexpr unsigned int kTileThreads =
        kSharedExactTileTokens * kSharedExactTileRows;
    float gate = 0.0f;
    float up = 0.0f;

    for (unsigned int col_base = 0u;
         col_base < QRT_QWEN36_HIDDEN_SIZE;
         col_base += kSharedExactTileK) {
        for (unsigned int index = linear_thread;
             index < kSharedExactTileTokens * kSharedExactTileK;
             index += kTileThreads) {
            const unsigned int tile_token = index / kSharedExactTileK;
            const unsigned int tile_col = index % kSharedExactTileK;
            const unsigned int source_token =
                blockIdx.y * kSharedExactTileTokens + tile_token;
            input_tile[tile_token][tile_col] =
                source_token < selected_token_count
                    ? selected_inputs[
                          static_cast<size_t>(source_token) *
                              QRT_QWEN36_HIDDEN_SIZE +
                          col_base + tile_col
                      ]
                    : 0.0f;
        }
        for (unsigned int index = linear_thread;
             index < kSharedExactTileRows * kSharedExactTileK;
             index += kTileThreads) {
            const unsigned int tile_row = index / kSharedExactTileK;
            const unsigned int tile_col = index % kSharedExactTileK;
            const unsigned int source_inter =
                blockIdx.x * kSharedExactTileRows + tile_row;
            if (source_inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) {
                const size_t weight_index =
                    static_cast<size_t>(source_inter) *
                        QRT_QWEN36_HIDDEN_SIZE +
                    col_base + tile_col;
                gate_weight_tile[tile_row][tile_col] =
                    gate_proj_weight[weight_index];
                up_weight_tile[tile_row][tile_col] =
                    up_proj_weight[weight_index];
            } else {
                gate_weight_tile[tile_row][tile_col] = 0u;
                up_weight_tile[tile_row][tile_col] = 0u;
            }
        }
        __syncthreads();

        if (token_index < selected_token_count &&
            inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) {
            for (unsigned int tile_col = 0u;
                 tile_col < kSharedExactTileK;
                 ++tile_col) {
                const float input_value =
                    input_tile[token_lane][tile_col];
                gate = device_mul_add_separate(
                    gate,
                    input_value,
                    device_bf16_to_float(
                        gate_weight_tile[row_lane][tile_col]
                    )
                );
                up = device_mul_add_separate(
                    up,
                    input_value,
                    device_bf16_to_float(
                        up_weight_tile[row_lane][tile_col]
                    )
                );
            }
        }
        __syncthreads();
    }

    if (token_index < selected_token_count &&
        inter < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) {
        activated[
            static_cast<size_t>(token_index) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
            inter
        ] = device_silu_f32(gate) * up;
    }
}

__global__ void shared_expert_down_combine_exact_tiled_kernel(
    const float *activated,
    const float *gate_scales,
    const uint16_t *down_weight,
    const float *routed_inputs,
    float *shared_outputs,
    float *combined_outputs,
    unsigned int selected_token_count
) {
    __shared__ float
        activated_tile[kSharedExactTileTokens][kSharedExactTileK];
    __shared__ uint16_t
        down_weight_tile[kSharedExactTileRows][kSharedExactTileK];

    const unsigned int row_lane = threadIdx.x;
    const unsigned int token_lane = threadIdx.y;
    const unsigned int row =
        blockIdx.x * kSharedExactTileRows + row_lane;
    const unsigned int token_index =
        blockIdx.y * kSharedExactTileTokens + token_lane;
    const unsigned int linear_thread =
        token_lane * kSharedExactTileRows + row_lane;
    constexpr unsigned int kTileThreads =
        kSharedExactTileTokens * kSharedExactTileRows;
    float value = 0.0f;

    for (unsigned int inter_base = 0u;
         inter_base < QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
         inter_base += kSharedExactTileK) {
        for (unsigned int index = linear_thread;
             index < kSharedExactTileTokens * kSharedExactTileK;
             index += kTileThreads) {
            const unsigned int tile_token = index / kSharedExactTileK;
            const unsigned int tile_inter = index % kSharedExactTileK;
            const unsigned int source_token =
                blockIdx.y * kSharedExactTileTokens + tile_token;
            activated_tile[tile_token][tile_inter] =
                source_token < selected_token_count
                    ? activated[
                          static_cast<size_t>(source_token) *
                              QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                          inter_base + tile_inter
                      ]
                    : 0.0f;
        }
        for (unsigned int index = linear_thread;
             index < kSharedExactTileRows * kSharedExactTileK;
             index += kTileThreads) {
            const unsigned int tile_row = index / kSharedExactTileK;
            const unsigned int tile_inter = index % kSharedExactTileK;
            const unsigned int source_row =
                blockIdx.x * kSharedExactTileRows + tile_row;
            down_weight_tile[tile_row][tile_inter] =
                source_row < QRT_QWEN36_HIDDEN_SIZE
                    ? down_weight[
                          static_cast<size_t>(source_row) *
                              QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                          inter_base + tile_inter
                      ]
                    : 0u;
        }
        __syncthreads();

        if (token_index < selected_token_count &&
            row < QRT_QWEN36_HIDDEN_SIZE) {
            for (unsigned int tile_inter = 0u;
                 tile_inter < kSharedExactTileK;
                 ++tile_inter) {
                value = device_mul_add_separate(
                    value,
                    activated_tile[token_lane][tile_inter],
                    device_bf16_to_float(
                        down_weight_tile[row_lane][tile_inter]
                    )
                );
            }
        }
        __syncthreads();
    }

    if (token_index < selected_token_count &&
        row < QRT_QWEN36_HIDDEN_SIZE) {
        const size_t output_index =
            static_cast<size_t>(token_index) * QRT_QWEN36_HIDDEN_SIZE + row;
        const float shared = device_mul_add_separate(
            0.0f,
            gate_scales[token_index],
            value
        );
        shared_outputs[output_index] = shared;
        combined_outputs[output_index] = device_mul_add_separate(
            routed_inputs[output_index],
            1.0f,
            shared
        );
    }
}

__global__ void shared_expert_gate_scale_from_bf16_kernel(
    const uint16_t *gate_logits_bf16,
    float *gate_logits,
    float *gate_scales,
    unsigned int selected_token_count
) {
    const unsigned int token_index =
        blockIdx.x * blockDim.x + threadIdx.x;
    if (token_index >= selected_token_count) {
        return;
    }
    const float gate_logit = device_bf16_to_float(
        gate_logits_bf16[token_index]
    );
    gate_logits[token_index] = gate_logit;
    gate_scales[token_index] = 1.0f / (1.0f + expf(-gate_logit));
}

__global__ void shared_expert_activation_from_bf16_kernel(
    const uint16_t *gate_projection,
    const uint16_t *up_projection,
    uint16_t *activated,
    size_t count
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= count) {
        return;
    }
    const float gate = device_bf16_to_float(gate_projection[index]);
    const float up = device_bf16_to_float(up_projection[index]);
    activated[index] = device_float_to_bf16(device_silu_f32(gate) * up);
}

__global__ void shared_expert_down_combine_from_bf16_kernel(
    const uint16_t *down_projection,
    const float *gate_scales,
    const float *routed_inputs,
    float *shared_outputs,
    float *combined_outputs,
    size_t output_elements,
    unsigned int hidden_size
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= output_elements) {
        return;
    }
    const size_t token_index = index / hidden_size;
    const float shared = gate_scales[token_index] *
        device_bf16_to_float(down_projection[index]);
    shared_outputs[index] = shared;
    combined_outputs[index] = routed_inputs[index] + shared;
}

// Multi-row routed output remains live in linear_aux while the four retained
// shared hipBLASLt matrices run.  This tail evaluates the BF16 gate sigmoid,
// shared scaling and routed combination use the same contracted FMA emitted by
// the former shared-combine kernel; the residual add remains a separate F32
// instruction, matching the following kernel boundary.
__global__ void q1_moe_shared_output_residual_fused_kernel(
    const uint16_t *down_projection,
    const uint16_t *gate_logit_bf16,
    const float *routed_inputs,
    const float *residual_inputs,
    float *outputs,
    size_t output_elements,
    bool vllm_bf16_residual_norm,
    bool vllm_bf16_moe_endpoints
) {
    __shared__ float gate_scale;
    if (threadIdx.x == 0u) {
        const float gate_logit = device_bf16_to_float(gate_logit_bf16[0]);
        const float value = 1.0f / (1.0f + expf(-gate_logit));
        gate_scale = vllm_bf16_moe_endpoints
            ? device_bf16_round_to_float(value)
            : value;
    }
    __syncthreads();

    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= output_elements) {
        return;
    }
    float combined = 0.0f;
    if (vllm_bf16_moe_endpoints) {
        const float shared = device_bf16_round_to_float(
            gate_scale * device_bf16_to_float(down_projection[index])
        );
        combined = device_bf16_round_to_float(
            device_bf16_round_to_float(routed_inputs[index]) + shared
        );
    } else {
        asm("v_fma_f32 %0, %1, %2, %3"
            : "=v"(combined)
            : "v"(gate_scale),
              "v"(device_bf16_to_float(down_projection[index])),
              "v"(routed_inputs[index]));
    }
    float output = 0.0f;
    if (vllm_bf16_residual_norm) {
        output = device_bf16_round_to_float(
            device_bf16_round_to_float(residual_inputs[index]) +
            device_bf16_round_to_float(combined)
        );
    } else {
        asm("v_add_f32 %0, %1, %2"
            : "=v"(output)
            : "v"(residual_inputs[index]), "v"(combined));
    }
    outputs[index] = output;
}

// D145 moves the following layer's exact input RMSNorm into the last completed
// nonterminal MoE-output block.  The shared/routed/residual arithmetic above
// remains byte-for-byte identical; only after all 2048 F32 hidden values are
// globally visible does one 256-thread block execute the retained double
// reduction tree and publish the same BF16-rounded F32 plus BF16 endpoints.
__global__ void q1_moe_shared_output_next_input_rmsnorm_fused_kernel(
    const uint16_t *down_projection,
    const uint16_t *gate_logit_bf16,
    const float *routed_inputs,
    const float *residual_inputs,
    float *outputs,
    const uint16_t *next_norm_weights,
    float *next_norm_outputs,
    uint16_t *next_norm_outputs_bf16,
    uint32_t *completion_counter,
    size_t output_elements,
    bool vllm_bf16_residual_norm,
    bool vllm_bf16_moe_endpoints
) {
    __shared__ float gate_scale;
    __shared__ uint32_t last_block;
    __shared__ double partial[kThreads];
    __shared__ float inv_shared;

    if (threadIdx.x == 0u) {
        const float gate_logit = device_bf16_to_float(gate_logit_bf16[0]);
        const float value = 1.0f / (1.0f + expf(-gate_logit));
        gate_scale = vllm_bf16_moe_endpoints
            ? device_bf16_round_to_float(value)
            : value;
    }
    __syncthreads();

    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index < output_elements) {
        float combined = 0.0f;
        if (vllm_bf16_moe_endpoints) {
            const float shared = device_bf16_round_to_float(
                gate_scale *
                device_bf16_to_float(down_projection[index])
            );
            combined = device_bf16_round_to_float(
                device_bf16_round_to_float(routed_inputs[index]) +
                shared
            );
        } else {
            asm("v_fma_f32 %0, %1, %2, %3"
                : "=v"(combined)
                : "v"(gate_scale),
                  "v"(device_bf16_to_float(down_projection[index])),
                  "v"(routed_inputs[index]));
        }
        float output = 0.0f;
        if (vllm_bf16_residual_norm) {
            output = device_bf16_round_to_float(
                device_bf16_round_to_float(residual_inputs[index]) +
                device_bf16_round_to_float(combined)
            );
        } else {
            asm("v_add_f32 %0, %1, %2"
                : "=v"(output)
                : "v"(residual_inputs[index]), "v"(combined));
        }
        outputs[index] = output;
    }
    // Every writer must publish its own global store before the block's
    // completion ticket becomes visible to the eventual last block.
    __threadfence();
    __syncthreads();
    if (threadIdx.x == 0u) {
        const uint32_t ticket = atomicAdd(completion_counter, 1u);
        last_block = ticket + 1u == gridDim.x ? 1u : 0u;
    }
    __syncthreads();
    if (last_block == 0u) {
        return;
    }

    const unsigned int lane = threadIdx.x;
    double sumsq = 0.0;
    float sumsq_f32 = 0.0f;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kThreads;
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? lane * kValuesPerLane + item
            : lane + item * blockDim.x;
        const float value = outputs[col];
        if (vllm_bf16_residual_norm) {
            sumsq_f32 += value * value;
        } else {
            sumsq +=
                static_cast<double>(value) * static_cast<double>(value);
        }
    }
    float *partial_f32 = reinterpret_cast<float *>(partial);
    if (vllm_bf16_residual_norm) {
        partial_f32[lane] = sumsq_f32;
    } else {
        partial[lane] = sumsq;
    }
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u;
         stride >>= 1u) {
        if (lane < stride) {
            if (vllm_bf16_residual_norm) {
                partial_f32[lane] += partial_f32[lane + stride];
            } else {
                partial[lane] += partial[lane + stride];
            }
        }
        __syncthreads();
    }
    if (lane == 0u) {
        if (vllm_bf16_residual_norm) {
            inv_shared = rsqrtf(
                partial_f32[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
        } else {
            inv_shared = 1.0f / sqrtf(
                static_cast<float>(
                    partial[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
        }
    }
    __syncthreads();

    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? lane * kValuesPerLane + item
            : lane + item * blockDim.x;
        const float normalized =
            outputs[col] * inv_shared *
            (1.0f + device_bf16_to_float(next_norm_weights[col]));
        const uint16_t endpoint = device_float_to_bf16(normalized);
        next_norm_outputs[col] = device_bf16_to_float(endpoint);
        next_norm_outputs_bf16[col] = endpoint;
    }
    __syncthreads();
    if (lane == 0u) {
        __threadfence();
        atomicExch(completion_counter, 0u);
    }
}

// The paired corridor has both selected/shared MoE endpoints resident on one
// ordered stream before either state publishes its final residual.  Consume
// both states in one launch while retaining the former per-state FMA/add
// sequence and two independent 256-lane double RMS trees.  Terminal layer 39
// passes fuse_next_norm=false and stops after the exact residual publication.
__global__ void q1_moe_shared_output_next_input_rmsnorm_dual_exact_kernel(
    const uint16_t *down_projection0,
    const uint16_t *down_projection1,
    const uint16_t *gate_logit_bf160,
    const uint16_t *gate_logit_bf161,
    const float *routed_inputs0,
    const float *routed_inputs1,
    const float *residual_inputs0,
    const float *residual_inputs1,
    float *outputs0,
    float *outputs1,
    const uint16_t *next_norm_weights,
    float *next_norm_outputs0,
    float *next_norm_outputs1,
    uint16_t *next_norm_outputs_bf160,
    uint16_t *next_norm_outputs_bf161,
    uint32_t *completion_counter,
    size_t output_elements,
    bool fuse_next_norm,
    bool vllm_bf16_residual_norm,
    bool vllm_bf16_moe_endpoints
) {
    __shared__ float gate_scale[2];
    __shared__ uint32_t last_block;
    __shared__ double partial0[kThreads];
    __shared__ double partial1[kThreads];
    __shared__ float inv_shared[2];

    if (threadIdx.x == 0u) {
        const float gate_logit0 =
            device_bf16_to_float(gate_logit_bf160[0]);
        const float gate_logit1 =
            device_bf16_to_float(gate_logit_bf161[0]);
        const float gate_scale0 =
            1.0f / (1.0f + expf(-gate_logit0));
        const float gate_scale1 =
            1.0f / (1.0f + expf(-gate_logit1));
        gate_scale[0] = vllm_bf16_moe_endpoints
            ? device_bf16_round_to_float(gate_scale0)
            : gate_scale0;
        gate_scale[1] = vllm_bf16_moe_endpoints
            ? device_bf16_round_to_float(gate_scale1)
            : gate_scale1;
    }
    __syncthreads();

    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index < output_elements) {
        float combined0 = 0.0f;
        float combined1 = 0.0f;
        if (vllm_bf16_moe_endpoints) {
            const float shared0 = device_bf16_round_to_float(
                gate_scale[0] *
                device_bf16_to_float(down_projection0[index])
            );
            const float shared1 = device_bf16_round_to_float(
                gate_scale[1] *
                device_bf16_to_float(down_projection1[index])
            );
            combined0 = device_bf16_round_to_float(
                device_bf16_round_to_float(routed_inputs0[index]) +
                shared0
            );
            combined1 = device_bf16_round_to_float(
                device_bf16_round_to_float(routed_inputs1[index]) +
                shared1
            );
        } else {
            asm("v_fma_f32 %0, %1, %2, %3"
                : "=v"(combined0)
                : "v"(gate_scale[0]),
                  "v"(device_bf16_to_float(down_projection0[index])),
                  "v"(routed_inputs0[index]));
            asm("v_fma_f32 %0, %1, %2, %3"
                : "=v"(combined1)
                : "v"(gate_scale[1]),
                  "v"(device_bf16_to_float(down_projection1[index])),
                  "v"(routed_inputs1[index]));
        }
        float output0 = 0.0f;
        float output1 = 0.0f;
        if (vllm_bf16_residual_norm) {
            output0 = device_bf16_round_to_float(
                device_bf16_round_to_float(residual_inputs0[index]) +
                device_bf16_round_to_float(combined0)
            );
            output1 = device_bf16_round_to_float(
                device_bf16_round_to_float(residual_inputs1[index]) +
                device_bf16_round_to_float(combined1)
            );
        } else {
            asm("v_add_f32 %0, %1, %2"
                : "=v"(output0)
                : "v"(residual_inputs0[index]), "v"(combined0));
            asm("v_add_f32 %0, %1, %2"
                : "=v"(output1)
                : "v"(residual_inputs1[index]), "v"(combined1));
        }
        outputs0[index] = output0;
        outputs1[index] = output1;
    }
    if (!fuse_next_norm) {
        return;
    }

    // Every writer must publish both global stores before the shared
    // completion ticket becomes visible to the eventual last block.
    __threadfence();
    __syncthreads();
    if (threadIdx.x == 0u) {
        const uint32_t ticket = atomicAdd(completion_counter, 1u);
        last_block = ticket + 1u == gridDim.x ? 1u : 0u;
    }
    __syncthreads();
    if (last_block == 0u) {
        return;
    }

    const unsigned int lane = threadIdx.x;
    double sumsq0 = 0.0;
    double sumsq1 = 0.0;
    float sumsq_f320 = 0.0f;
    float sumsq_f321 = 0.0f;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kThreads;
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? lane * kValuesPerLane + item
            : lane + item * blockDim.x;
        const float value0 = outputs0[col];
        const float value1 = outputs1[col];
        if (vllm_bf16_residual_norm) {
            sumsq_f320 += value0 * value0;
            sumsq_f321 += value1 * value1;
        } else {
            sumsq0 +=
                static_cast<double>(value0) * static_cast<double>(value0);
            sumsq1 +=
                static_cast<double>(value1) * static_cast<double>(value1);
        }
    }
    float *partial_f320 = reinterpret_cast<float *>(partial0);
    float *partial_f321 = reinterpret_cast<float *>(partial1);
    if (vllm_bf16_residual_norm) {
        partial_f320[lane] = sumsq_f320;
        partial_f321[lane] = sumsq_f321;
    } else {
        partial0[lane] = sumsq0;
        partial1[lane] = sumsq1;
    }
    __syncthreads();

    for (unsigned int stride = blockDim.x / 2u; stride > 0u;
         stride >>= 1u) {
        if (lane < stride) {
            if (vllm_bf16_residual_norm) {
                partial_f320[lane] += partial_f320[lane + stride];
                partial_f321[lane] += partial_f321[lane + stride];
            } else {
                partial0[lane] += partial0[lane + stride];
                partial1[lane] += partial1[lane + stride];
            }
        }
        __syncthreads();
    }
    if (lane == 0u) {
        if (vllm_bf16_residual_norm) {
            inv_shared[0] = rsqrtf(
                partial_f320[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
            inv_shared[1] = rsqrtf(
                partial_f321[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
        } else {
            inv_shared[0] = 1.0f / sqrtf(
                static_cast<float>(
                    partial0[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
            inv_shared[1] = 1.0f / sqrtf(
                static_cast<float>(
                    partial1[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
        }
    }
    __syncthreads();

    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? lane * kValuesPerLane + item
            : lane + item * blockDim.x;
        const float weight =
            1.0f + device_bf16_to_float(next_norm_weights[col]);
        const uint16_t endpoint0 = device_float_to_bf16(
            outputs0[col] * inv_shared[0] * weight
        );
        const uint16_t endpoint1 = device_float_to_bf16(
            outputs1[col] * inv_shared[1] * weight
        );
        next_norm_outputs0[col] = device_bf16_to_float(endpoint0);
        next_norm_outputs1[col] = device_bf16_to_float(endpoint1);
        next_norm_outputs_bf160[col] = endpoint0;
        next_norm_outputs_bf161[col] = endpoint1;
    }
    __syncthreads();
    if (lane == 0u) {
        __threadfence();
        atomicExch(completion_counter, 0u);
    }
}

__device__ __forceinline__ float q1_moe_raw_wave_tree_sum(float value) {
    #pragma unroll
    for (unsigned int offset = kQ1MoeRawWaveSize / 2u;
         offset > 0u;
         offset >>= 1u) {
        value += __shfl_down(value, offset, kQ1MoeRawWaveSize);
    }
    return value;
}

__device__ __forceinline__ uint32_t
q1_moe_lossless_palette_wave_broadcast(uint32_t value) {
    return __shfl(value, 0u, kQ1MoeRawWaveSize);
}

__device__ __forceinline__ uint8_t q1_moe_lossless_palette_byte(
    uint32_t palette_0_3,
    uint32_t palette_4_7,
    uint32_t palette_8_11,
    uint32_t palette_12_15,
    unsigned int slot
) {
    const uint32_t word = slot < 4u
        ? palette_0_3
        : (slot < 8u
            ? palette_4_7
            : (slot < 12u ? palette_8_11 : palette_12_15));
    return static_cast<uint8_t>(
        word >> ((slot & 3u) * 8u)
    );
}

__device__ __forceinline__ void q1_moe_lossless_palette_store_byte(
    uint32_t *palette_0_3,
    uint32_t *palette_4_7,
    uint32_t *palette_8_11,
    uint32_t *palette_12_15,
    unsigned int slot,
    uint8_t value
) {
    uint32_t *word = slot < 4u
        ? palette_0_3
        : (slot < 8u
            ? palette_4_7
            : (slot < 12u ? palette_8_11 : palette_12_15));
    *word |= static_cast<uint32_t>(value) << ((slot & 3u) * 8u);
}

__device__ __forceinline__ unsigned int
q1_moe_lossless_palette_build(
    const uint16_t *source,
    uint32_t *palette_0_3,
    uint32_t *palette_4_7,
    uint32_t *palette_8_11,
    uint32_t *palette_12_15
) {
    *palette_0_3 = 0u;
    *palette_4_7 = 0u;
    *palette_8_11 = 0u;
    *palette_12_15 = 0u;
    unsigned int count = 0u;
    for (unsigned int index = 0u;
         index < kQ1MoeLosslessPaletteChunkValues;
         ++index) {
        const uint8_t high = static_cast<uint8_t>(source[index] >> 8u);
        bool found = false;
        for (unsigned int slot = 0u; slot < count; ++slot) {
            found = found ||
                q1_moe_lossless_palette_byte(
                    *palette_0_3,
                    *palette_4_7,
                    *palette_8_11,
                    *palette_12_15,
                    slot
                ) == high;
        }
        if (!found) {
            if (count == 16u) {
                return 17u;
            }
            q1_moe_lossless_palette_store_byte(
                palette_0_3,
                palette_4_7,
                palette_8_11,
                palette_12_15,
                count,
                high
            );
            ++count;
        }
    }
    return count;
}

__global__ __launch_bounds__(kQ1MoeW8A8QuantizeThreads)
void q1_moe_lossless_palette_count_overflow_kernel(
    const uint16_t *source,
    uint64_t chunk_count,
    uint32_t *overflow_count
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const uint64_t first =
        static_cast<uint64_t>(blockIdx.x) * kQ1MoeRawWavesPerBlock +
        wave;
    const uint64_t stride =
        static_cast<uint64_t>(gridDim.x) * kQ1MoeRawWavesPerBlock;
    for (uint64_t chunk = first; chunk < chunk_count; chunk += stride) {
        const uint16_t *const source_chunk =
            source + chunk * kQ1MoeLosslessPaletteChunkValues;
        uint32_t local_presence = 0u;
        uint32_t local_unknown = 0u;
        #pragma unroll
        for (unsigned int item = 0u; item < 8u; ++item) {
            const uint8_t high = static_cast<uint8_t>(
                source_chunk[lane * 8u + item] >> 8u
            );
            unsigned int code = 0u;
            bool known = true;
            if (high == UINT8_C(0x01)) {
                code = 0u;
            } else if (high == UINT8_C(0x81)) {
                code = 1u;
            } else if (high >= UINT8_C(0x30) &&
                       high <= UINT8_C(0x3e)) {
                code = 2u + static_cast<unsigned int>(
                    high - UINT8_C(0x30)
                );
            } else if (high >= UINT8_C(0xb0) &&
                       high <= UINT8_C(0xbe)) {
                code = 17u + static_cast<unsigned int>(
                    high - UINT8_C(0xb0)
                );
            } else {
                known = false;
            }
            if (known) {
                local_presence |= UINT32_C(1) << code;
            } else {
                local_unknown = 1u;
            }
        }
        #pragma unroll
        for (unsigned int mask = 16u; mask != 0u; mask >>= 1u) {
            local_presence |= __shfl_xor(
                local_presence,
                mask,
                kQ1MoeRawWaveSize
            );
            local_unknown |= __shfl_xor(
                local_unknown,
                mask,
                kQ1MoeRawWaveSize
            );
        }
        if (lane == 0u &&
            (local_unknown != 0u || __popc(local_presence) > 16)) {
            (void)atomicAdd(overflow_count, 1u);
        }
    }
}

__device__ __forceinline__ unsigned int
q1_moe_lossless_palette_find_code(
    uint8_t high,
    uint32_t palette_0_3,
    uint32_t palette_4_7,
    uint32_t palette_8_11,
    uint32_t palette_12_15
) {
    unsigned int code = 0u;
    for (unsigned int slot = 0u; slot < 16u; ++slot) {
        if (q1_moe_lossless_palette_byte(
                palette_0_3,
                palette_4_7,
                palette_8_11,
                palette_12_15,
                slot
            ) == high) {
            code = slot;
            break;
        }
    }
    return code;
}

__global__ __launch_bounds__(kQ1MoeW8A8QuantizeThreads)
void q1_moe_lossless_palette_pack_kernel(
    const uint16_t *source,
    uint64_t chunk_count,
    uint8_t *packed_chunks,
    uint32_t *overflow_indices,
    uint16_t *overflow_values,
    uint32_t *overflow_count
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const uint64_t first =
        static_cast<uint64_t>(blockIdx.x) * kQ1MoeRawWavesPerBlock +
        wave;
    const uint64_t stride =
        static_cast<uint64_t>(gridDim.x) * kQ1MoeRawWavesPerBlock;
    for (uint64_t chunk = first; chunk < chunk_count; chunk += stride) {
        const uint16_t *const source_chunk =
            source + chunk * kQ1MoeLosslessPaletteChunkValues;
        uint16_t values[8]{};
        unsigned int codes[8]{};
        uint32_t local_presence = 0u;
        uint32_t local_unknown = 0u;
        #pragma unroll
        for (unsigned int item = 0u; item < 8u; ++item) {
            const uint16_t value = source_chunk[lane * 8u + item];
            const uint8_t high = static_cast<uint8_t>(value >> 8u);
            values[item] = value;
            bool known = true;
            if (high == UINT8_C(0x01)) {
                codes[item] = 0u;
            } else if (high == UINT8_C(0x81)) {
                codes[item] = 1u;
            } else if (high >= UINT8_C(0x30) &&
                       high <= UINT8_C(0x3e)) {
                codes[item] = 2u + static_cast<unsigned int>(
                    high - UINT8_C(0x30)
                );
            } else if (high >= UINT8_C(0xb0) &&
                       high <= UINT8_C(0xbe)) {
                codes[item] = 17u + static_cast<unsigned int>(
                    high - UINT8_C(0xb0)
                );
            } else {
                known = false;
            }
            if (known) {
                local_presence |= UINT32_C(1) << codes[item];
            } else {
                local_unknown = 1u;
            }
        }
        #pragma unroll
        for (unsigned int mask = 16u; mask != 0u; mask >>= 1u) {
            local_presence |= __shfl_xor(
                local_presence,
                mask,
                kQ1MoeRawWaveSize
            );
            local_unknown |= __shfl_xor(
                local_unknown,
                mask,
                kQ1MoeRawWaveSize
            );
        }
        const bool overflow =
            local_unknown != 0u || __popc(local_presence) > 16;
        if (overflow) {
            uint32_t overflow_index = 0u;
            if (lane == 0u) {
                overflow_index = atomicAdd(overflow_count, 1u);
                overflow_indices[chunk] = overflow_index;
            }
            overflow_index =
                q1_moe_lossless_palette_wave_broadcast(overflow_index);
            #pragma unroll
            for (unsigned int item = 0u; item < 8u; ++item) {
                const unsigned int index = lane * 8u + item;
                overflow_values[
                    static_cast<uint64_t>(overflow_index) *
                        kQ1MoeLosslessPaletteChunkValues +
                    index
                ] = values[item];
            }
            continue;
        }

        uint8_t *const packed = packed_chunks +
            chunk * kQ1MoeLosslessPalettePackedChunkBytes;
        if (lane == 0u) {
            overflow_indices[chunk] =
                kQ1MoeLosslessPaletteOverflowSentinel;
            uint8_t *const palette =
                packed + kQ1MoeLosslessPaletteLowBytes +
                kQ1MoeLosslessPaletteCodeBytes;
            unsigned int slot = 0u;
            #pragma unroll
            for (unsigned int code = 0u; code < 32u; ++code) {
                if ((local_presence & (UINT32_C(1) << code)) == 0u) {
                    continue;
                }
                uint8_t high = 0u;
                if (code == 0u) {
                    high = UINT8_C(0x01);
                } else if (code == 1u) {
                    high = UINT8_C(0x81);
                } else if (code <= 16u) {
                    high = static_cast<uint8_t>(
                        UINT8_C(0x30) + code - 2u
                    );
                } else {
                    high = static_cast<uint8_t>(
                        UINT8_C(0xb0) + code - 17u
                    );
                }
                palette[slot++] = high;
            }
            while (slot < 16u) {
                palette[slot++] = 0u;
            }
        }
        #pragma unroll
        for (unsigned int item = 0u; item < 8u; ++item) {
            packed[lane * 8u + item] =
                static_cast<uint8_t>(values[item]);
        }
        #pragma unroll
        for (unsigned int pair = 0u; pair < 4u; ++pair) {
            const unsigned int first_code = codes[2u * pair];
            const unsigned int second_code = codes[2u * pair + 1u];
            const uint32_t first_lower = first_code == 0u
                ? 0u
                : (UINT32_C(1) << first_code) - 1u;
            const uint32_t second_lower = second_code == 0u
                ? 0u
                : (UINT32_C(1) << second_code) - 1u;
            const unsigned int first_slot = __popc(
                local_presence & first_lower
            );
            const unsigned int second_slot = __popc(
                local_presence & second_lower
            );
            packed[
                kQ1MoeLosslessPaletteLowBytes + lane * 4u + pair
            ] = static_cast<uint8_t>(
                first_slot | (second_slot << 4u)
            );
        }
    }
}

__device__ __forceinline__ bool
q8192_moe_lossless_row_palette_known_code(
    uint8_t high,
    unsigned int *code
) {
    if (high == UINT8_C(0x01)) {
        *code = 0u;
    } else if (high == UINT8_C(0x81)) {
        *code = 1u;
    } else if (high >= UINT8_C(0x30) && high <= UINT8_C(0x3e)) {
        *code = 2u + static_cast<unsigned int>(high - UINT8_C(0x30));
    } else if (high >= UINT8_C(0xb0) && high <= UINT8_C(0xbe)) {
        *code = 17u + static_cast<unsigned int>(high - UINT8_C(0xb0));
    } else {
        *code = 0u;
        return false;
    }
    return true;
}

__device__ __forceinline__ void
q8192_moe_lossless_row_palette_reduce(
    uint32_t *presence,
    uint32_t *unknown
) {
    #pragma unroll
    for (unsigned int mask = 16u; mask != 0u; mask >>= 1u) {
        *presence |= __shfl_xor(
            *presence,
            mask,
            kQ1MoeRawWaveSize
        );
        *unknown |= __shfl_xor(
            *unknown,
            mask,
            kQ1MoeRawWaveSize
        );
    }
}

