__device__ __forceinline__ uint32_t
q1_moe_lossless_palette_permute_bytes(
    uint32_t first,
    uint32_t second,
    uint32_t selectors
) {
    // gfx1151 v_perm_b32 numbers bytes 0..3 from its second data
    // operand, so keep the logical low dictionary in that operand.
    return static_cast<uint32_t>(
        __builtin_amdgcn_perm(second, first, selectors)
    );
}

__device__ __forceinline__ uint16_t
q1_moe_lossless_palette_decode_high_pair(
    uint8_t packed_codes,
    uint32_t palette_0_3,
    uint32_t palette_4_7,
    uint32_t palette_8_11,
    uint32_t palette_12_15
) {
    const unsigned int code0 =
        static_cast<unsigned int>(packed_codes & UINT8_C(0x0f));
    const unsigned int code1 =
        static_cast<unsigned int>(packed_codes >> 4u);
    const uint32_t selectors =
        static_cast<uint32_t>(code0 & 7u) |
        (static_cast<uint32_t>(code1 & 7u) << 8u);
    const uint32_t low_half =
        q1_moe_lossless_palette_permute_bytes(
            palette_0_3,
            palette_4_7,
            selectors
        );
    const uint32_t high_half =
        q1_moe_lossless_palette_permute_bytes(
            palette_8_11,
            palette_12_15,
            selectors
        );
    const uint32_t high_select =
        (code0 >= 8u ? UINT32_C(0x000000ff) : UINT32_C(0)) |
        (code1 >= 8u ? UINT32_C(0x0000ff00) : UINT32_C(0));
    return static_cast<uint16_t>(
        (low_half & ~high_select) | (high_half & high_select)
    );
}

struct Q1MoeLosslessPaletteWaveChunk {
    const uint8_t *packed = nullptr;
    const uint32_t *raw_pairs = nullptr;
    uint32_t palette_0_3 = 0u;
    uint32_t palette_4_7 = 0u;
    uint32_t palette_8_11 = 0u;
    uint32_t palette_12_15 = 0u;
};

__device__ __forceinline__ Q1MoeLosslessPaletteWaveChunk
q1_moe_lossless_palette_prepare_wave_chunk(
    const uint8_t *packed_chunks,
    const uint32_t *overflow_indices,
    const uint16_t *overflow_values,
    uint64_t chunk,
    unsigned int lane
) {
    Q1MoeLosslessPaletteWaveChunk result;
    uint32_t overflow_index = lane == 0u
        ? overflow_indices[chunk]
        : 0u;
    overflow_index =
        q1_moe_lossless_palette_wave_broadcast(overflow_index);
    if (overflow_index != kQ1MoeLosslessPaletteOverflowSentinel) {
        result.raw_pairs = reinterpret_cast<const uint32_t *>(
            overflow_values +
            static_cast<uint64_t>(overflow_index) *
                kQ1MoeLosslessPaletteChunkValues
        );
        return result;
    }
    result.packed = packed_chunks +
        chunk * kQ1MoeLosslessPalettePackedChunkBytes;
    const uint32_t *const palette_words =
        reinterpret_cast<const uint32_t *>(
            result.packed +
            kQ1MoeLosslessPaletteLowBytes +
            kQ1MoeLosslessPaletteCodeBytes
        );
    result.palette_0_3 = q1_moe_lossless_palette_wave_broadcast(
        lane == 0u ? palette_words[0u] : 0u
    );
    result.palette_4_7 = q1_moe_lossless_palette_wave_broadcast(
        lane == 0u ? palette_words[1u] : 0u
    );
    result.palette_8_11 = q1_moe_lossless_palette_wave_broadcast(
        lane == 0u ? palette_words[2u] : 0u
    );
    result.palette_12_15 = q1_moe_lossless_palette_wave_broadcast(
        lane == 0u ? palette_words[3u] : 0u
    );
    return result;
}

__device__ __forceinline__ uint32_t
q1_moe_lossless_palette_decode_pair(
    const Q1MoeLosslessPaletteWaveChunk &chunk,
    unsigned int pair
) {
    if (chunk.raw_pairs != nullptr) {
        return chunk.raw_pairs[pair];
    }
    const uint16_t low_pair =
        reinterpret_cast<const uint16_t *>(chunk.packed)[pair];
    const uint16_t high_pair =
        q1_moe_lossless_palette_decode_high_pair(
            chunk.packed[kQ1MoeLosslessPaletteLowBytes + pair],
            chunk.palette_0_3,
            chunk.palette_4_7,
            chunk.palette_8_11,
            chunk.palette_12_15
        );
    return static_cast<uint32_t>(low_pair & UINT16_C(0x00ff)) |
        (static_cast<uint32_t>(low_pair & UINT16_C(0xff00)) << 8u) |
        (static_cast<uint32_t>(high_pair & UINT16_C(0x00ff)) << 8u) |
        (static_cast<uint32_t>(high_pair & UINT16_C(0xff00)) << 16u);
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_lossless_palette_gate_up_dual_kernel(
    const uint8_t *packed_gate_up,
    const uint32_t *overflow_indices,
    const uint16_t *overflow_values,
    const uint16_t *input0,
    const uint16_t *input1,
    const uint32_t *topk0_ids,
    const uint32_t *topk1_ids,
    uint16_t *activated0,
    uint16_t *activated1
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int task =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    constexpr unsigned int kTaskCount =
        QRT_QWEN36_EXPERTS_PER_TOKEN *
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    if (task >= kTaskCount) {
        return;
    }
    const unsigned int route =
        task / QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const unsigned int row =
        task - route * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const unsigned int expert0 = topk0_ids[route];
    const unsigned int expert1 = topk1_ids[route];
    const bool same_expert = expert0 == expert1;
    constexpr uint64_t kChunksPerRow =
        QRT_QWEN36_HIDDEN_SIZE /
        kQ1MoeLosslessPaletteChunkValues;
    constexpr uint64_t kGateChunksPerExpert =
        static_cast<uint64_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        kChunksPerRow;
    constexpr uint64_t kChunksPerExpert =
        2u * kGateChunksPerExpert;
    const uint64_t gate0_first =
        static_cast<uint64_t>(expert0) * kChunksPerExpert +
        static_cast<uint64_t>(row) * kChunksPerRow;
    const uint64_t up0_first = gate0_first + kGateChunksPerExpert;
    const uint64_t gate1_first =
        static_cast<uint64_t>(expert1) * kChunksPerExpert +
        static_cast<uint64_t>(row) * kChunksPerRow;
    const uint64_t up1_first = gate1_first + kGateChunksPerExpert;
    const uint32_t *const input0_pairs =
        reinterpret_cast<const uint32_t *>(input0);
    const uint32_t *const input1_pairs =
        reinterpret_cast<const uint32_t *>(input1);
    float gate0_sum = 0.0f;
    float up0_sum = 0.0f;
    float gate1_sum = 0.0f;
    float up1_sum = 0.0f;

    #pragma unroll
    for (unsigned int local_chunk = 0u;
         local_chunk < kChunksPerRow;
         ++local_chunk) {
        const Q1MoeLosslessPaletteWaveChunk gate0_chunk =
            q1_moe_lossless_palette_prepare_wave_chunk(
                packed_gate_up,
                overflow_indices,
                overflow_values,
                gate0_first + local_chunk,
                lane
            );
        const Q1MoeLosslessPaletteWaveChunk up0_chunk =
            q1_moe_lossless_palette_prepare_wave_chunk(
                packed_gate_up,
                overflow_indices,
                overflow_values,
                up0_first + local_chunk,
                lane
            );
        const Q1MoeLosslessPaletteWaveChunk gate1_chunk = same_expert
            ? gate0_chunk
            : q1_moe_lossless_palette_prepare_wave_chunk(
                  packed_gate_up,
                  overflow_indices,
                  overflow_values,
                  gate1_first + local_chunk,
                  lane
              );
        const Q1MoeLosslessPaletteWaveChunk up1_chunk = same_expert
            ? up0_chunk
            : q1_moe_lossless_palette_prepare_wave_chunk(
                  packed_gate_up,
                  overflow_indices,
                  overflow_values,
                  up1_first + local_chunk,
                  lane
              );
        #pragma unroll
        for (unsigned int iteration = 0u;
             iteration < kQ1MoeLosslessPalettePairsPerLane;
             ++iteration) {
            const unsigned int local_pair =
                lane + iteration * kQ1MoeRawWaveSize;
            const unsigned int input_pair =
                local_chunk * kQ1MoeLosslessPalettePairsPerChunk +
                local_pair;
            const uint32_t input0_pair = input0_pairs[input_pair];
            const uint32_t input1_pair = input1_pairs[input_pair];
            const uint32_t gate0_pair =
                q1_moe_lossless_palette_decode_pair(
                    gate0_chunk,
                    local_pair
                );
            const uint32_t up0_pair =
                q1_moe_lossless_palette_decode_pair(
                    up0_chunk,
                    local_pair
                );
            const uint32_t gate1_pair = same_expert
                ? gate0_pair
                : q1_moe_lossless_palette_decode_pair(
                      gate1_chunk,
                      local_pair
                  );
            const uint32_t up1_pair = same_expert
                ? up0_pair
                : q1_moe_lossless_palette_decode_pair(
                      up1_chunk,
                      local_pair
                  );
            gate0_sum = device_dot2_f32_bf16(
                input0_pair,
                gate0_pair,
                gate0_sum
            );
            up0_sum = device_dot2_f32_bf16(
                input0_pair,
                up0_pair,
                up0_sum
            );
            gate1_sum = device_dot2_f32_bf16(
                input1_pair,
                gate1_pair,
                gate1_sum
            );
            up1_sum = device_dot2_f32_bf16(
                input1_pair,
                up1_pair,
                up1_sum
            );
        }
    }
    gate0_sum = q1_moe_raw_wave_tree_sum(gate0_sum);
    up0_sum = q1_moe_raw_wave_tree_sum(up0_sum);
    gate1_sum = q1_moe_raw_wave_tree_sum(gate1_sum);
    up1_sum = q1_moe_raw_wave_tree_sum(up1_sum);
    if (lane == 0u) {
        const uint16_t gate0 = device_float_to_bf16(gate0_sum);
        const uint16_t up0 = device_float_to_bf16(up0_sum);
        const uint16_t gate1 = device_float_to_bf16(gate1_sum);
        const uint16_t up1 = device_float_to_bf16(up1_sum);
        activated0[task] = device_float_to_bf16(
            device_silu_f32(device_bf16_to_float(gate0)) *
            device_bf16_to_float(up0)
        );
        activated1[task] = device_float_to_bf16(
            device_silu_f32(device_bf16_to_float(gate1)) *
            device_bf16_to_float(up1)
        );
    }
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_lossless_palette_down_dual_kernel(
    const uint8_t *packed_down,
    const uint32_t *overflow_indices,
    const uint16_t *overflow_values,
    const uint16_t *activated0,
    const uint16_t *activated1,
    const uint32_t *topk0_ids,
    const uint32_t *topk1_ids,
    const float *topk0_weights,
    const float *topk1_weights,
    float *routed0_output,
    float *routed1_output
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    if (row >= QRT_QWEN36_HIDDEN_SIZE) {
        return;
    }
    constexpr uint64_t kChunksPerRow =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE /
        kQ1MoeLosslessPaletteChunkValues;
    constexpr uint64_t kChunksPerExpert =
        static_cast<uint64_t>(QRT_QWEN36_HIDDEN_SIZE) *
        kChunksPerRow;
    float combined0 = 0.0f;
    float combined1 = 0.0f;
    #pragma unroll
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const unsigned int expert0 = topk0_ids[route];
        const unsigned int expert1 = topk1_ids[route];
        const bool same_expert = expert0 == expert1;
        const uint64_t first0 =
            static_cast<uint64_t>(expert0) * kChunksPerExpert +
            static_cast<uint64_t>(row) * kChunksPerRow;
        const uint64_t first1 =
            static_cast<uint64_t>(expert1) * kChunksPerExpert +
            static_cast<uint64_t>(row) * kChunksPerRow;
        const uint32_t *const input0_pairs =
            reinterpret_cast<const uint32_t *>(
                activated0 +
                static_cast<size_t>(route) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
            );
        const uint32_t *const input1_pairs =
            reinterpret_cast<const uint32_t *>(
                activated1 +
                static_cast<size_t>(route) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
            );
        float sum0 = 0.0f;
        float sum1 = 0.0f;
        #pragma unroll
        for (unsigned int local_chunk = 0u;
             local_chunk < kChunksPerRow;
             ++local_chunk) {
            const Q1MoeLosslessPaletteWaveChunk chunk0 =
                q1_moe_lossless_palette_prepare_wave_chunk(
                    packed_down,
                    overflow_indices,
                    overflow_values,
                    first0 + local_chunk,
                    lane
                );
            const Q1MoeLosslessPaletteWaveChunk chunk1 = same_expert
                ? chunk0
                : q1_moe_lossless_palette_prepare_wave_chunk(
                      packed_down,
                      overflow_indices,
                      overflow_values,
                      first1 + local_chunk,
                      lane
                  );
            #pragma unroll
            for (unsigned int iteration = 0u;
                 iteration < kQ1MoeLosslessPalettePairsPerLane;
                 ++iteration) {
                const unsigned int local_pair =
                    lane + iteration * kQ1MoeRawWaveSize;
                const unsigned int input_pair =
                    local_chunk *
                        kQ1MoeLosslessPalettePairsPerChunk +
                    local_pair;
                const uint32_t weight0 =
                    q1_moe_lossless_palette_decode_pair(
                        chunk0,
                        local_pair
                    );
                const uint32_t weight1 = same_expert
                    ? weight0
                    : q1_moe_lossless_palette_decode_pair(
                          chunk1,
                          local_pair
                      );
                sum0 = device_dot2_f32_bf16(
                    input0_pairs[input_pair],
                    weight0,
                    sum0
                );
                sum1 = device_dot2_f32_bf16(
                    input1_pairs[input_pair],
                    weight1,
                    sum1
                );
            }
        }
        sum0 = q1_moe_raw_wave_tree_sum(sum0);
        sum1 = q1_moe_raw_wave_tree_sum(sum1);
        if (lane == 0u) {
            combined0 = device_mul_add_separate(
                combined0,
                topk0_weights[route],
                device_bf16_round_to_float(sum0)
            );
            combined1 = device_mul_add_separate(
                combined1,
                topk1_weights[route],
                device_bf16_round_to_float(sum1)
            );
        }
    }
    if (lane == 0u) {
        routed0_output[row] = device_bf16_round_to_float(combined0);
        routed1_output[row] = device_bf16_round_to_float(combined1);
    }
}

__device__ __forceinline__ float q1_moe_w8a8_wave_max(float value) {
#pragma unroll
    for (unsigned int offset = kQ1MoeRawWaveSize / 2u;
         offset > 0u;
         offset >>= 1u) {
        value = fmaxf(
            value,
            __shfl_down(value, offset, kQ1MoeRawWaveSize)
        );
    }
    return value;
}

__device__ __forceinline__ int q1_moe_w8a8_wave_tree_sum_i32(int value) {
#pragma unroll
    for (unsigned int offset = kQ1MoeRawWaveSize / 2u;
         offset > 0u;
         offset >>= 1u) {
        value += __shfl_down(value, offset, kQ1MoeRawWaveSize);
    }
    return value;
}

__device__ __forceinline__ int q1_moe_w8a8_quantize_value(
    float value,
    float inverse_scale
) {
    const float scaled = value * inverse_scale;
    const int rounded = static_cast<int>(
        scaled + (scaled >= 0.0f ? 0.5f : -0.5f)
    );
    return rounded < -127 ? -127 : (rounded > 127 ? 127 : rounded);
}

__device__ __forceinline__ int q1_moe_packed_w6_quantize_value(
    float value,
    float inverse_scale
) {
    const float scaled = value * inverse_scale;
    const int rounded = static_cast<int>(
        scaled + (scaled >= 0.0f ? 0.5f : -0.5f)
    );
    return rounded < -static_cast<int>(kQ1MoePackedW6MaximumCode)
        ? -static_cast<int>(kQ1MoePackedW6MaximumCode)
        : (rounded > static_cast<int>(kQ1MoePackedW6MaximumCode)
            ? static_cast<int>(kQ1MoePackedW6MaximumCode)
            : rounded);
}

__device__ __forceinline__ int q1_moe_packed_w6_sign_extend(
    uint32_t value
) {
    return static_cast<int>(value << 26u) >> 26u;
}

// Four signed six-bit weights occupy exactly three bytes.  gfx1151 accepts
// the unaligned dword fetch used here; the masked fourth byte is protected by
// one allocation-level padding word.  The decoded char4 feeds the same native
// signed dot4 recurrence as the retained W8A8 provider.
__device__ __forceinline__ char4 q1_moe_packed_w6_load_char4(
    const uint8_t *source
) {
    const uint32_t bits =
        *reinterpret_cast<const uint32_t *>(source) & UINT32_C(0x00ffffff);
    return make_char4(
        static_cast<signed char>(
            q1_moe_packed_w6_sign_extend(bits & 63u)
        ),
        static_cast<signed char>(
            q1_moe_packed_w6_sign_extend((bits >> 6u) & 63u)
        ),
        static_cast<signed char>(
            q1_moe_packed_w6_sign_extend((bits >> 12u) & 63u)
        ),
        static_cast<signed char>(
            q1_moe_packed_w6_sign_extend((bits >> 18u) & 63u)
        )
    );
}

// This intentionally uses the resident BF16 weights directly.  It is the
// reversible q8192 numerical gate for W8A8, not the final packed provider:
// no persistent quantized model copy or startup cost is introduced until the
// gb10 boundary proves that the arithmetic is viable.
__global__ __launch_bounds__(kQ1MoeW8A8QuantizeThreads)
void q1_moe_w8a8_quantize_bf16_vectors_kernel(
    const uint16_t *inputs,
    int8_t *outputs,
    float *scales,
    unsigned int vector_size,
    unsigned int vector_count
) {
    const unsigned int vector = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (vector >= vector_count) {
        return;
    }
    __shared__ float maxima[kQ1MoeW8A8QuantizeThreads];
    const size_t base = static_cast<size_t>(vector) * vector_size;
    float maximum = 0.0f;
    for (unsigned int index = lane;
         index < vector_size;
         index += kQ1MoeW8A8QuantizeThreads) {
        maximum = fmaxf(
            maximum,
            fabsf(device_bf16_to_float(inputs[base + index]))
        );
    }
    maxima[lane] = maximum;
    __syncthreads();
#pragma unroll
    for (unsigned int offset = kQ1MoeW8A8QuantizeThreads / 2u;
         offset > 0u;
         offset >>= 1u) {
        if (lane < offset) {
            maxima[lane] = fmaxf(maxima[lane], maxima[lane + offset]);
        }
        __syncthreads();
    }
    const float scale = maxima[0] > 0.0f ? maxima[0] / 127.0f : 1.0f;
    const float inverse_scale = 1.0f / scale;
    if (lane == 0u) {
        scales[vector] = scale;
    }
    for (unsigned int index = lane;
         index < vector_size;
         index += kQ1MoeW8A8QuantizeThreads) {
        outputs[base + index] = static_cast<int8_t>(
            q1_moe_w8a8_quantize_value(
                device_bf16_to_float(inputs[base + index]),
                inverse_scale
            )
        );
    }
}

// Decode-only dense W8A8 corridors need both the exact BF16 endpoint and the
// activation-quantized vector.  Publishing them in one block removes the
// duplicate launch and input traversal while preserving the established BF16
// rounding and block-wide maximum-reduction order.  Every lane publishes all
// of its BF16 endpoints before the first synchronization; this is required
// because the attention corridors intentionally alias the F32 source scratch
// with the smaller int8 destination scratch.  Reading the endpoint buffer in
// the quantization pass also avoids retaining 16 values per lane across the
// reduction, which would sharply reduce occupancy on gfx1151.
__global__ __launch_bounds__(kQ1MoeW8A8QuantizeThreads)
void q1_w8a8_f32_to_bf16_quantize_kernel(
    const float *inputs,
    uint16_t *bf16_outputs,
    int8_t *quantized_outputs,
    float *scales,
    unsigned int vector_size,
    unsigned int vector_count
) {
    const unsigned int vector = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (vector >= vector_count || vector_size > kValueFeatures) {
        return;
    }
    const size_t base = static_cast<size_t>(vector) * vector_size;
    float maximum = 0.0f;
    for (unsigned int index = lane;
         index < vector_size;
         index += kQ1MoeW8A8QuantizeThreads) {
        const uint16_t endpoint = device_float_to_bf16(inputs[base + index]);
        bf16_outputs[base + index] = endpoint;
        maximum = fmaxf(
            maximum,
            fabsf(device_bf16_to_float(endpoint))
        );
    }

    __shared__ float maxima[kQ1MoeW8A8QuantizeThreads];
    maxima[lane] = maximum;
    // Besides starting the identical maximum tree, this barrier guarantees
    // that an aliased int8 write cannot clobber another lane's unread F32.
    __syncthreads();
#pragma unroll
    for (unsigned int offset = kQ1MoeW8A8QuantizeThreads / 2u;
         offset > 0u;
         offset >>= 1u) {
        if (lane < offset) {
            maxima[lane] = fmaxf(maxima[lane], maxima[lane + offset]);
        }
        __syncthreads();
    }
    const float scale = maxima[0] > 0.0f ? maxima[0] / 127.0f : 1.0f;
    const float inverse_scale = 1.0f / scale;
    if (lane == 0u) {
        scales[vector] = scale;
    }
    for (unsigned int index = lane;
         index < vector_size;
         index += kQ1MoeW8A8QuantizeThreads) {
        quantized_outputs[base + index] = static_cast<int8_t>(
            q1_moe_w8a8_quantize_value(
                device_bf16_to_float(bf16_outputs[base + index]),
                inverse_scale
            )
        );
    }
}

// Post-prefill model compaction uses one block per grid-stride row and eight
// wave32 groups per block.  Each lane covers four adjacent wave-width
// segments, so one wave computes a complete group128 maximum and quantizes
// all 128 values without block-wide synchronization.  The destination stays
// row-major for direct expert-ID addressing during decode.
__global__ __launch_bounds__(kQ1MoeW8A8QuantizeThreads)
void q1_moe_w8a8_quantize_weight_rows_kernel(
    const uint16_t *source,
    int8_t *destination,
    float *scales,
    unsigned int row_size,
    unsigned int row_count
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int group_count = row_size / kQ1MoeW8A8GroupSize;
    for (unsigned int row = blockIdx.x;
         row < row_count;
         row += gridDim.x) {
        const size_t row_base = static_cast<size_t>(row) * row_size;
        const size_t scale_base = static_cast<size_t>(row) * group_count;
        for (unsigned int group = wave;
             group < group_count;
             group += kQ1MoeRawWavesPerBlock) {
            float values[kQ1MoeW8A8ValuesPerLane];
            float local_maximum = 0.0f;
#pragma unroll
            for (unsigned int segment = 0u;
                 segment < kQ1MoeW8A8ValuesPerLane;
                 ++segment) {
                const unsigned int column =
                    group * kQ1MoeW8A8GroupSize +
                    segment * kQ1MoeRawWaveSize + lane;
                values[segment] = device_bf16_to_float(
                    source[row_base + column]
                );
                local_maximum = fmaxf(
                    local_maximum,
                    fabsf(values[segment])
                );
            }
            const float maximum = __shfl(
                q1_moe_w8a8_wave_max(local_maximum),
                0u,
                kQ1MoeRawWaveSize
            );
            const float scale = maximum > 0.0f
                ? maximum / 127.0f
                : 1.0f;
            const float inverse_scale = 1.0f / scale;
#pragma unroll
            for (unsigned int segment = 0u;
                 segment < kQ1MoeW8A8ValuesPerLane;
                 ++segment) {
                const unsigned int column =
                    group * kQ1MoeW8A8GroupSize +
                    segment * kQ1MoeRawWaveSize + lane;
                destination[row_base + column] = static_cast<int8_t>(
                    q1_moe_w8a8_quantize_value(
                        values[segment],
                        inverse_scale
                    )
                );
            }
            if (lane == 0u) {
                scales[scale_base + group] = scale;
            }
        }
    }
}

// The short-prefill selected-MoE route may keep its per-group scales in FP16.
// This is a distinct kernel from the decode W8A8 packer: decode keeps FP32
// scales, while the resident q8192 surface uses the smaller ABI negotiated
// with its provider DLL.
__global__ __launch_bounds__(kQ1MoeW8A8QuantizeThreads)
void q8192_short_weight_int8_quantize_weight_rows_kernel(
    const uint16_t *source,
    int8_t *destination,
    Q8192ShortWeightInt8Scale *scales,
    unsigned int row_size,
    unsigned int row_count
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int group_count = row_size / kQ1MoeW8A8GroupSize;
    for (unsigned int row = blockIdx.x;
         row < row_count;
         row += gridDim.x) {
        const size_t row_base = static_cast<size_t>(row) * row_size;
        const size_t scale_base = static_cast<size_t>(row) * group_count;
        for (unsigned int group = wave;
             group < group_count;
             group += kQ1MoeRawWavesPerBlock) {
            float values[kQ1MoeW8A8ValuesPerLane];
            float local_maximum = 0.0f;
#pragma unroll
            for (unsigned int segment = 0u;
                 segment < kQ1MoeW8A8ValuesPerLane;
                 ++segment) {
                const unsigned int column =
                    group * kQ1MoeW8A8GroupSize +
                    segment * kQ1MoeRawWaveSize + lane;
                values[segment] = device_bf16_to_float(
                    source[row_base + column]
                );
                local_maximum = fmaxf(
                    local_maximum,
                    fabsf(values[segment])
                );
            }
            const float maximum = __shfl(
                q1_moe_w8a8_wave_max(local_maximum),
                0u,
                kQ1MoeRawWaveSize
            );
            const float scale = maximum > 0.0f
                ? maximum / 127.0f
                : 1.0f;
            const float inverse_scale = 1.0f / scale;
#pragma unroll
            for (unsigned int segment = 0u;
                 segment < kQ1MoeW8A8ValuesPerLane;
                 ++segment) {
                const unsigned int column =
                    group * kQ1MoeW8A8GroupSize +
                    segment * kQ1MoeRawWaveSize + lane;
                destination[row_base + column] = static_cast<int8_t>(
                    q1_moe_w8a8_quantize_value(
                        values[segment],
                        inverse_scale
                    )
                );
            }
            if (lane == 0u) {
#if QRT_QWEN36_Q8192_WEIGHT_INT8_FP16_SCALES
                scales[scale_base + group] = __float2half(scale);
#else
                scales[scale_base + group] = scale;
#endif
            }
        }
    }
}

// Real model compaction for the packed-W6 route.  One wave owns one group32:
// every lane quantizes one BF16 source value and the first eight lanes pack
// four signed six-bit codes into three contiguous bytes.  Rows remain directly
// addressable by expert ID while shrinking the routed payload by 25 percent.
__global__ __launch_bounds__(kQ1MoeW8A8QuantizeThreads)
void q1_moe_packed_w6_quantize_weight_rows_kernel(
    const uint16_t *source,
    uint8_t *destination,
    float *scales,
    unsigned int row_size,
    unsigned int row_count
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int group_count = row_size / kQ1MoePackedW6GroupSize;
    const unsigned int packed_row_bytes =
        row_size / kQ1MoePackedW6ValuesPerDot *
        kQ1MoePackedW6BytesPerDot;
    constexpr unsigned int kPackedGroupBytes =
        kQ1MoePackedW6GroupSize / kQ1MoePackedW6ValuesPerDot *
        kQ1MoePackedW6BytesPerDot;
    for (unsigned int row = blockIdx.x;
         row < row_count;
         row += gridDim.x) {
        const size_t source_row_base = static_cast<size_t>(row) * row_size;
        const size_t destination_row_base =
            static_cast<size_t>(row) * packed_row_bytes;
        const size_t scale_base = static_cast<size_t>(row) * group_count;
        for (unsigned int group = wave;
             group < group_count;
             group += kQ1MoeRawWavesPerBlock) {
            const unsigned int column =
                group * kQ1MoePackedW6GroupSize + lane;
            const float value = device_bf16_to_float(
                source[source_row_base + column]
            );
            const float maximum = __shfl(
                q1_moe_w8a8_wave_max(fabsf(value)),
                0u,
                kQ1MoeRawWaveSize
            );
            const float scale = maximum > 0.0f
                ? maximum / static_cast<float>(kQ1MoePackedW6MaximumCode)
                : 1.0f;
            const int quantized = q1_moe_packed_w6_quantize_value(
                value,
                1.0f / scale
            );
            const unsigned int packed_lane = lane & 7u;
            const unsigned int source_lane =
                packed_lane * kQ1MoePackedW6ValuesPerDot;
            const uint32_t q0 = static_cast<uint32_t>(__shfl(
                quantized,
                source_lane + 0u,
                kQ1MoeRawWaveSize
            )) & 63u;
            const uint32_t q1 = static_cast<uint32_t>(__shfl(
                quantized,
                source_lane + 1u,
                kQ1MoeRawWaveSize
            )) & 63u;
            const uint32_t q2 = static_cast<uint32_t>(__shfl(
                quantized,
                source_lane + 2u,
                kQ1MoeRawWaveSize
            )) & 63u;
            const uint32_t q3 = static_cast<uint32_t>(__shfl(
                quantized,
                source_lane + 3u,
                kQ1MoeRawWaveSize
            )) & 63u;
            if (lane < 8u) {
                const uint32_t bits =
                    q0 | (q1 << 6u) | (q2 << 12u) | (q3 << 18u);
                const size_t byte = destination_row_base +
                    static_cast<size_t>(group) * kPackedGroupBytes +
                    packed_lane * kQ1MoePackedW6BytesPerDot;
                destination[byte + 0u] = static_cast<uint8_t>(bits);
                destination[byte + 1u] = static_cast<uint8_t>(bits >> 8u);
                destination[byte + 2u] = static_cast<uint8_t>(bits >> 16u);
            }
            if (lane == 0u) {
                scales[scale_base + group] = scale;
            }
        }
    }
}

// Fixed decode matrices use the same group128 weight layout and dynamic
// per-vector activation scale as the retained all-expert W8A8 provider.  One
// wave owns one output row; packed signed dot4 keeps the batch-one path native
// to gfx1151 while preserving the established BF16 matrix endpoint.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_dense_w8a8_projection_bf16_kernel(
    const int8_t *weights,
    const float *weight_scales,
    const int8_t *input,
    const float *input_scale,
    uint16_t *output,
    unsigned int row_size,
    unsigned int row_count
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    if (row >= row_count) {
        return;
    }
    const unsigned int group_count =
        row_size / kQ1MoeW8A8GroupSize;
    const unsigned int packed_words_per_group =
        kQ1MoeW8A8GroupSize / 4u;
    const unsigned int packed_k = row_size / 4u;
    const char4 *row_weights = reinterpret_cast<const char4 *>(
        weights + static_cast<size_t>(row) * row_size
    );
    const float *row_scales = weight_scales +
        static_cast<size_t>(row) * group_count;
    const char4 *input_words = reinterpret_cast<const char4 *>(input);
    const float activation_scale = input_scale[0];
    float sum = 0.0f;
    for (unsigned int packed = lane;
         packed < packed_k;
         packed += kQ1MoeRawWaveSize) {
        const unsigned int group = packed / packed_words_per_group;
        sum += static_cast<float>(amd_mixed_dot(
            input_words[packed],
            row_weights[packed],
            0,
            false
        )) * row_scales[group] * activation_scale;
    }
    sum = q1_moe_raw_wave_tree_sum(sum);
    if (lane == 0u) {
        output[row] = device_float_to_bf16(sum);
    }
}

// Dense batch-one projections reuse the retained dynamic signed-int8 input,
// but compact each group32 weight row to four signed six-bit values per three
// bytes.  The per-row recurrence, native dot4, wave tree, and BF16 matrix
// endpoint match the routed packed-W6 provider already accepted by gb10.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_dense_packed_w6_projection_bf16_kernel(
    const uint8_t *weights,
    const float *weight_scales,
    const int8_t *input,
    const float *input_scale,
    uint16_t *output,
    unsigned int row_size,
    unsigned int row_count
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    if (row >= row_count) {
        return;
    }
    const unsigned int group_count =
        row_size / kQ1MoePackedW6GroupSize;
    const unsigned int packed_words_per_group =
        kQ1MoePackedW6GroupSize / kQ1MoePackedW6ValuesPerDot;
    const unsigned int packed_k =
        row_size / kQ1MoePackedW6ValuesPerDot;
    const unsigned int packed_row_bytes =
        packed_k * kQ1MoePackedW6BytesPerDot;
    const uint8_t *row_weights = weights +
        static_cast<size_t>(row) * packed_row_bytes;
    const float *row_scales = weight_scales +
        static_cast<size_t>(row) * group_count;
    const char4 *input_words = reinterpret_cast<const char4 *>(input);
    const float activation_scale = input_scale[0];
    float sum = 0.0f;
    for (unsigned int packed = lane;
         packed < packed_k;
         packed += kQ1MoeRawWaveSize) {
        const unsigned int group = packed / packed_words_per_group;
        const char4 weight = q1_moe_packed_w6_load_char4(
            row_weights +
                static_cast<size_t>(packed) *
                    kQ1MoePackedW6BytesPerDot
        );
        sum += static_cast<float>(amd_mixed_dot(
            input_words[packed],
            weight,
            0,
            false
        )) * row_scales[group] * activation_scale;
    }
    sum = q1_moe_raw_wave_tree_sum(sum);
    if (lane == 0u) {
        output[row] = device_float_to_bf16(sum);
    }
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_dense_w8a8_dual_projection_f32_kernel(
    const int8_t *first_weights,
    const float *first_weight_scales,
    const int8_t *second_weights,
    const float *second_weight_scales,
    const int8_t *input,
    const float *input_scale,
    float *output,
    unsigned int row_size,
    unsigned int rows_per_matrix
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int combined_row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    if (combined_row >= 2u * rows_per_matrix) {
        return;
    }
    const bool second = combined_row >= rows_per_matrix;
    const unsigned int row = second
        ? combined_row - rows_per_matrix
        : combined_row;
    const unsigned int group_count =
        row_size / kQ1MoeW8A8GroupSize;
    const unsigned int packed_words_per_group =
        kQ1MoeW8A8GroupSize / 4u;
    const unsigned int packed_k = row_size / 4u;
    const int8_t *matrix_weights = second ? second_weights : first_weights;
    const float *matrix_scales = second
        ? second_weight_scales
        : first_weight_scales;
    const char4 *row_weights = reinterpret_cast<const char4 *>(
        matrix_weights + static_cast<size_t>(row) * row_size
    );
    const float *row_scales = matrix_scales +
        static_cast<size_t>(row) * group_count;
    const char4 *input_words = reinterpret_cast<const char4 *>(input);
    const float activation_scale = input_scale[0];
    float sum = 0.0f;
    for (unsigned int packed = lane;
         packed < packed_k;
         packed += kQ1MoeRawWaveSize) {
        const unsigned int group = packed / packed_words_per_group;
        sum += static_cast<float>(amd_mixed_dot(
            input_words[packed],
            row_weights[packed],
            0,
            false
        )) * row_scales[group] * activation_scale;
    }
    sum = q1_moe_raw_wave_tree_sum(sum);
    if (lane == 0u) {
        output[combined_row] = sum;
    }
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_w8a8_dynamic_gate_up_activation_kernel(
    const uint16_t *all_gate_up_weights,
    const int8_t *input,
    const float *input_scale,
    const uint32_t *device_topk_ids,
    uint16_t *activated
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    constexpr unsigned int kRowCount =
        QRT_QWEN36_EXPERTS_PER_TOKEN *
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    if (row >= kRowCount) {
        return;
    }
    const unsigned int route =
        row / QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const unsigned int projection_row =
        row - route * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const unsigned int expert = device_topk_ids[route];
    constexpr size_t kProjectionElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint16_t *gate_weights = all_gate_up_weights + expert_base +
        static_cast<size_t>(projection_row) * QRT_QWEN36_HIDDEN_SIZE;
    const uint16_t *up_weights = all_gate_up_weights + expert_base +
        kProjectionElements +
        static_cast<size_t>(projection_row) * QRT_QWEN36_HIDDEN_SIZE;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    constexpr unsigned int kGroupCount =
        QRT_QWEN36_HIDDEN_SIZE / kQ1MoeW8A8GroupSize;
#pragma unroll 1
    for (unsigned int group = 0u; group < kGroupCount; ++group) {
        float gate_values[kQ1MoeW8A8ValuesPerLane];
        float up_values[kQ1MoeW8A8ValuesPerLane];
        float gate_local_maximum = 0.0f;
        float up_local_maximum = 0.0f;
#pragma unroll
        for (unsigned int segment = 0u;
             segment < kQ1MoeW8A8ValuesPerLane;
             ++segment) {
            const unsigned int column =
                group * kQ1MoeW8A8GroupSize +
                segment * kQ1MoeRawWaveSize + lane;
            gate_values[segment] = device_bf16_to_float(
                gate_weights[column]
            );
            up_values[segment] = device_bf16_to_float(up_weights[column]);
            gate_local_maximum = fmaxf(
                gate_local_maximum,
                fabsf(gate_values[segment])
            );
            up_local_maximum = fmaxf(
                up_local_maximum,
                fabsf(up_values[segment])
            );
        }
        const float gate_max = __shfl(
            q1_moe_w8a8_wave_max(gate_local_maximum),
            0u,
            kQ1MoeRawWaveSize
        );
        const float up_max = __shfl(
            q1_moe_w8a8_wave_max(up_local_maximum),
            0u,
            kQ1MoeRawWaveSize
        );
        const float gate_scale = gate_max > 0.0f
            ? gate_max / 127.0f
            : 1.0f;
        const float up_scale = up_max > 0.0f
            ? up_max / 127.0f
            : 1.0f;
        int gate_group_sum = 0;
        int up_group_sum = 0;
#pragma unroll
        for (unsigned int segment = 0u;
             segment < kQ1MoeW8A8ValuesPerLane;
             ++segment) {
            const unsigned int column =
                group * kQ1MoeW8A8GroupSize +
                segment * kQ1MoeRawWaveSize + lane;
            const int input_value = static_cast<int>(input[column]);
            gate_group_sum += q1_moe_w8a8_quantize_value(
                gate_values[segment],
                1.0f / gate_scale
            ) * input_value;
            up_group_sum += q1_moe_w8a8_quantize_value(
                up_values[segment],
                1.0f / up_scale
            ) * input_value;
        }
        gate_group_sum = q1_moe_w8a8_wave_tree_sum_i32(gate_group_sum);
        up_group_sum = q1_moe_w8a8_wave_tree_sum_i32(up_group_sum);
        if (lane == 0u) {
            gate_sum += static_cast<float>(gate_group_sum) * gate_scale *
                input_scale[0];
            up_sum += static_cast<float>(up_group_sum) * up_scale *
                input_scale[0];
        }
    }
    if (lane == 0u) {
        const uint16_t gate_bf16 = device_float_to_bf16(gate_sum);
        const uint16_t up_bf16 = device_float_to_bf16(up_sum);
        activated[row] = device_float_to_bf16(
            device_silu_f32(device_bf16_to_float(gate_bf16)) *
            device_bf16_to_float(up_bf16)
        );
    }
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_w8a8_dynamic_down_kernel(
    const uint16_t *all_down_weights,
    const int8_t *activated,
    const float *activation_scales,
    const uint32_t *device_topk_ids,
    uint16_t *route_outputs
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    constexpr unsigned int kRowCount =
        QRT_QWEN36_EXPERTS_PER_TOKEN * QRT_QWEN36_HIDDEN_SIZE;
    if (row >= kRowCount) {
        return;
    }
    const unsigned int route = row / QRT_QWEN36_HIDDEN_SIZE;
    const unsigned int projection_row =
        row - route * QRT_QWEN36_HIDDEN_SIZE;
    const unsigned int expert = device_topk_ids[route];
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
    const uint16_t *weights = all_down_weights + expert_base +
        static_cast<size_t>(projection_row) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const int8_t *route_input = activated +
        static_cast<size_t>(route) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    float sum = 0.0f;
    constexpr unsigned int kGroupCount =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / kQ1MoeW8A8GroupSize;
#pragma unroll
    for (unsigned int group = 0u; group < kGroupCount; ++group) {
        float weight_values[kQ1MoeW8A8ValuesPerLane];
        float local_maximum = 0.0f;
#pragma unroll
        for (unsigned int segment = 0u;
             segment < kQ1MoeW8A8ValuesPerLane;
             ++segment) {
            const unsigned int column =
                group * kQ1MoeW8A8GroupSize +
                segment * kQ1MoeRawWaveSize + lane;
            weight_values[segment] = device_bf16_to_float(weights[column]);
            local_maximum = fmaxf(
                local_maximum,
                fabsf(weight_values[segment])
            );
        }
        const float maximum = __shfl(
            q1_moe_w8a8_wave_max(local_maximum),
            0u,
            kQ1MoeRawWaveSize
        );
        const float weight_scale = maximum > 0.0f
            ? maximum / 127.0f
            : 1.0f;
        int group_sum = 0;
#pragma unroll
        for (unsigned int segment = 0u;
             segment < kQ1MoeW8A8ValuesPerLane;
             ++segment) {
            const unsigned int column =
                group * kQ1MoeW8A8GroupSize +
                segment * kQ1MoeRawWaveSize + lane;
            group_sum += q1_moe_w8a8_quantize_value(
                weight_values[segment],
                1.0f / weight_scale
            ) * static_cast<int>(route_input[column]);
        }
        group_sum = q1_moe_w8a8_wave_tree_sum_i32(group_sum);
        if (lane == 0u) {
            sum += static_cast<float>(group_sum) * weight_scale *
                activation_scales[route];
        }
    }
    if (lane == 0u) {
        route_outputs[row] = device_float_to_bf16(sum);
    }
}

// A single thread owns the fully-associative cache directory for one layer.
// The eight routes are reserved as a transaction so an eviction selected for
// a later route cannot overwrite a slot still consumed by the current token.
__global__ void q1_moe_w8a8_cache_select_kernel(
    const uint32_t *device_topk_ids,
    uint32_t *metadata,
    uint32_t *global_counters
) {
    if (blockIdx.x != 0u || threadIdx.x != 0u) {
        return;
    }
    uint32_t *tags = metadata + kQ1MoeW8A8CacheTagsOffset;
    uint32_t *ages = metadata + kQ1MoeW8A8CacheAgesOffset;
    uint32_t *route_slots =
        metadata + kQ1MoeW8A8CacheRouteSlotsOffset;
    uint32_t *route_misses =
        metadata + kQ1MoeW8A8CacheRouteMissesOffset;
    uint32_t clock = metadata[kQ1MoeW8A8CacheClockOffset];
    uint32_t reserved_mask = 0u;
    uint32_t hits = 0u;
    uint32_t misses = 0u;
    uint32_t evictions = 0u;
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const uint32_t expert = device_topk_ids[route];
        uint32_t selected_slot = kQ1MoeW8A8CacheCapacity;
        for (uint32_t slot = 0u;
             slot < kQ1MoeW8A8CacheCapacity;
             ++slot) {
            if (tags[slot] == expert) {
                selected_slot = slot;
                break;
            }
        }
        bool miss = selected_slot == kQ1MoeW8A8CacheCapacity;
        if (miss) {
            for (uint32_t slot = 0u;
                 slot < kQ1MoeW8A8CacheCapacity;
                 ++slot) {
                if ((reserved_mask & (UINT32_C(1) << slot)) == 0u &&
                    tags[slot] == UINT32_MAX) {
                    selected_slot = slot;
                    break;
                }
            }
            if (selected_slot == kQ1MoeW8A8CacheCapacity) {
                uint32_t oldest_age = UINT32_MAX;
                for (uint32_t slot = 0u;
                     slot < kQ1MoeW8A8CacheCapacity;
                     ++slot) {
                    if ((reserved_mask & (UINT32_C(1) << slot)) == 0u &&
                        ages[slot] <= oldest_age) {
                        oldest_age = ages[slot];
                        selected_slot = slot;
                    }
                }
            }
            if (tags[selected_slot] != UINT32_MAX) {
                ++evictions;
            }
            tags[selected_slot] = expert;
            ++misses;
        } else {
            ++hits;
        }
        ++clock;
        ages[selected_slot] = clock;
        route_slots[route] = selected_slot;
        route_misses[route] = miss ? 1u : 0u;
        reserved_mask |= UINT32_C(1) << selected_slot;
    }
    metadata[kQ1MoeW8A8CacheClockOffset] = clock;
    atomicAdd(global_counters + kQ1MoeW8A8CacheHitCounter, hits);
    atomicAdd(global_counters + kQ1MoeW8A8CacheMissCounter, misses);
    atomicAdd(global_counters + kQ1MoeW8A8CacheEvictionCounter, evictions);
    atomicAdd(global_counters + kQ1MoeW8A8CacheSelectionCounter, 1u);
}

// A bounded grid walks source rows in grid-stride order.  Its eight wave32
// groups quantize eight independent group128 chunks at a time.  Hit routes
// only traverse the small row directory and never touch the raw BF16 model;
// misses materialize both W13 and W2 into the layer cache exactly once.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_w8a8_cache_fill_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *all_down_weights,
    const uint32_t *device_topk_ids,
    const uint32_t *metadata,
    int8_t *cached_gate_up,
    float *cached_gate_up_scales,
    int8_t *cached_down,
    float *cached_down_scales
) {
    constexpr unsigned int kGateUpRows =
        2u * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    constexpr unsigned int kRowsPerRoute =
        kGateUpRows + QRT_QWEN36_HIDDEN_SIZE;
    constexpr unsigned int kTransactionRows =
        QRT_QWEN36_EXPERTS_PER_TOKEN * kRowsPerRoute;
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    for (unsigned int transaction_row = blockIdx.x;
         transaction_row < kTransactionRows;
         transaction_row += gridDim.x) {
        const unsigned int route = transaction_row / kRowsPerRoute;
        if (metadata[
                kQ1MoeW8A8CacheRouteMissesOffset + route
            ] == 0u) {
            continue;
        }
        const unsigned int local_row =
            transaction_row - route * kRowsPerRoute;
        const uint32_t expert = device_topk_ids[route];
        const uint32_t slot =
            metadata[kQ1MoeW8A8CacheRouteSlotsOffset + route];
        const uint16_t *source = nullptr;
        int8_t *destination = nullptr;
        float *scales = nullptr;
        unsigned int row_size = 0u;
        unsigned int group_count = 0u;
        if (local_row < kGateUpRows) {
            row_size = QRT_QWEN36_HIDDEN_SIZE;
            group_count = row_size / kQ1MoeW8A8GroupSize;
            source = all_gate_up_weights +
                static_cast<size_t>(expert) *
                    kQ1MoeW8A8GateUpElementsPerExpert +
                static_cast<size_t>(local_row) * row_size;
            destination = cached_gate_up +
                static_cast<size_t>(slot) *
                    kQ1MoeW8A8GateUpElementsPerExpert +
                static_cast<size_t>(local_row) * row_size;
            scales = cached_gate_up_scales +
                static_cast<size_t>(slot) *
                    kQ1MoeW8A8GateUpScalesPerExpert +
                static_cast<size_t>(local_row) * group_count;
        } else {
            const unsigned int down_row = local_row - kGateUpRows;
            row_size = QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            group_count = row_size / kQ1MoeW8A8GroupSize;
            source = all_down_weights +
                static_cast<size_t>(expert) *
                    kQ1MoeW8A8DownElementsPerExpert +
                static_cast<size_t>(down_row) * row_size;
            destination = cached_down +
                static_cast<size_t>(slot) *
                    kQ1MoeW8A8DownElementsPerExpert +
                static_cast<size_t>(down_row) * row_size;
            scales = cached_down_scales +
                static_cast<size_t>(slot) *
                    kQ1MoeW8A8DownScalesPerExpert +
                static_cast<size_t>(down_row) * group_count;
        }
        for (unsigned int group = wave;
             group < group_count;
             group += kQ1MoeRawWavesPerBlock) {
            float values[kQ1MoeW8A8ValuesPerLane];
            float local_maximum = 0.0f;
#pragma unroll
            for (unsigned int segment = 0u;
                 segment < kQ1MoeW8A8ValuesPerLane;
                 ++segment) {
                const unsigned int column =
                    group * kQ1MoeW8A8GroupSize +
                    segment * kQ1MoeRawWaveSize + lane;
                values[segment] = device_bf16_to_float(source[column]);
                local_maximum = fmaxf(
                    local_maximum,
                    fabsf(values[segment])
                );
            }
            const float maximum = __shfl(
                q1_moe_w8a8_wave_max(local_maximum),
                0u,
                kQ1MoeRawWaveSize
            );
            const float scale = maximum > 0.0f
                ? maximum / 127.0f
                : 1.0f;
            const float inverse_scale = 1.0f / scale;
#pragma unroll
            for (unsigned int segment = 0u;
                 segment < kQ1MoeW8A8ValuesPerLane;
                 ++segment) {
                const unsigned int column =
                    group * kQ1MoeW8A8GroupSize +
                    segment * kQ1MoeRawWaveSize + lane;
                destination[column] = static_cast<int8_t>(
                    q1_moe_w8a8_quantize_value(
                        values[segment],
                        inverse_scale
                    )
                );
            }
            if (lane == 0u) {
                scales[group] = scale;
            }
        }
    }
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_w8a8_cached_gate_up_activation_kernel(
    const int8_t *cached_gate_up,
    const float *cached_gate_up_scales,
    const int8_t *input,
    const float *input_scale,
    const uint32_t *route_indices,
    unsigned int route_index_offset,
