) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    constexpr unsigned int kRowCount =
        QRT_QWEN36_EXPERTS_PER_TOKEN *
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    if (row >= kRowCount) {
        return;
    }
    const unsigned int route =
        row / QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const unsigned int projection_row =
        row - route * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const uint32_t slot =
        route_indices[route_index_offset + route];
    constexpr size_t kProjectionElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    constexpr unsigned int kGroupCount =
        QRT_QWEN36_HIDDEN_SIZE / kQ1MoeW8A8GroupSize;
    constexpr unsigned int kPackedWordsPerGroup =
        kQ1MoeW8A8GroupSize / 4u;
    constexpr unsigned int kPackedK = QRT_QWEN36_HIDDEN_SIZE / 4u;
