// Batch-one routed MoE uses the device router IDs to address the existing raw
// all-expert BF16 arena directly.  Eight wave32 reductions own eight rows per
// block; every lane consumes a coalesced strided slice of K through the native
// BF16 dot2 recurrence.  Gate, up, and SiLU*up are all rounded at the same BF16
// endpoints as the retained hipBLASLt-plus-pointwise path.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_raw_gate_up_activation_wave_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *input,
    const uint32_t *device_topk_ids,
    uint16_t *gate_endpoints,
    uint16_t *up_endpoints,
    uint16_t *activated
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kBlocksPerRoute =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE /
        kQ1MoeRawWavesPerBlock;
    const unsigned int route = blockIdx.x / kBlocksPerRoute;
    const unsigned int route_block =
        blockIdx.x - route * kBlocksPerRoute;
    const unsigned int row =
        route_block * kQ1MoeRawWavesPerBlock + wave;
    const unsigned int expert = device_topk_ids[route];
    constexpr size_t kGateElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint32_t *input_pairs =
        reinterpret_cast<const uint32_t *>(input);
    const uint32_t *gate_pairs = reinterpret_cast<const uint32_t *>(
        all_gate_up_weights + expert_base +
        static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    const uint32_t *up_pairs = reinterpret_cast<const uint32_t *>(
        all_gate_up_weights + expert_base + kGateElements +
        static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    constexpr unsigned int kPairCount = QRT_QWEN36_HIDDEN_SIZE / 2u;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    for (unsigned int pair = lane;
         pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        const uint32_t input_pair = input_pairs[pair];
        gate_sum = device_dot2_f32_bf16(
            input_pair,
            gate_pairs[pair],
            gate_sum
        );
        up_sum = device_dot2_f32_bf16(
            input_pair,
            up_pairs[pair],
            up_sum
        );
    }
    gate_sum = q1_moe_raw_wave_tree_sum(gate_sum);
    up_sum = q1_moe_raw_wave_tree_sum(up_sum);

    if (lane == 0u) {
        const size_t output = static_cast<size_t>(route) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + row;
        const uint16_t gate_bf16 = device_float_to_bf16(gate_sum);
        const uint16_t up_bf16 = device_float_to_bf16(up_sum);
        gate_endpoints[output] = gate_bf16;
        up_endpoints[output] = up_bf16;
        activated[output] = device_float_to_bf16(
            device_silu_f32(device_bf16_to_float(gate_bf16)) *
            device_bf16_to_float(up_bf16)
        );
    }
}

// The down projection keeps one independent BF16 endpoint per original route.
// The existing route-order combine kernel remains the sole consumer, so its
// separate multiply/add sequence and router order are unchanged.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_raw_down_wave_kernel(
    const uint16_t *all_down_weights,
    const uint16_t *activated,
