    uint16_t *route_outputs
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kBlocksPerRoute =
        QRT_QWEN36_HIDDEN_SIZE / kQ1MoeRawWavesPerBlock;
    const unsigned int route = blockIdx.x / kBlocksPerRoute;
    const unsigned int route_block =
        blockIdx.x - route * kBlocksPerRoute;
    const unsigned int row =
        route_block * kQ1MoeRawWavesPerBlock + wave;
    const unsigned int expert = device_topk_ids[route];
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
    const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(
        activated + static_cast<size_t>(route) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    const uint32_t *weight_pairs = reinterpret_cast<const uint32_t *>(
        all_down_weights + expert_base +
        static_cast<size_t>(row) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    constexpr unsigned int kPairCount =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / 2u;
    float sum = 0.0f;
    for (unsigned int pair = lane;
         pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        sum = device_dot2_f32_bf16(
            input_pairs[pair],
            weight_pairs[pair],
            sum
        );
    }
    sum = q1_moe_raw_wave_tree_sum(sum);
    if (lane == 0u) {
        route_outputs[
            static_cast<size_t>(route) * QRT_QWEN36_HIDDEN_SIZE + row
        ] = device_float_to_bf16(sum);
    }
}

// 0626-reference gate/up decomposition: one block owns exactly one selected
// expert output row.  Four wave32s split hidden=2048, then reduce their FP32
// partials through shared memory.  The established native endpoint contract
// is retained: gate and up round to BF16 before SiLU*up rounds to BF16.
__global__ __launch_bounds__(kQ1Moe0626GateUpBlockThreads)
void q1_moe_0626_gate_up_row_parallel_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *input,
    const uint32_t *device_topk_ids,
    uint16_t *activated
) {
    __shared__ float gate_wave_sums[kQ1Moe0626GateUpWavesPerBlock];
    __shared__ float up_wave_sums[kQ1Moe0626GateUpWavesPerBlock];

    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int route =
        blockIdx.x / QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const unsigned int row =
        blockIdx.x - route * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const unsigned int expert = device_topk_ids[route];
    constexpr size_t kGateElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint32_t *input_pairs =
        reinterpret_cast<const uint32_t *>(input);
    const uint32_t *gate_pairs = reinterpret_cast<const uint32_t *>(
        all_gate_up_weights + expert_base +
        static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    const uint32_t *up_pairs = reinterpret_cast<const uint32_t *>(
        all_gate_up_weights + expert_base + kGateElements +
        static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    constexpr unsigned int kPairCount = QRT_QWEN36_HIDDEN_SIZE / 2u;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    for (unsigned int pair = threadIdx.x; pair < kPairCount;
         pair += kQ1Moe0626GateUpBlockThreads) {
        const uint32_t input_pair = input_pairs[pair];
        gate_sum = device_dot2_f32_bf16(
            input_pair,
            gate_pairs[pair],
            gate_sum
        );
        up_sum = device_dot2_f32_bf16(
            input_pair,
            up_pairs[pair],
            up_sum
        );
    }
    gate_sum = q1_moe_raw_wave_tree_sum(gate_sum);
    up_sum = q1_moe_raw_wave_tree_sum(up_sum);
    if (lane == 0u) {
        gate_wave_sums[wave] = gate_sum;
        up_wave_sums[wave] = up_sum;
    }
    __syncthreads();

    if (threadIdx.x == 0u) {
        float gate_total = gate_wave_sums[0];
        float up_total = up_wave_sums[0];
        #pragma unroll
        for (unsigned int source_wave = 1u;
             source_wave < kQ1Moe0626GateUpWavesPerBlock;
             ++source_wave) {
            gate_total = device_add_separate(
                gate_total,
                gate_wave_sums[source_wave]
            );
            up_total = device_add_separate(
                up_total,
                up_wave_sums[source_wave]
            );
        }
        const uint16_t gate_bf16 = device_float_to_bf16(gate_total);
        const uint16_t up_bf16 = device_float_to_bf16(up_total);
        activated[
            static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + row
        ] = device_float_to_bf16(
            device_silu_f32(device_bf16_to_float(gate_bf16)) *
            device_bf16_to_float(up_bf16)
        );
    }
}

// 0626-reference down/sum decomposition: one wave32 block owns one hidden
// output row, walks the top-8 routes in router order, and never materializes
// the 8xhidden route-output surface.  The final routed sum is rounded to BF16
// and carried in the existing F32 buffer so the shared-expert interface and
// workspace layout remain unchanged.
__global__ __launch_bounds__(kQ1Moe0626DownBlockThreads)
void q1_moe_0626_down_sum_row_parallel_kernel(
    const uint16_t *all_down_weights,
    const uint16_t *activated,
    const uint32_t *device_topk_ids,
    const float *device_topk_weights,
    float *routed_output
) {
    const unsigned int lane = threadIdx.x;
    const unsigned int row = blockIdx.x;
    constexpr unsigned int kPairCount =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / 2u;
    float combined = 0.0f;

    #pragma unroll
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const unsigned int expert = device_topk_ids[route];
        const size_t expert_base = static_cast<size_t>(expert) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
        const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(
            activated + static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
        );
        const uint32_t *weight_pairs = reinterpret_cast<const uint32_t *>(
            all_down_weights + expert_base +
            static_cast<size_t>(row) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
        );
        float sum = 0.0f;
        for (unsigned int pair = lane; pair < kPairCount;
             pair += kQ1Moe0626DownBlockThreads) {
            sum = device_dot2_f32_bf16(
                input_pairs[pair],
                weight_pairs[pair],
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
        if (lane == 0u) {
            combined = device_mul_add_separate(
                combined,
                device_topk_weights[route],
                device_bf16_round_to_float(sum)
            );
        }
    }

    if (lane == 0u) {
        routed_output[row] = device_bf16_round_to_float(combined);
    }
}

using Q1MoePersistentDirectVector =
    uint32_t __attribute__((ext_vector_type(4)));

__device__ __forceinline__ Q1MoePersistentDirectVector
q1_moe_persistent_direct_load_weight(
    const Q1MoePersistentDirectVector *address
) {
    return __builtin_nontemporal_load(address);
}

__device__ __forceinline__ float q1_moe_persistent_direct_dot8(
    const Q1MoePersistentDirectVector &input,
    const Q1MoePersistentDirectVector &weight,
    float sum
) {
    sum = device_dot2_f32_bf16(input[0], weight[0], sum);
    sum = device_dot2_f32_bf16(input[1], weight[1], sum);
    sum = device_dot2_f32_bf16(input[2], weight[2], sum);
    sum = device_dot2_f32_bf16(input[3], weight[3], sum);
    return sum;
}

// Batch-one gfx1151 provider: a bounded persistent wave32 grid owns one
// output row per wave and streams aligned BF16x8 weights straight into VGPRs
// with non-temporal loads.  It preserves the established BF16 gate/up,
// activation, down, and route-order endpoints; only the row scheduling and
// load path differ from q1_moe_raw_*_wave_kernel.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_persistent_direct_gate_up_activation_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *input,
    const uint32_t *device_topk_ids,
    uint16_t *gate_endpoints,
    uint16_t *up_endpoints,
    uint16_t *activated
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kTasks =
        QRT_QWEN36_EXPERTS_PER_TOKEN *
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    constexpr unsigned int kVectors = QRT_QWEN36_HIDDEN_SIZE / 8u;
    constexpr size_t kGateElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    static_assert(QRT_QWEN36_HIDDEN_SIZE % 8u == 0u);

    for (unsigned int task =
             blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
         task < kTasks;
         task += gridDim.x * kQ1MoeRawWavesPerBlock) {
        const unsigned int route =
            task / QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const unsigned int row = task -
            route * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        const unsigned int expert = device_topk_ids[route];
        const size_t expert_base = static_cast<size_t>(expert) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
        const Q1MoePersistentDirectVector *input_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(input);
        const Q1MoePersistentDirectVector *gate_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                all_gate_up_weights + expert_base +
                static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
            );
        const Q1MoePersistentDirectVector *up_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                all_gate_up_weights + expert_base + kGateElements +
                static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
            );
        float gate_sum = 0.0f;
        float up_sum = 0.0f;
#pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            const Q1MoePersistentDirectVector input_vector =
                input_vectors[vector];
            const Q1MoePersistentDirectVector gate_vector =
                q1_moe_persistent_direct_load_weight(
                    gate_vectors + vector
                );
            const Q1MoePersistentDirectVector up_vector =
                q1_moe_persistent_direct_load_weight(up_vectors + vector);
            gate_sum = q1_moe_persistent_direct_dot8(
                input_vector,
                gate_vector,
                gate_sum
            );
            up_sum = q1_moe_persistent_direct_dot8(
                input_vector,
                up_vector,
                up_sum
            );
        }
        gate_sum = q1_moe_raw_wave_tree_sum(gate_sum);
        up_sum = q1_moe_raw_wave_tree_sum(up_sum);
        if (lane == 0u) {
            const size_t output = static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + row;
            const uint16_t gate_bf16 = device_float_to_bf16(gate_sum);
            const uint16_t up_bf16 = device_float_to_bf16(up_sum);
            gate_endpoints[output] = gate_bf16;
            up_endpoints[output] = up_bf16;
            activated[output] = device_float_to_bf16(
                device_silu_f32(device_bf16_to_float(gate_bf16)) *
                device_bf16_to_float(up_bf16)
            );
        }
    }
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_persistent_direct_down_kernel(
    const uint16_t *all_down_weights,
    const uint16_t *activated,
    const uint32_t *device_topk_ids,
    uint16_t *route_outputs
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kTasks =
        QRT_QWEN36_EXPERTS_PER_TOKEN * QRT_QWEN36_HIDDEN_SIZE;
    constexpr unsigned int kVectors =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / 8u;
    static_assert(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE % 8u == 0u);

    for (unsigned int task =
             blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
         task < kTasks;
         task += gridDim.x * kQ1MoeRawWavesPerBlock) {
        const unsigned int route = task / QRT_QWEN36_HIDDEN_SIZE;
        const unsigned int row =
            task - route * QRT_QWEN36_HIDDEN_SIZE;
        const unsigned int expert = device_topk_ids[route];
        const size_t expert_base = static_cast<size_t>(expert) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
        const Q1MoePersistentDirectVector *input_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                activated + static_cast<size_t>(route) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
            );
        const Q1MoePersistentDirectVector *weight_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                all_down_weights + expert_base +
                static_cast<size_t>(row) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
            );
        float sum = 0.0f;
#pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            const Q1MoePersistentDirectVector input_vector =
                input_vectors[vector];
            const Q1MoePersistentDirectVector weight_vector =
                q1_moe_persistent_direct_load_weight(
                    weight_vectors + vector
                );
            sum = q1_moe_persistent_direct_dot8(
                input_vector,
                weight_vector,
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
        if (lane == 0u) {
            route_outputs[
                static_cast<size_t>(route) * QRT_QWEN36_HIDDEN_SIZE + row
            ] = device_float_to_bf16(sum);
        }
    }
}

constexpr int32_t kQ1MoeRocblasW13SolutionIndex = INT32_C(-9);
constexpr int32_t kQ1MoeRocblasW2SolutionIndex = INT32_C(-1162086116);
constexpr int32_t kQ1MoeRocblasRouterSolutionIndex = INT32_C(-9);
constexpr int32_t kQ1LinearRocblasQkvzSolutionIndex = INT32_C(-9);
constexpr int32_t kQ1LinearRocblasOutSolutionIndex = INT32_C(-9);
constexpr int32_t kQ1FullAttentionRocblasQSolutionIndex =
    INT32_C(-1162086096);
constexpr int32_t kQ1LmHeadRocblasSolutionIndex = INT32_C(-9);
constexpr unsigned int kQ1MoeRocblasW13BatchCount =
    2u * QRT_QWEN36_EXPERTS_PER_TOKEN;
constexpr unsigned int kQ1MoeRocblasW2BatchCount =
    QRT_QWEN36_EXPERTS_PER_TOKEN;
constexpr unsigned int kQ1MoeRocblasSharedW13BatchCount =
    kQ1MoeRocblasW13BatchCount + 2u;
constexpr unsigned int kQ1MoeRocblasSharedW2BatchCount =
    kQ1MoeRocblasW2BatchCount + 1u;
constexpr size_t kQ1MoeRocblasW13PointerTableBytes =
    3u * kQ1MoeRocblasSharedW13BatchCount * sizeof(void *);
constexpr unsigned int kQ1MoeRocblasCombinedPointerCount =
    kQ1MoeRocblasSharedW13BatchCount +
    kQ1MoeRocblasSharedW2BatchCount;
constexpr size_t kQ1MoeRocblasCombinedPointerTableBytes =
    3u * kQ1MoeRocblasCombinedPointerCount * sizeof(void *);

#ifdef QRT_ENABLE_ROCBLAS_Q1_MOE_BATCHED
// The router stays device-resident.  Build the rocBLAS pointer tables on the
// same stream that consumes them so selected expert IDs never introduce a
// host fence.  W13 alternates gate/up entries to match the cold-38 solution
// screen; W2 reuses the same scratch after W13 has consumed it.
__global__ void q1_moe_rocblas_w13_pointer_table_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *shared_gate_weights,
    const uint16_t *shared_up_weights,
    const uint16_t *input,
    const uint32_t *topk_ids,
    uint16_t *gate_outputs,
    uint16_t *up_outputs,
    const uint16_t **a_ptrs,
    const uint16_t **b_ptrs,
    uint16_t **d_ptrs,
    bool include_shared
) {
    const unsigned int index = threadIdx.x;
    const unsigned int batch_count = include_shared
        ? kQ1MoeRocblasSharedW13BatchCount
        : kQ1MoeRocblasW13BatchCount;
    if (index >= batch_count) {
        return;
    }
    if (index >= kQ1MoeRocblasW13BatchCount) {
        const bool up = index == kQ1MoeRocblasW13BatchCount + 1u;
        a_ptrs[index] = up ? shared_up_weights : shared_gate_weights;
        b_ptrs[index] = input;
        d_ptrs[index] =
            (up ? up_outputs : gate_outputs) +
            static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        return;
    }
    const unsigned int route = index / 2u;
    const bool up = (index & 1u) != 0u;
    const unsigned int expert = topk_ids[route];
    constexpr size_t kProjectionElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const uint16_t *expert_weights = all_gate_up_weights +
        static_cast<size_t>(expert) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    a_ptrs[index] = expert_weights + (up ? kProjectionElements : 0u);
    b_ptrs[index] = input;
    d_ptrs[index] =
        (up ? up_outputs : gate_outputs) +
        static_cast<size_t>(route) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
}

__global__ void q1_moe_rocblas_w2_pointer_table_kernel(
    const uint16_t *all_down_weights,
    const uint16_t *shared_down_weights,
    const uint16_t *activated,
    const uint32_t *topk_ids,
    uint16_t *route_outputs,
    uint16_t *shared_down_output,
    const uint16_t **a_ptrs,
    const uint16_t **b_ptrs,
    uint16_t **d_ptrs,
    bool include_shared
) {
    const unsigned int route = threadIdx.x;
    const unsigned int batch_count = include_shared
        ? kQ1MoeRocblasSharedW2BatchCount
        : kQ1MoeRocblasW2BatchCount;
    if (route >= batch_count) {
        return;
    }
    if (route == kQ1MoeRocblasW2BatchCount) {
        a_ptrs[route] = shared_down_weights;
        b_ptrs[route] = activated +
            static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        d_ptrs[route] = shared_down_output;
        return;
    }
    const unsigned int expert = topk_ids[route];
    a_ptrs[route] = all_down_weights +
        static_cast<size_t>(expert) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
    b_ptrs[route] = activated +
        static_cast<size_t>(route) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    d_ptrs[route] = route_outputs +
        static_cast<size_t>(route) * QRT_QWEN36_HIDDEN_SIZE;
}

// The selected top-8 is already serialized by the retained deterministic
// router kernel.  Publish both rocBLAS pointer batches from that same owner so
// W13 and W2 no longer need one tiny device launch apiece.  The tables occupy
// disjoint scratch ranges because W2 pointers are now ready before W13 starts;
// all projection arithmetic, BF16 endpoints, route order, and softmax math are
// unchanged.  This is ordinary BF16 decode and does not use quantization,
// speculation, MTP, or DFlash.
__global__ void moe_router_bf16_logits_topk_rocblas_pointer_tables_kernel(
    const uint16_t *logits_bf16,
    float *logits,
    uint32_t *topk_ids,
    float *topk_weights,
    const uint16_t *all_gate_up_weights,
    const uint16_t *all_down_weights,
    const uint16_t *shared_gate_weights,
    const uint16_t *shared_up_weights,
    const uint16_t *shared_down_weights,
    const uint16_t *input,
    uint16_t *gate_outputs,
    uint16_t *up_outputs,
    uint16_t *activated,
    uint16_t *route_outputs,
    uint16_t *shared_down_output,
    const uint16_t **a_ptrs,
    const uint16_t **b_ptrs,
    uint16_t **d_ptrs,
    bool include_shared
) {
    __shared__ float shared_logits[QRT_QWEN36_EXPERT_COUNT];

    const unsigned int expert = threadIdx.x;
    if (expert >= QRT_QWEN36_EXPERT_COUNT) {
        return;
    }
    const float value = device_bf16_to_float(logits_bf16[expert]);
    shared_logits[expert] = value;
    logits[expert] = value;
    __syncthreads();

    if (expert != 0u) {
        return;
    }

    uint32_t best_ids[QRT_QWEN36_EXPERTS_PER_TOKEN];
    double exp_values[QRT_QWEN36_EXPERTS_PER_TOKEN];
    double max_value = -1.0e300;
    double denom = 0.0;
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        unsigned int best_expert = QRT_QWEN36_EXPERT_COUNT;
        for (unsigned int candidate = 0u;
             candidate < QRT_QWEN36_EXPERT_COUNT;
             ++candidate) {
            bool already_selected = false;
            for (unsigned int prior = 0u; prior < route; ++prior) {
                already_selected = already_selected ||
                    best_ids[prior] == candidate;
            }
            if (already_selected) {
                continue;
            }
            if (best_expert == QRT_QWEN36_EXPERT_COUNT ||
                shared_logits[candidate] > shared_logits[best_expert] ||
                (shared_logits[candidate] == shared_logits[best_expert] &&
                 candidate < best_expert)) {
                best_expert = candidate;
            }
        }
        best_ids[route] = best_expert;
        topk_ids[route] = best_expert;
        if (static_cast<double>(shared_logits[best_expert]) > max_value) {
            max_value = static_cast<double>(shared_logits[best_expert]);
        }
    }
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const double route_exp = exp(
            static_cast<double>(shared_logits[best_ids[route]]) - max_value
        );
        exp_values[route] = route_exp;
        denom += route_exp;
    }
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        topk_weights[route] =
            static_cast<float>(exp_values[route] / denom);
    }

    constexpr size_t kProjectionElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const unsigned int w13_batch_count = include_shared
        ? kQ1MoeRocblasSharedW13BatchCount
        : kQ1MoeRocblasW13BatchCount;
    for (unsigned int index = 0u; index < w13_batch_count; ++index) {
        if (index >= kQ1MoeRocblasW13BatchCount) {
            const bool up = index == kQ1MoeRocblasW13BatchCount + 1u;
            a_ptrs[index] = up ? shared_up_weights : shared_gate_weights;
            b_ptrs[index] = input;
            d_ptrs[index] =
                (up ? up_outputs : gate_outputs) +
                static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            continue;
        }
        const unsigned int route = index / 2u;
        const bool up = (index & 1u) != 0u;
        const uint16_t *expert_weights = all_gate_up_weights +
            static_cast<size_t>(best_ids[route]) *
                QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
        a_ptrs[index] = expert_weights + (up ? kProjectionElements : 0u);
        b_ptrs[index] = input;
        d_ptrs[index] =
            (up ? up_outputs : gate_outputs) +
            static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    }

    const unsigned int w2_offset = kQ1MoeRocblasSharedW13BatchCount;
    const unsigned int w2_batch_count = include_shared
        ? kQ1MoeRocblasSharedW2BatchCount
        : kQ1MoeRocblasW2BatchCount;
    for (unsigned int route = 0u; route < w2_batch_count; ++route) {
        const unsigned int index = w2_offset + route;
        if (route == kQ1MoeRocblasW2BatchCount) {
            a_ptrs[index] = shared_down_weights;
            b_ptrs[index] = activated +
                static_cast<size_t>(QRT_QWEN36_EXPERTS_PER_TOKEN) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            d_ptrs[index] = shared_down_output;
            continue;
        }
        a_ptrs[index] = all_down_weights +
            static_cast<size_t>(best_ids[route]) *
                QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
        b_ptrs[index] = activated +
            static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        d_ptrs[index] = route_outputs +
            static_cast<size_t>(route) * QRT_QWEN36_HIDDEN_SIZE;
    }
}

// The shared gate/up matrices have the same 512x2048 shape as each routed
// W13 matrix, so the candidate appends them to the existing pointer batch.
// This endpoint kernel activates all nine matrix pairs and uses one wave in
// the same launch for the scalar shared gate.  The wave32 dot2 recurrence,
// shuffle tree, BF16 endpoint, sigmoid and SiLU arithmetic match the retained
// raw shared kernel.
__global__ void q1_moe_rocblas_routed_shared_activation_kernel(
    const uint16_t *gate_outputs,
    const uint16_t *up_outputs,
    const uint16_t *shared_gate_scalar_weights,
    const uint16_t *input,
    uint16_t *activated,
    uint16_t *shared_gate_logit_bf16,
    float *shared_gate_scale,
    size_t activation_count
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index < activation_count) {
        const float gate = device_bf16_to_float(gate_outputs[index]);
        const float up = device_bf16_to_float(up_outputs[index]);
        activated[index] = device_float_to_bf16(
            device_silu_f32(gate) * up
        );
    }

    const unsigned int lane = threadIdx.x;
    if (blockIdx.x == 0u && lane < kQ1MoeRawWaveSize) {
        const uint32_t *input_pairs =
            reinterpret_cast<const uint32_t *>(input);
        const uint32_t *weight_pairs =
            reinterpret_cast<const uint32_t *>(
                shared_gate_scalar_weights
            );
        constexpr unsigned int kPairCount =
            QRT_QWEN36_HIDDEN_SIZE / 2u;
        float gate_logit = 0.0f;
        for (unsigned int pair = lane;
             pair < kPairCount;
             pair += kQ1MoeRawWaveSize) {
            gate_logit = device_dot2_f32_bf16(
                input_pairs[pair],
                weight_pairs[pair],
                gate_logit
            );
        }
        gate_logit = q1_moe_raw_wave_tree_sum(gate_logit);
        if (lane == 0u) {
            const uint16_t endpoint = device_float_to_bf16(gate_logit);
            shared_gate_logit_bf16[0] = endpoint;
            shared_gate_scale[0] = 1.0f /
                (1.0f + expf(-device_bf16_to_float(endpoint)));
        }
    }
}

// W2 likewise appends the shared down matrix to the eight routed matrices.
// One final row-parallel kernel preserves the original route-order separate
// multiply/add chain, then the shared FMA and separate residual add.  It
// removes the routed-output scratch round trip and the two raw-shared launches
// without changing any live arithmetic boundary after the BF16 endpoints.
__global__ void q1_moe_rocblas_shared_final_output_kernel(
    const uint16_t *route_outputs,
    const float *topk_weights,
    const uint16_t *shared_down_output,
    const float *shared_gate_scale,
    const float *residual_input,
    float *output,
    size_t output_elements
) {
    const size_t row =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (row >= output_elements) {
        return;
    }
    float routed = 0.0f;
    for (unsigned int route_order = 0u;
         route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route_order) {
        routed = device_mul_add_separate(
            routed,
            topk_weights[route_order],
            device_bf16_to_float(
                route_outputs[
                    static_cast<size_t>(route_order) *
                        QRT_QWEN36_HIDDEN_SIZE + row
                ]
            )
        );
    }
    float combined;
    float final_output;
    asm("v_fma_f32 %0, %1, %2, %3"
        : "=v"(combined)
        : "v"(shared_gate_scale[0]),
          "v"(device_bf16_to_float(shared_down_output[row])),
          "v"(routed));
    asm("v_add_f32 %0, %1, %2"
        : "=v"(final_output)
        : "v"(residual_input[row]), "v"(combined));
    output[row] = final_output;
}
#endif

// Keep the routed expert's proven one-row wave geometry while replacing the
// four batch-one shared-expert GEMVs with a raw BF16 pair.  The first row also
// owns the scalar shared gate, rounds it to the retained BF16 endpoint, and
// publishes the scale consumed by the following down/output kernel.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_raw_shared_gate_up_activation_wave_kernel(
    const uint16_t *gate_scalar_weights,
    const uint16_t *gate_weights,
    const uint16_t *up_weights,
    const uint16_t *input,
    uint16_t *gate_logit_bf16,
    float *gate_scale,
    uint16_t *activated
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    const uint32_t *input_pairs =
        reinterpret_cast<const uint32_t *>(input);
    const uint32_t *gate_scalar_pairs =
        reinterpret_cast<const uint32_t *>(gate_scalar_weights);
    const uint32_t *gate_pairs = reinterpret_cast<const uint32_t *>(
        gate_weights +
        static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    const uint32_t *up_pairs = reinterpret_cast<const uint32_t *>(
        up_weights +
        static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    constexpr unsigned int kPairCount = QRT_QWEN36_HIDDEN_SIZE / 2u;
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
    float gate_logit_sum = 0.0f;
    for (unsigned int pair = lane;
         pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        const uint32_t input_pair = input_pairs[pair];
        gate_sum = device_dot2_f32_bf16(
            input_pair,
            gate_pairs[pair],
            gate_sum
        );
        up_sum = device_dot2_f32_bf16(
            input_pair,
            up_pairs[pair],
            up_sum
        );
        if (row == 0u) {
            gate_logit_sum = device_dot2_f32_bf16(
                input_pair,
                gate_scalar_pairs[pair],
                gate_logit_sum
            );
        }
    }
    gate_sum = q1_moe_raw_wave_tree_sum(gate_sum);
    up_sum = q1_moe_raw_wave_tree_sum(up_sum);
    if (row == 0u) {
        gate_logit_sum = q1_moe_raw_wave_tree_sum(gate_logit_sum);
    }

    if (lane == 0u) {
        const uint16_t gate_bf16 = device_float_to_bf16(gate_sum);
        const uint16_t up_bf16 = device_float_to_bf16(up_sum);
        activated[row] = device_float_to_bf16(
            device_silu_f32(device_bf16_to_float(gate_bf16)) *
            device_bf16_to_float(up_bf16)
        );
        if (row == 0u) {
            const uint16_t scalar_bf16 =
                device_float_to_bf16(gate_logit_sum);
            gate_logit_bf16[0] = scalar_bf16;
            gate_scale[0] = 1.0f /
                (1.0f + expf(-device_bf16_to_float(scalar_bf16)));
        }
    }
}

// The shared down projection retains one wave32 reduction per hidden row,
// rounds the projection to BF16, and then applies the same fused gate/routed
// FMA followed by the separate residual add as the retained pointwise tail.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_raw_shared_down_output_wave_kernel(
    const uint16_t *down_weights,
    const uint16_t *activated,
    const float *gate_scale,
    const float *routed_input,
    const float *residual_input,
    float *output
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    const uint32_t *input_pairs =
        reinterpret_cast<const uint32_t *>(activated);
    const uint32_t *weight_pairs = reinterpret_cast<const uint32_t *>(
        down_weights +
        static_cast<size_t>(row) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    constexpr unsigned int kPairCount =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / 2u;
    float sum = 0.0f;
    for (unsigned int pair = lane;
         pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        sum = device_dot2_f32_bf16(
            input_pairs[pair],
            weight_pairs[pair],
            sum
        );
    }
    sum = q1_moe_raw_wave_tree_sum(sum);
    if (lane == 0u) {
        const float down_endpoint = device_bf16_round_to_float(sum);
        float combined;
        float final_output;
        asm("v_fma_f32 %0, %1, %2, %3"
            : "=v"(combined)
            : "v"(gate_scale[0]),
              "v"(down_endpoint),
              "v"(routed_input[row]));
        asm("v_add_f32 %0, %1, %2"
            : "=v"(final_output)
            : "v"(residual_input[row]), "v"(combined));
        output[row] = final_output;
    }
}

// Reuse the routed provider's already-quantized post-attention input while
// replacing the two large shared gate/up BF16 reductions with group-128 W8
// dot4.  The scalar shared gate remains a BF16 dot2 reduction and every
// published projection endpoint retains the established BF16 rounding.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_w8a8_shared_gate_up_activation_kernel(
    const uint16_t *gate_scalar_weights,
    const int8_t *gate_weights,
    const float *gate_weight_scales,
    const int8_t *up_weights,
    const float *up_weight_scales,
    const uint16_t *input_bf16,
    const int8_t *input,
    const float *input_scale,
    float *gate_scale,
    uint16_t *activated
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
    if (row >= QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) {
        return;
    }
    constexpr unsigned int kGroupCount =
        QRT_QWEN36_HIDDEN_SIZE / kQ1MoeW8A8GroupSize;
    constexpr unsigned int kPackedWordsPerGroup =
        kQ1MoeW8A8GroupSize / 4u;
    constexpr unsigned int kPackedK = QRT_QWEN36_HIDDEN_SIZE / 4u;
    const char4 *input_words = reinterpret_cast<const char4 *>(input);
    const char4 *gate_words = reinterpret_cast<const char4 *>(
        gate_weights + static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    const char4 *up_words = reinterpret_cast<const char4 *>(
        up_weights + static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
    );
    const float *gate_scales = gate_weight_scales +
        static_cast<size_t>(row) * kGroupCount;
    const float *up_scales = up_weight_scales +
        static_cast<size_t>(row) * kGroupCount;
    const float activation_scale = input_scale[0];
    float gate_sum = 0.0f;
    float up_sum = 0.0f;
#pragma unroll
    for (unsigned int packed = lane;
         packed < kPackedK;
         packed += kQ1MoeRawWaveSize) {
        const unsigned int group = packed / kPackedWordsPerGroup;
        const char4 input_value = input_words[packed];
        gate_sum += static_cast<float>(amd_mixed_dot(
            input_value,
            gate_words[packed],
            0,
            false
        )) * gate_scales[group] * activation_scale;
        up_sum += static_cast<float>(amd_mixed_dot(
            input_value,
            up_words[packed],
            0,
            false
        )) * up_scales[group] * activation_scale;
    }
    gate_sum = q1_moe_raw_wave_tree_sum(gate_sum);
    up_sum = q1_moe_raw_wave_tree_sum(up_sum);

    float gate_logit_sum = 0.0f;
    if (row == 0u) {
        const uint32_t *input_pairs =
            reinterpret_cast<const uint32_t *>(input_bf16);
        const uint32_t *gate_scalar_pairs =
            reinterpret_cast<const uint32_t *>(gate_scalar_weights);
        constexpr unsigned int kPairCount =
            QRT_QWEN36_HIDDEN_SIZE / 2u;
        for (unsigned int pair = lane;
             pair < kPairCount;
             pair += kQ1MoeRawWaveSize) {
            gate_logit_sum = device_dot2_f32_bf16(
                input_pairs[pair],
                gate_scalar_pairs[pair],
                gate_logit_sum
            );
        }
        gate_logit_sum = q1_moe_raw_wave_tree_sum(gate_logit_sum);
    }
    if (lane == 0u) {
        const uint16_t gate_bf16 = device_float_to_bf16(gate_sum);
        const uint16_t up_bf16 = device_float_to_bf16(up_sum);
        activated[row] = device_float_to_bf16(
            device_silu_f32(device_bf16_to_float(gate_bf16)) *
            device_bf16_to_float(up_bf16)
        );
        if (row == 0u) {
            const uint16_t scalar_bf16 =
                device_float_to_bf16(gate_logit_sum);
            gate_scale[0] = 1.0f /
                (1.0f + expf(-device_bf16_to_float(scalar_bf16)));
        }
    }
}

// The shared W8 down endpoint is rounded to BF16 before the retained shared
