    );
    const float *weight_scales = down_weight_scales +
        static_cast<size_t>(row) * kGroupCount;
    float sum = 0.0f;
#pragma unroll
    for (unsigned int packed = lane;
         packed < kPackedK;
         packed += kQ1MoeRawWaveSize) {
