// Four adjacent output rows share each input-pair load while retaining four
// independent dot2 recurrences and the exact wave32 shuffle tree.  Gate/up
// endpoint arrays are deliberately omitted: only their BF16-rounded values
// feed the retained SiLU*up BF16 activation endpoint.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_raw_gate_up_activation_multirow_wave_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *input,
    const uint32_t *device_topk_ids,
    uint16_t *activated
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kBlocksPerRoute =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / kQ1MoeRawRowsPerBlock;
    const unsigned int route = blockIdx.x / kBlocksPerRoute;
    const unsigned int route_block = blockIdx.x - route * kBlocksPerRoute;
    const unsigned int row_base =
        route_block * kQ1MoeRawRowsPerBlock +
        wave * kQ1MoeRawRowsPerWave;
    const unsigned int expert = device_topk_ids[route];
    constexpr size_t kGateElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint32_t *input_pairs =
        reinterpret_cast<const uint32_t *>(input);
    const uint32_t *gate_pairs[kQ1MoeRawRowsPerWave];
    const uint32_t *up_pairs[kQ1MoeRawRowsPerWave];
    #pragma unroll
    for (unsigned int local_row = 0u;
         local_row < kQ1MoeRawRowsPerWave;
         ++local_row) {
        const unsigned int row = row_base + local_row;
        gate_pairs[local_row] = reinterpret_cast<const uint32_t *>(
            all_gate_up_weights + expert_base +
            static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
        );
        up_pairs[local_row] = reinterpret_cast<const uint32_t *>(
            all_gate_up_weights + expert_base + kGateElements +
            static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
        );
    }

    constexpr unsigned int kPairCount = QRT_QWEN36_HIDDEN_SIZE / 2u;
    float gate_sums[kQ1MoeRawRowsPerWave] = {};
    float up_sums[kQ1MoeRawRowsPerWave] = {};
    for (unsigned int pair = lane; pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        const uint32_t input_pair = input_pairs[pair];
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            gate_sums[local_row] = device_dot2_f32_bf16(
                input_pair,
                gate_pairs[local_row][pair],
                gate_sums[local_row]
            );
            up_sums[local_row] = device_dot2_f32_bf16(
                input_pair,
                up_pairs[local_row][pair],
                up_sums[local_row]
            );
        }
    }
    #pragma unroll
    for (unsigned int local_row = 0u;
         local_row < kQ1MoeRawRowsPerWave;
         ++local_row) {
        gate_sums[local_row] = q1_moe_raw_wave_tree_sum(
            gate_sums[local_row]
        );
        up_sums[local_row] = q1_moe_raw_wave_tree_sum(up_sums[local_row]);
    }

    if (lane == 0u) {
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            const uint16_t gate_bf16 =
                device_float_to_bf16(gate_sums[local_row]);
            const uint16_t up_bf16 =
                device_float_to_bf16(up_sums[local_row]);
            activated[
                static_cast<size_t>(route) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE +
                row_base + local_row
            ] = device_float_to_bf16(
                device_silu_f32(device_bf16_to_float(gate_bf16)) *
                device_bf16_to_float(up_bf16)
            );
        }
    }
}

// Extend the retained q1 raw-BF16 arithmetic to an M16 carrier without
// changing its wave32 dot2 reduction order.  Grid Y owns the token while grid
// X keeps the existing route/row tiling, so every expert weight row is reused
// by the memory system across the sixteen independent target rows.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q16_moe_raw_gate_up_activation_multirow_wave_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *inputs,
    const uint32_t *device_topk_ids,
    uint16_t *activated,
    unsigned int token_count
) {
    const unsigned int token = blockIdx.y;
    if (token >= token_count) {
        return;
    }
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kBlocksPerRoute =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / kQ1MoeRawRowsPerBlock;
    const unsigned int route = blockIdx.x / kBlocksPerRoute;
    const unsigned int route_block = blockIdx.x - route * kBlocksPerRoute;
    const unsigned int row_base =
        route_block * kQ1MoeRawRowsPerBlock +
        wave * kQ1MoeRawRowsPerWave;
    const size_t token_route_base =
        static_cast<size_t>(token) * QRT_QWEN36_EXPERTS_PER_TOKEN;
    const unsigned int expert = device_topk_ids[token_route_base + route];
    constexpr size_t kGateElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(
        inputs + static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE
    );
    const uint32_t *gate_pairs[kQ1MoeRawRowsPerWave];
    const uint32_t *up_pairs[kQ1MoeRawRowsPerWave];
    #pragma unroll
    for (unsigned int local_row = 0u;
         local_row < kQ1MoeRawRowsPerWave;
         ++local_row) {
        const unsigned int row = row_base + local_row;
        gate_pairs[local_row] = reinterpret_cast<const uint32_t *>(
            all_gate_up_weights + expert_base +
            static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
        );
        up_pairs[local_row] = reinterpret_cast<const uint32_t *>(
            all_gate_up_weights + expert_base + kGateElements +
            static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
        );
    }

    constexpr unsigned int kPairCount = QRT_QWEN36_HIDDEN_SIZE / 2u;
    float gate_sums[kQ1MoeRawRowsPerWave] = {};
    float up_sums[kQ1MoeRawRowsPerWave] = {};
    for (unsigned int pair = lane; pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        const uint32_t input_pair = input_pairs[pair];
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            gate_sums[local_row] = device_dot2_f32_bf16(
                input_pair,
                gate_pairs[local_row][pair],
                gate_sums[local_row]
            );
            up_sums[local_row] = device_dot2_f32_bf16(
                input_pair,
                up_pairs[local_row][pair],
                up_sums[local_row]
            );
        }
    }
    #pragma unroll
    for (unsigned int local_row = 0u;
         local_row < kQ1MoeRawRowsPerWave;
         ++local_row) {
        gate_sums[local_row] = q1_moe_raw_wave_tree_sum(
            gate_sums[local_row]
        );
        up_sums[local_row] = q1_moe_raw_wave_tree_sum(up_sums[local_row]);
    }

    if (lane == 0u) {
        const size_t activation_base =
            (token_route_base + route) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            const uint16_t gate_bf16 =
                device_float_to_bf16(gate_sums[local_row]);
            const uint16_t up_bf16 =
                device_float_to_bf16(up_sums[local_row]);
            activated[activation_base + row_base + local_row] =
                device_float_to_bf16(
                    device_silu_f32(device_bf16_to_float(gate_bf16)) *
                    device_bf16_to_float(up_bf16)
                );
        }
    }
}

// Each wave owns four hidden rows and walks routes in the retained 0..7
// router order.  Every per-route dot keeps its own BF16 down endpoint before
// the explicit v_mul/v_add route accumulation, so no materialized 8xhidden
// route-output surface or follow-up combine launch is needed.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_moe_raw_down_combine_multirow_wave_kernel(
    const uint16_t *all_down_weights,
    const uint16_t *activated,
    const uint32_t *device_topk_ids,
    const float *device_topk_weights,
    float *routed_output
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row_base =
        blockIdx.x * kQ1MoeRawRowsPerBlock +
        wave * kQ1MoeRawRowsPerWave;
    constexpr unsigned int kPairCount =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / 2u;
    float combined[kQ1MoeRawRowsPerWave] = {};

    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const unsigned int expert = device_topk_ids[route];
        const size_t expert_base = static_cast<size_t>(expert) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
        const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(
            activated + static_cast<size_t>(route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
        );
        const uint32_t *weight_pairs[kQ1MoeRawRowsPerWave];
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            weight_pairs[local_row] = reinterpret_cast<const uint32_t *>(
                all_down_weights + expert_base +
                static_cast<size_t>(row_base + local_row) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
            );
        }
        float sums[kQ1MoeRawRowsPerWave] = {};
        for (unsigned int pair = lane; pair < kPairCount;
             pair += kQ1MoeRawWaveSize) {
            const uint32_t input_pair = input_pairs[pair];
            #pragma unroll
            for (unsigned int local_row = 0u;
                 local_row < kQ1MoeRawRowsPerWave;
                 ++local_row) {
                sums[local_row] = device_dot2_f32_bf16(
                    input_pair,
                    weight_pairs[local_row][pair],
                    sums[local_row]
                );
            }
        }
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            sums[local_row] = q1_moe_raw_wave_tree_sum(sums[local_row]);
        }
        if (lane == 0u) {
            #pragma unroll
            for (unsigned int local_row = 0u;
                 local_row < kQ1MoeRawRowsPerWave;
                 ++local_row) {
                const float endpoint = device_bf16_round_to_float(
                    sums[local_row]
                );
                combined[local_row] = device_mul_add_separate(
                    combined[local_row],
                    device_topk_weights[route],
                    endpoint
                );
            }
        }
    }

    if (lane == 0u) {
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            routed_output[row_base + local_row] = combined[local_row];
        }
    }
}

__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q16_moe_raw_down_combine_multirow_wave_kernel(
    const uint16_t *all_down_weights,
    const uint16_t *activated,
    const uint32_t *device_topk_ids,
    const float *device_topk_weights,
    float *routed_output,
    unsigned int token_count
) {
    const unsigned int token = blockIdx.y;
    if (token >= token_count) {
        return;
    }
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row_base =
        blockIdx.x * kQ1MoeRawRowsPerBlock +
        wave * kQ1MoeRawRowsPerWave;
    const size_t token_route_base =
        static_cast<size_t>(token) * QRT_QWEN36_EXPERTS_PER_TOKEN;
    constexpr unsigned int kPairCount =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / 2u;
    float combined[kQ1MoeRawRowsPerWave] = {};

    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const unsigned int expert =
            device_topk_ids[token_route_base + route];
        const size_t expert_base = static_cast<size_t>(expert) *
            QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
        const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(
            activated + (token_route_base + route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
        );
        const uint32_t *weight_pairs[kQ1MoeRawRowsPerWave];
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            weight_pairs[local_row] = reinterpret_cast<const uint32_t *>(
                all_down_weights + expert_base +
                static_cast<size_t>(row_base + local_row) *
                    QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
            );
        }
        float sums[kQ1MoeRawRowsPerWave] = {};
        for (unsigned int pair = lane; pair < kPairCount;
             pair += kQ1MoeRawWaveSize) {
            const uint32_t input_pair = input_pairs[pair];
            #pragma unroll
            for (unsigned int local_row = 0u;
                 local_row < kQ1MoeRawRowsPerWave;
                 ++local_row) {
                sums[local_row] = device_dot2_f32_bf16(
                    input_pair,
                    weight_pairs[local_row][pair],
                    sums[local_row]
                );
            }
        }
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            sums[local_row] = q1_moe_raw_wave_tree_sum(sums[local_row]);
        }
        if (lane == 0u) {
            #pragma unroll
            for (unsigned int local_row = 0u;
                 local_row < kQ1MoeRawRowsPerWave;
                 ++local_row) {
                combined[local_row] = device_mul_add_separate(
                    combined[local_row],
                    device_topk_weights[token_route_base + route],
                    device_bf16_round_to_float(sums[local_row])
                );
            }
        }
    }

    if (lane == 0u) {
        const size_t output_base =
            static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ1MoeRawRowsPerWave;
             ++local_row) {
            routed_output[output_base + row_base + local_row] =
                combined[local_row];
        }
    }
}

// Up to M16 has at most 128 token-routes but substantially fewer unique
// experts.  The token-major kernels above rely on cache luck to reuse an expert
// row across tokens.  These grouped kernels designate the first route for each
// expert as a leader, then let eight waves in one block evaluate all matching
// routes for the same row tile.  Every route retains the established wave32
// dot2 tree; the separate endpoint-combine kernel restores the original
// per-token 0..7 weighted-add order exactly.
constexpr unsigned int kQ16MoeGroupedWaves = 8u;
constexpr unsigned int kQ16MoeGroupedThreads =
    kQ16MoeGroupedWaves * kQ1MoeRawWaveSize;
constexpr unsigned int kQ16MoeGroupedRowsPerWave = 8u;

__device__ bool q16_moe_route_is_expert_leader(
    const uint32_t *topk_ids,
    unsigned int flat_route,
    unsigned int expert
) {
    for (unsigned int previous = 0u; previous < flat_route; ++previous) {
        if (topk_ids[previous] == expert) {
            return false;
        }
    }
    return true;
}

__global__ __launch_bounds__(kQ16MoeGroupedThreads)
void q16_moe_grouped_gate_up_activation_wave_kernel(
    const uint16_t *all_gate_up_weights,
    const uint16_t *inputs,
    const uint32_t *device_topk_ids,
    uint16_t *activated,
    unsigned int token_count
) {
    const unsigned int flat_route_leader = blockIdx.x;
    const unsigned int route_count =
        token_count * QRT_QWEN36_EXPERTS_PER_TOKEN;
    if (flat_route_leader >= route_count ||
        token_count == 0u || token_count > 16u) {
        return;
    }
    const unsigned int expert = device_topk_ids[flat_route_leader];
    if (!q16_moe_route_is_expert_leader(
            device_topk_ids,
            flat_route_leader,
            expert
        )) {
        return;
    }
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row_base =
        blockIdx.y * kQ16MoeGroupedRowsPerWave;
    constexpr size_t kGateElements =
        static_cast<size_t>(QRT_QWEN36_MOE_EXPERT_INTERMEDIATE) *
        QRT_QWEN36_HIDDEN_SIZE;
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_GATE_UP_ELEMENTS_PER_EXPERT;
    const uint32_t *gate_pairs[kQ16MoeGroupedRowsPerWave];
    const uint32_t *up_pairs[kQ16MoeGroupedRowsPerWave];
    #pragma unroll
    for (unsigned int local_row = 0u;
         local_row < kQ16MoeGroupedRowsPerWave;
         ++local_row) {
        const unsigned int row = row_base + local_row;
        gate_pairs[local_row] = reinterpret_cast<const uint32_t *>(
            all_gate_up_weights + expert_base +
            static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
        );
        up_pairs[local_row] = reinterpret_cast<const uint32_t *>(
            all_gate_up_weights + expert_base + kGateElements +
            static_cast<size_t>(row) * QRT_QWEN36_HIDDEN_SIZE
        );
    }
    constexpr unsigned int kPairCount = QRT_QWEN36_HIDDEN_SIZE / 2u;
    unsigned int expert_occurrence = 0u;
    for (unsigned int flat_route = 0u; flat_route < route_count;
         ++flat_route) {
        if (device_topk_ids[flat_route] != expert) {
            continue;
        }
        const bool owned =
            expert_occurrence % kQ16MoeGroupedWaves == wave;
        ++expert_occurrence;
        if (!owned) {
            continue;
        }
        const unsigned int token =
            flat_route / QRT_QWEN36_EXPERTS_PER_TOKEN;
        const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(
            inputs + static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE
        );
        float gate_sums[kQ16MoeGroupedRowsPerWave] = {};
        float up_sums[kQ16MoeGroupedRowsPerWave] = {};
        for (unsigned int pair = lane; pair < kPairCount;
             pair += kQ1MoeRawWaveSize) {
            const uint32_t input_pair = input_pairs[pair];
            #pragma unroll
            for (unsigned int local_row = 0u;
                 local_row < kQ16MoeGroupedRowsPerWave;
                 ++local_row) {
                gate_sums[local_row] = device_dot2_f32_bf16(
                    input_pair,
                    gate_pairs[local_row][pair],
                    gate_sums[local_row]
                );
                up_sums[local_row] = device_dot2_f32_bf16(
                    input_pair,
                    up_pairs[local_row][pair],
                    up_sums[local_row]
                );
            }
        }
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kQ16MoeGroupedRowsPerWave;
             ++local_row) {
            gate_sums[local_row] = q1_moe_raw_wave_tree_sum(
                gate_sums[local_row]
            );
            up_sums[local_row] = q1_moe_raw_wave_tree_sum(
                up_sums[local_row]
            );
        }
        if (lane == 0u) {
            const size_t activation_base =
                static_cast<size_t>(flat_route) *
                QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
            #pragma unroll
            for (unsigned int local_row = 0u;
                 local_row < kQ16MoeGroupedRowsPerWave;
                 ++local_row) {
                const uint16_t gate_bf16 =
                    device_float_to_bf16(gate_sums[local_row]);
                const uint16_t up_bf16 =
                    device_float_to_bf16(up_sums[local_row]);
                activated[activation_base + row_base + local_row] =
                    device_float_to_bf16(
                        device_silu_f32(
                            device_bf16_to_float(gate_bf16)
                        ) * device_bf16_to_float(up_bf16)
                    );
            }
        }
    }
}

