__global__ void q16_moe_grouped_endpoint_combine_kernel(
    const uint16_t *route_endpoints,
    const float *topk_weights,
    float *routed_output,
    unsigned int token_count
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const size_t total =
        static_cast<size_t>(token_count) * QRT_QWEN36_HIDDEN_SIZE;
    if (index >= total || token_count == 0u || token_count > 16u) {
        return;
    }
    const size_t token = index / QRT_QWEN36_HIDDEN_SIZE;
    const size_t row = index - token * QRT_QWEN36_HIDDEN_SIZE;
    const size_t route_base =
        token * QRT_QWEN36_EXPERTS_PER_TOKEN;
    float combined = 0.0f;
    #pragma unroll
    for (unsigned int route = 0u;
         route < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route) {
        const size_t flat_route = route_base + route;
        combined = device_mul_add_separate(
            combined,
            topk_weights[flat_route],
            device_bf16_to_float(
                route_endpoints[
                    flat_route * QRT_QWEN36_HIDDEN_SIZE + row
                ]
            )
        );
    }
    routed_output[index] = combined;
}

// Preserve all independent route-row reductions while removing the global
// 8xhidden endpoint surface and follow-up combine launch.  Four rows share a
// block, but each of their eight routes owns one wave32; only the 64-byte BF16
// endpoint tile is shared before the retained route-order v_mul/v_add combine.
__global__ __launch_bounds__(kQ1MoeRawRouteParallelBlockThreads)
void q1_moe_raw_down_combine_route_parallel_wave_kernel(
    const uint16_t *all_down_weights,
    const uint16_t *activated,
    const uint32_t *device_topk_ids,
    const float *device_topk_weights,
    float *routed_output
) {
    __shared__ uint16_t endpoints[
        kQ1MoeRawRouteParallelRowsPerBlock
    ][QRT_QWEN36_EXPERTS_PER_TOKEN];

    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int local_row = wave / QRT_QWEN36_EXPERTS_PER_TOKEN;
    const unsigned int route =
        wave - local_row * QRT_QWEN36_EXPERTS_PER_TOKEN;
    const unsigned int row =
        blockIdx.x * kQ1MoeRawRouteParallelRowsPerBlock + local_row;
    const unsigned int expert = device_topk_ids[route];
    const size_t expert_base = static_cast<size_t>(expert) *
        QRT_QWEN36_LAYER0_MOE_EXPERT_DOWN_ELEMENTS_PER_EXPERT;
    const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(
        activated + static_cast<size_t>(route) *
            QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    const uint32_t *weight_pairs = reinterpret_cast<const uint32_t *>(
        all_down_weights + expert_base +
        static_cast<size_t>(row) * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE
    );
    constexpr unsigned int kPairCount =
        QRT_QWEN36_MOE_EXPERT_INTERMEDIATE / 2u;
    float sum = 0.0f;
    for (unsigned int pair = lane; pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        sum = device_dot2_f32_bf16(
            input_pairs[pair],
            weight_pairs[pair],
            sum
        );
    }
    sum = q1_moe_raw_wave_tree_sum(sum);
    if (lane == 0u) {
        endpoints[local_row][route] = device_float_to_bf16(sum);
    }
    __syncthreads();

    if (threadIdx.x < kQ1MoeRawRouteParallelRowsPerBlock) {
        const unsigned int combine_row = threadIdx.x;
        float combined = 0.0f;
        #pragma unroll
        for (unsigned int route_order = 0u;
             route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
             ++route_order) {
            combined = device_mul_add_separate(
                combined,
                device_topk_weights[route_order],
                device_bf16_to_float(endpoints[combine_row][route_order])
            );
        }
        routed_output[
            static_cast<size_t>(blockIdx.x) *
                kQ1MoeRawRouteParallelRowsPerBlock + combine_row
        ] = combined;
    }
}

// Batch-one QKVZ is a memory-bound row-major GEMV.  Each wave32 owns four rows
// so one input-pair load feeds four independent dot2 recurrences.  Lane zero
// rounds each result through the established BF16 endpoint and writes the F32
// QKV/Z corridor surfaces directly, eliminating both temporary BF16 unpack
// launches without introducing a host surface.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_linear_raw_bf16_wave_qkvz_kernel(
    const uint16_t *weights,
    const uint16_t *input,
    float *qkv_output,
    float *z_output
) {
    constexpr unsigned int kRowsPerWave = 4u;
    constexpr unsigned int kRowsPerBlock =
        kQ1MoeRawWavesPerBlock * kRowsPerWave;
    constexpr unsigned int kInputFeatures = QRT_QWEN36_HIDDEN_SIZE;
    constexpr unsigned int kOutputRows = kQkvRows + kZRows;
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row_base =
        blockIdx.x * kRowsPerBlock + wave * kRowsPerWave;

    const uint32_t *input_pairs =
        reinterpret_cast<const uint32_t *>(input);
    constexpr unsigned int kPairCount = kInputFeatures / 2u;
    float sums[kRowsPerWave] = {};
    for (unsigned int pair = lane;
         pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        const uint32_t input_pair = input_pairs[pair];
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kRowsPerWave;
             ++local_row) {
            const unsigned int row = row_base + local_row;
            if (row < kOutputRows) {
                const uint32_t *weight_pairs =
                    reinterpret_cast<const uint32_t *>(
                        weights + static_cast<size_t>(row) * kInputFeatures
                    );
                sums[local_row] = device_dot2_f32_bf16(
                    input_pair,
                    weight_pairs[pair],
                    sums[local_row]
                );
            }
        }
    }
    #pragma unroll
    for (unsigned int local_row = 0u;
         local_row < kRowsPerWave;
         ++local_row) {
        sums[local_row] = q1_moe_raw_wave_tree_sum(sums[local_row]);
    }
    if (lane == 0u) {
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kRowsPerWave;
             ++local_row) {
            const unsigned int row = row_base + local_row;
            if (row < kQkvRows) {
                qkv_output[row] = device_bf16_round_to_float(
                    sums[local_row]
                );
            } else if (row < kOutputRows) {
                z_output[row - kQkvRows] = device_bf16_round_to_float(
                    sums[local_row]
                );
            }
        }
    }
}

// The 0626 reference keeps decode input projection on a q1-specialized BF16
// path.  For gfx1151, a bounded grid with one output row per wave sustains
// more cold-weight bandwidth than rocBLAS on the exact combined
// QKVZ+A/B (12352 x 2048) shape.  Every lane consumes the same ascending
// BF16x8 vector sequence used by the standalone screen, lane zero publishes
// the established BF16 endpoint, and the existing unpack/conv consumers stay
// unchanged.  This is ordinary one-token BF16 decode: no quantization,
// speculation, MTP, or DFlash participates.
constexpr unsigned int kQ1LinearPersistentQkvzAbBlocks = 32u;
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_linear_persistent_bf16_qkvz_ab_kernel(
    const uint16_t *weights,
    const uint16_t *input,
    uint16_t *output
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kVectors = QRT_QWEN36_HIDDEN_SIZE / 8u;
    static_assert(QRT_QWEN36_HIDDEN_SIZE % 8u == 0u);
    const Q1MoePersistentDirectVector *input_vectors =
        reinterpret_cast<const Q1MoePersistentDirectVector *>(input);

    for (unsigned int row =
             blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
         row < kQ1LinearRocblasQkvzAbRows;
         row += gridDim.x * kQ1MoeRawWavesPerBlock) {
        const Q1MoePersistentDirectVector *weight_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                weights + static_cast<size_t>(row) *
                    QRT_QWEN36_HIDDEN_SIZE
            );
        float sum = 0.0f;
#pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            sum = q1_moe_persistent_direct_dot8(
                input_vectors[vector],
                q1_moe_persistent_direct_load_weight(
                    weight_vectors + vector
                ),
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
        if (lane == 0u) {
            output[row] = device_float_to_bf16(sum);
        }
    }
}

// D25 keeps the exact D22 dot2/tree arithmetic and BF16 publication boundary,
// but publishes the rounded values directly into the F32 corridor surfaces.
// D30 optionally consumes each rounded QKV row in the same owner to update the
// BF16 decode ring and four-tap convolution, while Z/A/B retain their direct
// F32 endpoints.  Both remain ordinary BF16 batch-one decode: weights/input
// are BF16, accumulation is FP32, and every visible value crosses the same RNE
// BF16 boundary.  Quantization, MTP, and DFlash are not involved.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_linear_persistent_bf16_qkvz_ab_direct_f32_kernel(
    const uint16_t *weights,
    const uint16_t *input,
    float *qkv_output,
    float *aux_output,
    uint16_t *qkv_ring,
    const uint16_t *conv_weights,
    float *conv_output,
    size_t absolute_position
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kVectors = QRT_QWEN36_HIDDEN_SIZE / 8u;
    static_assert(QRT_QWEN36_HIDDEN_SIZE % 8u == 0u);
    const Q1MoePersistentDirectVector *input_vectors =
        reinterpret_cast<const Q1MoePersistentDirectVector *>(input);

    for (unsigned int row =
             blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
         row < kQ1LinearRocblasQkvzAbRows;
         row += gridDim.x * kQ1MoeRawWavesPerBlock) {
        const Q1MoePersistentDirectVector *weight_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                weights + static_cast<size_t>(row) *
                    QRT_QWEN36_HIDDEN_SIZE
            );
        float sum = 0.0f;
#pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            sum = q1_moe_persistent_direct_dot8(
                input_vectors[vector],
                q1_moe_persistent_direct_load_weight(
                    weight_vectors + vector
                ),
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
        if (lane == 0u) {
            const float rounded = device_bf16_round_to_float(sum);
            if (row < kQkvRows) {
                if (qkv_ring != nullptr && conv_weights != nullptr &&
                    conv_output != nullptr) {
                    // D30 folds the current-token BF16 endpoint into the
                    // existing four-tap decode convolution and writes the
                    // same BF16 ring slot in one owner.  The tap order,
                    // endpoint rounding, weight conversion, accumulation,
                    // SiLU boundary, and ring layout are byte-for-byte the
                    // same operations as
                    // qwen36_resident_linear_conv_cache_kernel<uint16_t>.
                    float acc = 0.0f;
                    for (unsigned int tap = 0u; tap < kConvKernel; ++tap) {
                        if (absolute_position + tap >=
                            static_cast<size_t>(kConvKernel - 1u)) {
                            const size_t source_token =
                                absolute_position + tap -
                                static_cast<size_t>(kConvKernel - 1u);
                            float qkv_value = rounded;
                            if (source_token != absolute_position) {
                                const size_t source_slot = source_token %
                                    static_cast<size_t>(kConvKernel);
                                qkv_value = qwen36_resident_cache_value(
                                    qkv_ring[
                                        source_slot *
                                            static_cast<size_t>(kQkvRows) +
                                        row
                                    ]
                                );
                            }
                            qkv_value =
                                device_bf16_round_to_float(qkv_value);
                            const float weight = device_bf16_to_float(
                                conv_weights[row * kConvKernel + tap]
                            );
                            acc += qkv_value * weight;
                        }
                    }
                    conv_output[row] = device_silu_bf16_from_f32_acc(
                        device_bf16_round_to_float(acc)
                    );
                    const size_t destination_slot = absolute_position %
                        static_cast<size_t>(kConvKernel);
                    qwen36_resident_cache_store(
                        qkv_ring,
                        destination_slot *
                                static_cast<size_t>(kQkvRows) +
                            row,
                        rounded
                    );
                } else if (qkv_output != nullptr) {
                    qkv_output[row] = rounded;
                }
            } else {
                aux_output[row - kQkvRows] = rounded;
            }
        }
    }
}

// Full-attention Q is ten independent 8192x2048 batch-one BF16 GEMVs.  The
// exact D26 screen selects the same 32-block, eight-wave schedule as D22's
// cold projection family.  Accumulation and the published BF16 endpoint stay
// identical to the retained provider; this only replaces the rocBLAS Q call.
constexpr unsigned int kQ1FullAttentionPersistentQBlocks = 32u;
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_full_attention_persistent_bf16_q_kernel(
    const uint16_t *weights,
    const uint16_t *input,
    uint16_t *output
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kVectors = QRT_QWEN36_HIDDEN_SIZE / 8u;
    static_assert(QRT_QWEN36_HIDDEN_SIZE % 8u == 0u);
    const Q1MoePersistentDirectVector *input_vectors =
        reinterpret_cast<const Q1MoePersistentDirectVector *>(input);

    for (unsigned int row =
             blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
         row < kLayer3FullAttentionQRows;
         row += gridDim.x * kQ1MoeRawWavesPerBlock) {
        const Q1MoePersistentDirectVector *weight_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                weights + static_cast<size_t>(row) *
                    QRT_QWEN36_HIDDEN_SIZE
            );
        float sum = 0.0f;
#pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            sum = q1_moe_persistent_direct_dot8(
                input_vectors[vector],
                q1_moe_persistent_direct_load_weight(
                    weight_vectors + vector
                ),
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
        if (lane == 0u) {
            output[row] = device_float_to_bf16(sum);
        }
    }
}

// The q1 linear-attention output projection has the transposed shape
// 2048 x 4096 on all thirty linear-attention layers.  The connected product
// profile shows materially more wall time than the contiguous cold-arena
// screen, so keep this as an independently switchable provider and let the
// long decode gate decide whether the product layout realizes the bandwidth
// gain.  As above, weights and activations remain BF16, accumulation remains
// FP32 dot2/tree order, and the published endpoint is BF16.
constexpr unsigned int kQ1LinearPersistentOutBlocks = 28u;
constexpr unsigned int kQ1Triton0626OutputMatvecGridPrograms =
    kOutProjectionRows;
constexpr unsigned int kQ1Triton0626OutputMatvecThreads = 256u;
constexpr unsigned int kQ1Triton0626OutputMatvecSharedBytes = 32u;
constexpr unsigned int kQ1OutputConsumerFusedGridBlocks =
    kOutProjectionRows;
constexpr unsigned int kQ1OutputConsumerFusedThreads =
    kQ1MoeRawBlockThreads;
constexpr size_t kQ1OutputConsumerFusedSharedBytes =
    static_cast<size_t>(kValueFeatures) * sizeof(uint16_t);
constexpr unsigned int kQ1OutputConsumerFusedRows2RowsPerBlock = 2u;
constexpr unsigned int kQ1OutputConsumerFusedRows2GridBlocks =
    kOutProjectionRows / kQ1OutputConsumerFusedRows2RowsPerBlock;
constexpr size_t kQ1OutputConsumerFusedRows2SharedBytes =
    static_cast<size_t>(kQ1OutputConsumerFusedRows2RowsPerBlock) *
    kValueFeatures * sizeof(uint16_t);
static_assert(
    kOutProjectionRows % kQ1OutputConsumerFusedRows2RowsPerBlock == 0u
);
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_linear_persistent_bf16_out_kernel(
    const uint16_t *weights,
    const uint16_t *input,
    uint16_t *output
) {
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    constexpr unsigned int kVectors = kValueFeatures / 8u;
    static_assert(kValueFeatures % 8u == 0u);
    const Q1MoePersistentDirectVector *input_vectors =
        reinterpret_cast<const Q1MoePersistentDirectVector *>(input);

    for (unsigned int row =
             blockIdx.x * kQ1MoeRawWavesPerBlock + wave;
         row < kOutProjectionRows;
         row += gridDim.x * kQ1MoeRawWavesPerBlock) {
        const Q1MoePersistentDirectVector *weight_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(
                weights + static_cast<size_t>(row) * kValueFeatures
            );
        float sum = 0.0f;
#pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            sum = q1_moe_persistent_direct_dot8(
                input_vectors[vector],
                q1_moe_persistent_direct_load_weight(
                    weight_vectors + vector
                ),
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
        if (lane == 0u) {
            output[row] = device_float_to_bf16(sum);
        }
    }
}

// D115b moves the ordinary-layer output projection across its first consumer
// boundary.  One block owns one 2048x4096 output row.  Eight waves prefetch
// that row's 8 KiB BF16 weights into LDS, while wave zero preserves the
// retained D23/D24 dot2 accumulation and wave32 reduction order exactly.
// The last block to publish its BF16 attention endpoint performs the retained
// 256-lane double RMS tree.  This removes one launch and the intermediate
// attention-update materialization without changing model precision.
__global__ __launch_bounds__(kQ1OutputConsumerFusedThreads)
void q1_output_consumer_fused_exact_kernel(
    const uint16_t *weights,
    const uint16_t *input,
    const float *residual_input,
    const uint16_t *norm_weights,
    float *residual_output,
    float *postnorm_output,
    uint16_t *postnorm_output_bf16,
    uint32_t *completion_counter
) {
    extern __shared__ unsigned char shared_bytes[];
    __shared__ uint32_t last_block;
    __shared__ float inv_shared;

    constexpr unsigned int kVectors = kValueFeatures / 8u;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kQ1OutputConsumerFusedThreads;
    static_assert(kValueFeatures % 8u == 0u);
    static_assert(
        QRT_QWEN36_HIDDEN_SIZE % kQ1OutputConsumerFusedThreads == 0u
    );

    const unsigned int row = blockIdx.x;
    const unsigned int thread = threadIdx.x;
    const unsigned int lane =
        thread & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = thread / kQ1MoeRawWaveSize;

    Q1MoePersistentDirectVector *weight_tile =
        reinterpret_cast<Q1MoePersistentDirectVector *>(shared_bytes);
    const Q1MoePersistentDirectVector *weight_vectors =
        reinterpret_cast<const Q1MoePersistentDirectVector *>(
            weights + static_cast<size_t>(row) * kValueFeatures
        );
    for (unsigned int vector = thread;
         vector < kVectors;
         vector += kQ1OutputConsumerFusedThreads) {
        weight_tile[vector] =
            q1_moe_persistent_direct_load_weight(weight_vectors + vector);
    }
    __syncthreads();

    float sum = 0.0f;
    if (wave == 0u) {
        const Q1MoePersistentDirectVector *input_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(input);
        #pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            sum = q1_moe_persistent_direct_dot8(
                input_vectors[vector],
                weight_tile[vector],
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
    }
    if (thread == 0u) {
        const uint16_t attention_endpoint = device_float_to_bf16(sum);
        const float residual =
            residual_input[row] +
            device_bf16_to_float(attention_endpoint);
        residual_output[row] = residual;
        __threadfence();
        const uint32_t ticket = atomicAdd(completion_counter, 1u);
        last_block =
            ticket + 1u == kQ1OutputConsumerFusedGridBlocks ? 1u : 0u;
    }
    __syncthreads();
    if (last_block == 0u) {
        return;
    }

    double *partial = reinterpret_cast<double *>(shared_bytes);
    float values[kValuesPerLane];
    double sumsq = 0.0;
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col =
            thread + item * kQ1OutputConsumerFusedThreads;
        const float value = residual_output[col];
        values[item] = value;
        sumsq +=
            static_cast<double>(value) * static_cast<double>(value);
    }
    partial[thread] = sumsq;
    __syncthreads();

    for (unsigned int stride = kQ1OutputConsumerFusedThreads / 2u;
         stride > 0u;
         stride >>= 1u) {
        if (thread < stride) {
            partial[thread] += partial[thread + stride];
        }
        __syncthreads();
    }
    if (thread == 0u) {
        inv_shared = 1.0f / sqrtf(
            static_cast<float>(
                partial[0] /
                static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
            ) +
            QRT_QWEN36_RMS_NORM_EPSILON
        );
    }
    __syncthreads();

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col =
            thread + item * kQ1OutputConsumerFusedThreads;
        const float normalized =
            values[item] * inv_shared *
            (1.0f + device_bf16_to_float(norm_weights[col]));
        const uint16_t endpoint = device_float_to_bf16(normalized);
        postnorm_output[col] = device_bf16_to_float(endpoint);
        if (postnorm_output_bf16 != nullptr) {
            postnorm_output_bf16[col] = endpoint;
        }
    }
    __syncthreads();
    if (thread == 0u) {
        __threadfence();
        atomicExch(completion_counter, 0u);
    }
}

// D163 product-connects D152's exact two-row coalesced-LDS owner.  All 256
// threads stage two adjacent 8 KiB rows contiguously, and waves zero and one
// independently retain D115b's lane-stride dot8 accumulation and wave32
// reduction tree.  The block publishes both BF16 attention endpoints before
// taking one completion ticket; the final block then reuses the same LDS for
// the unchanged 256-lane double-RMS/postnorm tail.
__global__ __launch_bounds__(kQ1OutputConsumerFusedThreads)
void q1_output_consumer_fused_rows2_exact_kernel(
    const uint16_t *weights,
    const uint16_t *input,
    const float *residual_input,
    const uint16_t *norm_weights,
    float *residual_output,
    float *postnorm_output,
    uint16_t *postnorm_output_bf16,
    uint32_t *completion_counter,
    bool vllm_bf16_residual_norm
) {
    extern __shared__ unsigned char shared_bytes[];

    constexpr unsigned int kRowsPerBlock =
        kQ1OutputConsumerFusedRows2RowsPerBlock;
    constexpr unsigned int kVectors = kValueFeatures / 8u;
    constexpr unsigned int kTileVectors = kRowsPerBlock * kVectors;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kQ1OutputConsumerFusedThreads;
    static_assert(kRowsPerBlock <= kQ1MoeRawWavesPerBlock);
    static_assert(kValueFeatures % 8u == 0u);
    static_assert(
        QRT_QWEN36_HIDDEN_SIZE % kQ1OutputConsumerFusedThreads == 0u
    );

    const unsigned int thread = threadIdx.x;
    const unsigned int lane =
        thread & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = thread / kQ1MoeRawWaveSize;
    const unsigned int first_row = blockIdx.x * kRowsPerBlock;

    Q1MoePersistentDirectVector *weight_tile =
        reinterpret_cast<Q1MoePersistentDirectVector *>(shared_bytes);
    const Q1MoePersistentDirectVector *weight_vectors =
        reinterpret_cast<const Q1MoePersistentDirectVector *>(
            weights + static_cast<size_t>(first_row) * kValueFeatures
        );
    for (unsigned int vector = thread;
         vector < kTileVectors;
         vector += kQ1OutputConsumerFusedThreads) {
        weight_tile[vector] =
            q1_moe_persistent_direct_load_weight(weight_vectors + vector);
    }
    __syncthreads();

    float sum = 0.0f;
    if (wave < kRowsPerBlock) {
        const Q1MoePersistentDirectVector *input_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(input);
        const Q1MoePersistentDirectVector *row_weights =
            weight_tile + wave * kVectors;
        #pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            sum = q1_moe_persistent_direct_dot8(
                input_vectors[vector],
                row_weights[vector],
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
    }
    __syncthreads();

    if (wave < kRowsPerBlock && lane == 0u) {
        const unsigned int row = first_row + wave;
        const uint16_t attention_endpoint = device_float_to_bf16(sum);
        const float residual =
            (vllm_bf16_residual_norm
                 ? device_bf16_round_to_float(residual_input[row])
                 : residual_input[row]) +
            device_bf16_to_float(attention_endpoint);
        residual_output[row] = vllm_bf16_residual_norm
            ? device_bf16_round_to_float(residual)
            : residual;
        __threadfence();
    }
    __syncthreads();

    uint32_t *last_block =
        reinterpret_cast<uint32_t *>(shared_bytes);
    if (thread == 0u) {
        const uint32_t ticket = atomicAdd(completion_counter, 1u);
        last_block[0] =
            ticket + 1u == kQ1OutputConsumerFusedRows2GridBlocks ? 1u : 0u;
    }
    __syncthreads();
    if (last_block[0] == 0u) {
        return;
    }

    double *partial = reinterpret_cast<double *>(shared_bytes);
    float *partial_f32 = reinterpret_cast<float *>(shared_bytes);
    float *inv_shared = reinterpret_cast<float *>(
        shared_bytes +
        kQ1OutputConsumerFusedThreads * sizeof(double)
    );
    float values[kValuesPerLane];
    double sumsq = 0.0;
    float sumsq_f32 = 0.0f;
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? thread * kValuesPerLane + item
            : thread + item * kQ1OutputConsumerFusedThreads;
        const float value = residual_output[col];
        values[item] = value;
        if (vllm_bf16_residual_norm) {
            sumsq_f32 += value * value;
        } else {
            sumsq +=
                static_cast<double>(value) * static_cast<double>(value);
        }
    }
    if (vllm_bf16_residual_norm) {
        partial_f32[thread] = sumsq_f32;
    } else {
        partial[thread] = sumsq;
    }
    __syncthreads();

    for (unsigned int stride = kQ1OutputConsumerFusedThreads / 2u;
         stride > 0u;
         stride >>= 1u) {
        if (thread < stride) {
            if (vllm_bf16_residual_norm) {
                partial_f32[thread] += partial_f32[thread + stride];
            } else {
                partial[thread] += partial[thread + stride];
            }
        }
        __syncthreads();
    }
    if (thread == 0u) {
        if (vllm_bf16_residual_norm) {
            inv_shared[0] = rsqrtf(
                partial_f32[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
        } else {
            inv_shared[0] = 1.0f / sqrtf(
                static_cast<float>(
                    partial[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
        }
    }
    __syncthreads();

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? thread * kValuesPerLane + item
            : thread + item * kQ1OutputConsumerFusedThreads;
        const float normalized =
            values[item] * inv_shared[0] *
            (1.0f + device_bf16_to_float(norm_weights[col]));
        const uint16_t endpoint = device_float_to_bf16(normalized);
        postnorm_output[col] = device_bf16_to_float(endpoint);
        if (postnorm_output_bf16 != nullptr) {
            postnorm_output_bf16[col] = endpoint;
        }
    }
    __syncthreads();
    if (thread == 0u) {
        __threadfence();
        atomicExch(completion_counter, 0u);
    }
}

// Consume two independent attention states while staging each immutable
// output-weight row pair only once.  Waves 0/1 retain the existing state-zero
// row order and waves 2/3 repeat that exact order for state one.  The last
// block performs two independent 256-lane double-RMS trees, so neither dot,
// residual, reduction, nor BF16 publication order changes within a state.
__global__ __launch_bounds__(kQ1OutputConsumerFusedThreads)
void q1_output_consumer_fused_rows2_dual_exact_kernel(
    const uint16_t *weights,
    const uint16_t *input0,
    const uint16_t *input1,
    const float *residual_input0,
    const float *residual_input1,
    const uint16_t *norm_weights,
    float *residual_output0,
    float *residual_output1,
    float *postnorm_output0,
    float *postnorm_output1,
    uint16_t *postnorm_output_bf160,
    uint16_t *postnorm_output_bf161,
    uint16_t *attention_output_bf160,
    uint16_t *attention_output_bf161,
    uint32_t *completion_counter,
    bool vllm_bf16_residual_norm
) {
    extern __shared__ unsigned char shared_bytes[];

    constexpr unsigned int kRowsPerBlock =
        kQ1OutputConsumerFusedRows2RowsPerBlock;
    constexpr unsigned int kStates = 2u;
    constexpr unsigned int kVectors = kValueFeatures / 8u;
    constexpr unsigned int kTileVectors = kRowsPerBlock * kVectors;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kQ1OutputConsumerFusedThreads;
    static_assert(kStates * kRowsPerBlock <= kQ1MoeRawWavesPerBlock);
    static_assert(kValueFeatures % 8u == 0u);
    static_assert(
        QRT_QWEN36_HIDDEN_SIZE % kQ1OutputConsumerFusedThreads == 0u
    );

    const unsigned int thread = threadIdx.x;
    const unsigned int lane =
        thread & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = thread / kQ1MoeRawWaveSize;
    const unsigned int first_row = blockIdx.x * kRowsPerBlock;

    Q1MoePersistentDirectVector *weight_tile =
        reinterpret_cast<Q1MoePersistentDirectVector *>(shared_bytes);
    const Q1MoePersistentDirectVector *weight_vectors =
        reinterpret_cast<const Q1MoePersistentDirectVector *>(
            weights + static_cast<size_t>(first_row) * kValueFeatures
        );
    for (unsigned int vector = thread;
         vector < kTileVectors;
         vector += kQ1OutputConsumerFusedThreads) {
        weight_tile[vector] =
            q1_moe_persistent_direct_load_weight(weight_vectors + vector);
    }
    __syncthreads();

    float sum = 0.0f;
    if (wave < kStates * kRowsPerBlock) {
        const unsigned int state = wave / kRowsPerBlock;
        const unsigned int row_in_block = wave % kRowsPerBlock;
        const uint16_t *input = state == 0u ? input0 : input1;
        const Q1MoePersistentDirectVector *input_vectors =
            reinterpret_cast<const Q1MoePersistentDirectVector *>(input);
        const Q1MoePersistentDirectVector *row_weights =
            weight_tile + row_in_block * kVectors;
        #pragma unroll 1
        for (unsigned int vector = lane;
             vector < kVectors;
             vector += kQ1MoeRawWaveSize) {
            sum = q1_moe_persistent_direct_dot8(
                input_vectors[vector],
                row_weights[vector],
                sum
            );
        }
        sum = q1_moe_raw_wave_tree_sum(sum);
    }
    __syncthreads();

    if (wave < kStates * kRowsPerBlock && lane == 0u) {
        const unsigned int state = wave / kRowsPerBlock;
        const unsigned int row = first_row + wave % kRowsPerBlock;
        const uint16_t attention_endpoint = device_float_to_bf16(sum);
        const float *residual_input = state == 0u
            ? residual_input0
            : residual_input1;
        float *residual_output = state == 0u
            ? residual_output0
            : residual_output1;
        const float residual =
            (vllm_bf16_residual_norm
                 ? device_bf16_round_to_float(residual_input[row])
                 : residual_input[row]) +
            device_bf16_to_float(attention_endpoint);
        residual_output[row] = vllm_bf16_residual_norm
            ? device_bf16_round_to_float(residual)
            : residual;
        uint16_t *attention_output = state == 0u
            ? attention_output_bf160
            : attention_output_bf161;
        if (attention_output != nullptr) {
            attention_output[row] = attention_endpoint;
        }
        __threadfence();
    }
    __syncthreads();

    uint32_t *last_block = reinterpret_cast<uint32_t *>(shared_bytes);
    if (thread == 0u) {
        const uint32_t ticket = atomicAdd(completion_counter, 1u);
        last_block[0] =
            ticket + 1u == kQ1OutputConsumerFusedRows2GridBlocks ? 1u : 0u;
    }
    __syncthreads();
    if (last_block[0] == 0u) {
        return;
    }

    double *partial0 = reinterpret_cast<double *>(shared_bytes);
    double *partial1 = partial0 + kQ1OutputConsumerFusedThreads;
    float *partial_f320 = reinterpret_cast<float *>(shared_bytes);
    float *partial_f321 =
        partial_f320 + kQ1OutputConsumerFusedThreads;
    float *inv_shared = reinterpret_cast<float *>(
        partial1 + kQ1OutputConsumerFusedThreads
    );
    float values0[kValuesPerLane];
    float values1[kValuesPerLane];
    double sumsq0 = 0.0;
    double sumsq1 = 0.0;
    float sumsq_f320 = 0.0f;
    float sumsq_f321 = 0.0f;
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? thread * kValuesPerLane + item
            : thread + item * kQ1OutputConsumerFusedThreads;
        const float value0 = residual_output0[col];
        const float value1 = residual_output1[col];
        values0[item] = value0;
        values1[item] = value1;
        if (vllm_bf16_residual_norm) {
            sumsq_f320 += value0 * value0;
            sumsq_f321 += value1 * value1;
        } else {
            sumsq0 += static_cast<double>(value0) *
                static_cast<double>(value0);
            sumsq1 += static_cast<double>(value1) *
                static_cast<double>(value1);
        }
    }
    if (vllm_bf16_residual_norm) {
        partial_f320[thread] = sumsq_f320;
        partial_f321[thread] = sumsq_f321;
    } else {
        partial0[thread] = sumsq0;
        partial1[thread] = sumsq1;
    }
    __syncthreads();

    for (unsigned int stride = kQ1OutputConsumerFusedThreads / 2u;
         stride > 0u;
        stride >>= 1u) {
        if (thread < stride) {
            if (vllm_bf16_residual_norm) {
                partial_f320[thread] += partial_f320[thread + stride];
                partial_f321[thread] += partial_f321[thread + stride];
            } else {
                partial0[thread] += partial0[thread + stride];
                partial1[thread] += partial1[thread + stride];
            }
        }
        __syncthreads();
    }
    if (thread == 0u) {
        if (vllm_bf16_residual_norm) {
            inv_shared[0] = rsqrtf(
                partial_f320[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
            inv_shared[1] = rsqrtf(
                partial_f321[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
        } else {
            inv_shared[0] = 1.0f / sqrtf(
                static_cast<float>(
                    partial0[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
            inv_shared[1] = 1.0f / sqrtf(
                static_cast<float>(
                    partial1[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
        }
    }
    __syncthreads();

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? thread * kValuesPerLane + item
            : thread + item * kQ1OutputConsumerFusedThreads;
        const float weight =
            1.0f + device_bf16_to_float(norm_weights[col]);
        const uint16_t endpoint0 = device_float_to_bf16(
            values0[item] * inv_shared[0] * weight
        );
        const uint16_t endpoint1 = device_float_to_bf16(
            values1[item] * inv_shared[1] * weight
        );
        postnorm_output0[col] = device_bf16_to_float(endpoint0);
        postnorm_output1[col] = device_bf16_to_float(endpoint1);
        if (postnorm_output_bf160 != nullptr) {
            postnorm_output_bf160[col] = endpoint0;
        }
        if (postnorm_output_bf161 != nullptr) {
            postnorm_output_bf161[col] = endpoint1;
        }
    }
    __syncthreads();
    if (thread == 0u) {
        __threadfence();
        atomicExch(completion_counter, 0u);
    }
}

constexpr size_t kQ2PrecomputedOutputResidualNormSharedBytes =
    2u * kQ1OutputConsumerFusedThreads * sizeof(double) +
    2u * sizeof(float);

// Consume a precomputed two-row BF16 output projection while preserving the
// retained dual-consumer residual and RMSNorm arithmetic.  This separates the
// batch-two GEMM's numerical order from its first nonlinear consumer.
__global__ __launch_bounds__(kQ1OutputConsumerFusedThreads)
void qwen36_q2_precomputed_output_residual_norm_dual_exact_kernel(
    const uint16_t *attention_output_bf16,
    const float *residual_input,
    const uint16_t *norm_weights,
    float *residual_output,
    float *postnorm_output,
    bool vllm_bf16_residual_norm
) {
    extern __shared__ unsigned char shared_bytes[];

    constexpr unsigned int kTokens = 2u;
    constexpr unsigned int kValuesPerLane =
        QRT_QWEN36_HIDDEN_SIZE / kQ1OutputConsumerFusedThreads;
    static_assert(
        QRT_QWEN36_HIDDEN_SIZE % kQ1OutputConsumerFusedThreads == 0u
    );

    const unsigned int thread = threadIdx.x;
    double *partial0 = reinterpret_cast<double *>(shared_bytes);
    double *partial1 = partial0 + kQ1OutputConsumerFusedThreads;
    float *partial_f320 = reinterpret_cast<float *>(shared_bytes);
    float *partial_f321 =
        partial_f320 + kQ1OutputConsumerFusedThreads;
    float *inv_shared = reinterpret_cast<float *>(
        partial1 + kQ1OutputConsumerFusedThreads
    );
    float values0[kValuesPerLane];
    float values1[kValuesPerLane];
    double sumsq0 = 0.0;
    double sumsq1 = 0.0;
    float sumsq_f320 = 0.0f;
    float sumsq_f321 = 0.0f;

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? thread * kValuesPerLane + item
            : thread + item * kQ1OutputConsumerFusedThreads;
        const float residual0 =
            (vllm_bf16_residual_norm
                 ? device_bf16_round_to_float(residual_input[col])
                 : residual_input[col]) +
            device_bf16_to_float(attention_output_bf16[col]);
        const float residual1 =
            (vllm_bf16_residual_norm
                 ? device_bf16_round_to_float(
                       residual_input[
                           QRT_QWEN36_HIDDEN_SIZE + col
                       ]
                   )
                 : residual_input[QRT_QWEN36_HIDDEN_SIZE + col]) +
            device_bf16_to_float(
                attention_output_bf16[
                    QRT_QWEN36_HIDDEN_SIZE + col
                ]
            );
        const float value0 = vllm_bf16_residual_norm
            ? device_bf16_round_to_float(residual0)
            : residual0;
        const float value1 = vllm_bf16_residual_norm
            ? device_bf16_round_to_float(residual1)
            : residual1;
        residual_output[col] = value0;
        residual_output[QRT_QWEN36_HIDDEN_SIZE + col] = value1;
        values0[item] = value0;
        values1[item] = value1;
        if (vllm_bf16_residual_norm) {
            sumsq_f320 += value0 * value0;
            sumsq_f321 += value1 * value1;
        } else {
            sumsq0 += static_cast<double>(value0) *
                static_cast<double>(value0);
            sumsq1 += static_cast<double>(value1) *
                static_cast<double>(value1);
        }
    }
    if (vllm_bf16_residual_norm) {
        partial_f320[thread] = sumsq_f320;
        partial_f321[thread] = sumsq_f321;
    } else {
        partial0[thread] = sumsq0;
        partial1[thread] = sumsq1;
    }
    __syncthreads();

    for (unsigned int stride = kQ1OutputConsumerFusedThreads / 2u;
         stride > 0u;
         stride >>= 1u) {
        if (thread < stride) {
            if (vllm_bf16_residual_norm) {
                partial_f320[thread] += partial_f320[thread + stride];
                partial_f321[thread] += partial_f321[thread + stride];
            } else {
                partial0[thread] += partial0[thread + stride];
                partial1[thread] += partial1[thread + stride];
            }
        }
        __syncthreads();
    }
    if (thread == 0u) {
        if (vllm_bf16_residual_norm) {
            inv_shared[0] = rsqrtf(
                partial_f320[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
            inv_shared[1] = rsqrtf(
                partial_f321[0] /
                    static_cast<float>(QRT_QWEN36_HIDDEN_SIZE) +
                QRT_QWEN36_RMS_NORM_EPSILON
            );
        } else {
            inv_shared[0] = 1.0f / sqrtf(
                static_cast<float>(
                    partial0[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
            inv_shared[1] = 1.0f / sqrtf(
                static_cast<float>(
                    partial1[0] /
                    static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
                ) + QRT_QWEN36_RMS_NORM_EPSILON
            );
        }
    }
    __syncthreads();

    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = vllm_bf16_residual_norm
            ? thread * kValuesPerLane + item
            : thread + item * kQ1OutputConsumerFusedThreads;
        const float weight =
            1.0f + device_bf16_to_float(norm_weights[col]);
        postnorm_output[col] = device_bf16_to_float(
            device_float_to_bf16(
                values0[item] * inv_shared[0] * weight
            )
        );
        postnorm_output[QRT_QWEN36_HIDDEN_SIZE + col] =
            device_bf16_to_float(
                device_float_to_bf16(
                    values1[item] * inv_shared[1] * weight
                )
            );
    }
}

// Preserve the retained double-precision input RMS tree while publishing both
// the diagnostic F32 surface and its identical BF16 projection endpoint.
__global__ void q1_full_attention_input_rmsnorm_bf16_kernel(
    const float *selected_input,
    const uint16_t *norm_weights,
    float *outputs_f32,
    uint16_t *outputs_bf16
) {
    __shared__ double partial[kThreads];
    __shared__ float inv_shared;
    const unsigned int lane = threadIdx.x;
    if (blockDim.x != kThreads || selected_input == nullptr ||
        norm_weights == nullptr || outputs_f32 == nullptr ||
        outputs_bf16 == nullptr) {
        return;
    }
    double sumsq = 0.0;
    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE;
         col += blockDim.x) {
        const float value = selected_input[col];
        sumsq += static_cast<double>(value) * static_cast<double>(value);
    }
    partial[lane] = sumsq;
    __syncthreads();
    for (unsigned int stride = blockDim.x / 2u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            partial[lane] += partial[lane + stride];
        }
        __syncthreads();
    }
    if (lane == 0u) {
        inv_shared = 1.0f / sqrtf(
            static_cast<float>(
                partial[0] /
                static_cast<double>(QRT_QWEN36_HIDDEN_SIZE)
            ) + QRT_QWEN36_RMS_NORM_EPSILON
        );
    }
    __syncthreads();
    for (unsigned int col = lane; col < QRT_QWEN36_HIDDEN_SIZE;
         col += blockDim.x) {
        const float value = device_bf16_round_to_float(
            selected_input[col] * inv_shared *
            (1.0f + device_bf16_to_float(norm_weights[col]))
        );
        outputs_f32[col] = value;
        outputs_bf16[col] = device_float_to_bf16(value);
    }
}

// Q, K, and V retain independent resident weight pointers but share one raw
// wave32 GEMV geometry and one rounded canonical [Q][K][V] F32 destination.
__global__ __launch_bounds__(kQ1MoeRawBlockThreads)
void q1_full_attention_raw_bf16_wave_qkv_kernel(
    const uint16_t *q_weights,
    const uint16_t *k_weights,
    const uint16_t *v_weights,
    const uint16_t *input,
    float *qkv_output
) {
    constexpr unsigned int kRowsPerWave = 4u;
    constexpr unsigned int kRowsPerBlock =
        kQ1MoeRawWavesPerBlock * kRowsPerWave;
    constexpr unsigned int kInputFeatures = QRT_QWEN36_HIDDEN_SIZE;
    constexpr unsigned int kOutputRows = kLayer3FullAttentionQkvRows;
    static_assert(kLayer3FullAttentionQRows % kRowsPerBlock == 0u, "Q row boundary must align to raw blocks");
    static_assert(kLayer3FullAttentionKRows % kRowsPerBlock == 0u, "K row boundary must align to raw blocks");
    const unsigned int lane =
        threadIdx.x & (kQ1MoeRawWaveSize - 1u);
    const unsigned int wave = threadIdx.x / kQ1MoeRawWaveSize;
    const unsigned int row_base =
        blockIdx.x * kRowsPerBlock + wave * kRowsPerWave;
    const uint32_t *input_pairs = reinterpret_cast<const uint32_t *>(input);
    constexpr unsigned int kPairCount = kInputFeatures / 2u;
    const uint32_t *weight_pairs[kRowsPerWave] = {};
    #pragma unroll
    for (unsigned int local_row = 0u; local_row < kRowsPerWave; ++local_row) {
        const unsigned int row = row_base + local_row;
        const uint16_t *row_weights = nullptr;
        unsigned int local_weight_row = 0u;
        if (row < kLayer3FullAttentionQRows) {
            row_weights = q_weights;
            local_weight_row = row;
        } else if (row < kLayer3FullAttentionQRows +
                         kLayer3FullAttentionKRows) {
            row_weights = k_weights;
            local_weight_row = row - kLayer3FullAttentionQRows;
        } else if (row < kOutputRows) {
            row_weights = v_weights;
            local_weight_row = row - kLayer3FullAttentionQRows -
                kLayer3FullAttentionKRows;
        }
        if (row_weights != nullptr) {
            weight_pairs[local_row] = reinterpret_cast<const uint32_t *>(
                row_weights +
                static_cast<size_t>(local_weight_row) * kInputFeatures
            );
        }
    }
    float sums[kRowsPerWave] = {};
    for (unsigned int pair = lane; pair < kPairCount;
         pair += kQ1MoeRawWaveSize) {
        const uint32_t input_pair = input_pairs[pair];
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kRowsPerWave;
             ++local_row) {
            if (weight_pairs[local_row] != nullptr) {
                sums[local_row] = device_dot2_f32_bf16(
                    input_pair,
                    weight_pairs[local_row][pair],
                    sums[local_row]
                );
            }
        }
    }
    #pragma unroll
    for (unsigned int local_row = 0u; local_row < kRowsPerWave; ++local_row) {
        sums[local_row] = q1_moe_raw_wave_tree_sum(sums[local_row]);
    }
    if (lane == 0u) {
        #pragma unroll
        for (unsigned int local_row = 0u;
             local_row < kRowsPerWave;
             ++local_row) {
            const unsigned int row = row_base + local_row;
            if (row < kOutputRows) {
                qkv_output[row] = device_bf16_round_to_float(
                    sums[local_row]
                );
            }
        }
    }
}

__global__ void routed_matrix_unpack_gate_up_pairs_kernel(
    const uint32_t *const *packed_gate_up_pairs,
    uint16_t *gate_weights,
    uint16_t *up_weights,
    size_t projection_elements,
    size_t total_elements
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= total_elements) {
        return;
    }
    const size_t expert_slot = index / projection_elements;
    const size_t in_expert = index - expert_slot * projection_elements;
    const uint32_t packed = packed_gate_up_pairs[expert_slot][in_expert];
    gate_weights[index] = static_cast<uint16_t>(packed & UINT32_C(0xffff));
    up_weights[index] = static_cast<uint16_t>(packed >> 16u);
}

__global__ void routed_matrix_unpack_down_pairs_kernel(
    const uint32_t *const *packed_down_pairs,
    uint16_t *down_weights,
    size_t projection_elements,
    size_t total_elements
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= total_elements) {
        return;
    }
    const size_t expert_slot = index / projection_elements;
    const size_t in_expert = index - expert_slot * projection_elements;
    const size_t row = in_expert / QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const size_t inter =
        in_expert - row * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE;
    const size_t tile = row / kRoutedDownTileRows;
    const size_t row_in_tile = row - tile * kRoutedDownTileRows;
    const size_t pair_group =
        row_in_tile / (2u * static_cast<size_t>(kThreadTileRows));
    const size_t row_in_pair_group =
        row_in_tile - pair_group * (2u * static_cast<size_t>(kThreadTileRows));
    const bool high_half = row_in_pair_group >= kThreadTileRows;
    const size_t local_row = row_in_pair_group % kThreadTileRows;
    const size_t row_pair =
        (tile * kRoutedDownPackedRowPairGroups + pair_group) *
            kThreadTileRows +
        local_row;
    const uint32_t packed = packed_down_pairs[expert_slot][
        row_pair * QRT_QWEN36_MOE_EXPERT_INTERMEDIATE + inter
    ];
    down_weights[index] = high_half
        ? static_cast<uint16_t>(packed >> 16u)
        : static_cast<uint16_t>(packed & UINT32_C(0xffff));
}

__global__ void routed_matrix_gather_inputs_bf16_kernel(
    const float *inputs,
    const uint32_t *sorted_route_indices,
    uint16_t *grouped_inputs,
    size_t total_elements
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= total_elements) {
        return;
    }
    const size_t sorted_route = index / QRT_QWEN36_HIDDEN_SIZE;
    const size_t col = index - sorted_route * QRT_QWEN36_HIDDEN_SIZE;
    const uint32_t route_index = sorted_route_indices[sorted_route];
    const size_t token_index = route_index / QRT_QWEN36_EXPERTS_PER_TOKEN;
    grouped_inputs[index] = device_float_to_bf16(
        inputs[token_index * QRT_QWEN36_HIDDEN_SIZE + col]
    );
}

__global__ void routed_matrix_combine_original_route_order_kernel(
    const uint16_t *grouped_route_outputs,
    const uint32_t *route_to_grouped_position,
    const float *topk_weights,
    float *outputs,
    size_t output_elements
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= output_elements) {
        return;
    }
    const size_t token_index = index / QRT_QWEN36_HIDDEN_SIZE;
    const size_t row = index - token_index * QRT_QWEN36_HIDDEN_SIZE;
    const size_t route_base =
        token_index * QRT_QWEN36_EXPERTS_PER_TOKEN;
    float value = 0.0f;
    for (unsigned int route_order = 0u;
         route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route_order) {
        const size_t route_index = route_base + route_order;
        const size_t grouped_position =
            route_to_grouped_position[route_index];
        value = device_mul_add_separate(
            value,
            topk_weights[route_index],
            device_bf16_to_float(
                grouped_route_outputs[
                    grouped_position * QRT_QWEN36_HIDDEN_SIZE + row
                ]
            )
        );
    }
    outputs[index] = value;
}

// Q1 top-k routes are unique and the resident corridor writes every expert
// result directly into its original router slot.  This is the identity-map
// specialization of routed_matrix_combine_original_route_order_kernel: it
// deliberately preserves the same route-order loop and separate multiply/add
// boundary while removing the per-layer inverse-permutation allocation/copy.
__global__ void routed_matrix_combine_q1_route_order_kernel(
    const uint16_t *route_outputs,
    const float *topk_weights,
    float *outputs,
    size_t output_elements
) {
    const size_t index =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (index >= output_elements) {
        return;
    }
    const size_t row = index % QRT_QWEN36_HIDDEN_SIZE;
    float value = 0.0f;
    for (unsigned int route_order = 0u;
         route_order < QRT_QWEN36_EXPERTS_PER_TOKEN;
         ++route_order) {
        value = device_mul_add_separate(
            value,
            topk_weights[route_order],
            device_bf16_to_float(
                route_outputs[
                    static_cast<size_t>(route_order) *
                        QRT_QWEN36_HIDDEN_SIZE +
                    row
                ]
            )
        );
    }
    outputs[index] = value;
}

__global__ void output_residual_add_kernel(
    const float *residual_inputs,
    const float *moe_updates,
    float *outputs,
    unsigned int selected_token_count
) {
    const size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const size_t total = static_cast<size_t>(selected_token_count) * QRT_QWEN36_HIDDEN_SIZE;
    if (idx >= total) {
        return;
    }
    outputs[idx] = residual_inputs[idx] + moe_updates[idx];
}

// The service-visible MoE endpoint is BF16 before GemmaRMSNorm consumes it.
// Preserve that boundary explicitly for the q65536 diagnostic even when the
// selected-MoE implementation owns F32 scratch internally.
__global__ void output_residual_add_vllm_bf16_kernel(
    const float *residual_inputs,
    const float *moe_updates,
    float *outputs,
    unsigned int selected_token_count
) {
    const size_t idx =
        static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const size_t total =
        static_cast<size_t>(selected_token_count) *
        QRT_QWEN36_HIDDEN_SIZE;
    if (idx >= total) {
        return;
    }
    const float residual =
        device_bf16_round_to_float(residual_inputs[idx]);
    const float update = device_bf16_round_to_float(moe_updates[idx]);
    outputs[idx] = device_bf16_round_to_float(residual + update);
}

// vLLM's fused GemmaRMSNorm publishes the rounded BF16 residual carrier but
// evaluates the following layer's variance from the unrounded FP32 addition
// of its two BF16 inputs.  Preserve that otherwise-lost scalar boundary while
// still carrying only the compact rounded hidden row between layers.
//
// TorchInductor's q8192 Triton kernel uses R0_BLOCK=2048 with eight logical
// 32-lane warps per token.  Every lane owns eight adjacent columns.  Match its
// generated reduction literally: a fixed scalar fold of those eight squares,
// a butterfly-equivalent fold inside each logical warp, and finally a fold of
// the eight warp totals.  A single 256-lane tree changes the FP32 association
// and is measurably wrong at the gb10 first-token boundary.
__device__ __forceinline__ float vllm_triton_lane8_sumsq(
    const float values[8]
) {
    // Spell out the exact Hopper PTX sequence observed for the dynamic
    // TorchInductor reduction.  HIP-Clang otherwise contracts/reassociates
    // a small subset of these operations differently on gfx1151, moving the
    // final sum by one or two FP32 ULPs even when all 2048 inputs are exact.
    float sum = device_fma_f32(
        values[0],
        values[0],
        device_mul_separate(values[1], values[1])
    );
    sum = device_fma_f32(values[2], values[2], sum);
    sum = device_add_separate(
        device_mul_separate(values[3], values[3]),
        sum
    );
    sum = device_fma_f32(values[4], values[4], sum);
    sum = device_add_separate(
        device_mul_separate(values[5], values[5]),
        sum
    );
    sum = device_fma_f32(values[6], values[6], sum);
    return device_add_separate(
        device_mul_separate(values[7], values[7]),
        sum
    );
}

__device__ __forceinline__ float vllm_triton_reduce_sumsq(
    float lane_sumsq,
    float *partial,
    unsigned int lane
) {
    constexpr unsigned int kLogicalWarp = 32u;
    constexpr unsigned int kLogicalWarpsPerToken =
        kThreads / kLogicalWarp;
    static_assert(kLogicalWarpsPerToken == 8u);
    partial[lane] = lane_sumsq;
    __syncthreads();
    const unsigned int logical_lane = lane & (kLogicalWarp - 1u);
    for (unsigned int stride = kLogicalWarp / 2u; stride > 0u;
         stride >>= 1u) {
        if (logical_lane < stride) {
            partial[lane] = device_add_separate(
                partial[lane],
                partial[lane + stride]
            );
        }
        __syncthreads();
    }
    if (lane < kLogicalWarpsPerToken) {
        partial[lane] = partial[lane * kLogicalWarp];
    }
    __syncthreads();
    for (unsigned int stride = kLogicalWarpsPerToken / 2u; stride > 0u;
         stride >>= 1u) {
        if (lane < stride) {
            partial[lane] = device_add_separate(
                partial[lane],
                partial[lane + stride]
            );
        }
        __syncthreads();
    }
    return partial[0];
}

__global__ void final_norm_unrounded_vll.text:
__global__ void final_norm_unrounded_vllm_kernel(
    const float *selected_input,
    const uint16_t *norm_weights,
    float *outputs,
    unsigned int selected_token_count,
    const uint8_t *gfx1151_sm121_rsqrt_correction
) {
    __shared__ float partial[kThreads];
    __shared__ float inv_shared;
    constexpr unsigned int kValuesPerLane = QRT_QWEN36_HIDDEN_SIZE / kThreads;
    const unsigned int token = blockIdx.x;
    const unsigned int lane = threadIdx.x;
    if (token >= selected_token_count || selected_input == nullptr ||
        norm_weights == nullptr || outputs == nullptr) {
        return;
    }
    const size_t base = static_cast<size_t>(token) * QRT_QWEN36_HIDDEN_SIZE;
    float values[kValuesPerLane];
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        values[item] = selected_input[base + lane * kValuesPerLane + item];
    }
    const float sumsq = vllm_triton_reduce_sumsq(
        vllm_triton_lane8_sumsq(values), partial, lane);
    if (lane == 0u) {
        const float variance = __fadd_rn(
            sumsq / static_cast<float>(QRT_QWEN36_HIDDEN_SIZE),
            QRT_QWEN36_RMS_NORM_EPSILON);
        inv_shared = device_sm121_rsqrt_from_gfx1151(
            variance, gfx1151_sm121_rsqrt_correction);
    }
    __syncthreads();
    #pragma unroll
    for (unsigned int item = 0u; item < kValuesPerLane; ++item) {
        const unsigned int col = lane * kValuesPerLane + item;
        outputs[base + col] = device_bf16_round_to_float(
            device_bf16_round_to_float(values[item]) * inv_shared *
            (1.0f + device_bf16_to_float(norm_weights[col])));
    }
}

