template<class T> std::vector<T> read(const char *path) {
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if(!f || f.tellg()%sizeof(T)) throw std::runtime_error("invalid input");
    std::vector<T> a(static_cast<size_t>(f.tellg())/sizeof(T));
    f.seekg(0);f.read(reinterpret_cast<char*>(a.data()),a.size()*sizeof(T));
    if(!f) throw std::runtime_error("short input");
    return a;
}
float value(uint16_t x) {uint32_t y=uint32_t(x)<<16;float f;std::memcpy(&f,&y,4);return f;}
uint16_t bf16(float f) {uint32_t y;std::memcpy(&y,&f,4);return (y+0x7fffu+((y>>16)&1u))>>16;}

std::array<float,3> scalars(const float *x,const unsigned char *table,int order,int lookup) {
 std::array<float,256> lane{},next{};
 for(unsigned i=0;i<256;++i){const float *p=x+8*i;float sum=p[1]*p[1];sum=std::fma(p[0],p[0],sum);
  for(unsigned j=2;j<8;++j) sum=(order==1&&(j&1))?sum+p[j]*p[j]:std::fma(p[j],p[j],sum);
  lane[i]=sum;
 }
 for(unsigned mask:{16u,8u,4u,2u,1u}) {for(unsigned i=0;i<256;++i)next[i]=lane[i]+lane[i^mask];lane=next;}
 std::array<float,8> warp{},sum{};for(unsigned i=0;i<8;++i)warp[i]=lane[i*32];
 for(unsigned mask:{4u,2u,1u}) {for(unsigned i=0;i<8;++i)sum[i]=warp[i]+warp[i^mask];warp=sum;}
 float var=warp[0]/2048.0f+1.0e-6f;
 if(order==2){double s=0;for(int i=0;i<2048;++i)s+=double(x[i])*double(x[i]);var=float(s/2048.0)+1.0e-6f;}
 return {warp[0],var,lookup?qrt_sm121_rsqrt::evaluate(table,var):1.0f/std::sqrt(var)};
}


int main(int argc,char**argv)try{if(argc!=6)throw std::runtime_error("unrounded weight expected table output");auto x=read<float>(argv[1]);auto w=read<uint16_t>(argv[2]),e=read<uint16_t>(argv[3]);auto table=read<unsigned char>(argv[4]);if(x.size()!=2048||w.size()!=2048||e.size()!=2048||!qrt_sm121_rsqrt::valid_layout(table.data(),table.size()))throw std::runtime_error("shape");auto c=scalars(x.data(),table.data(),1,1);std::vector<uint16_t> out(x.size());size_t bad=0;for(size_t i=0;i<2048;++i){out[i]=bf16(value(bf16(x[i]))*c[2]*(value(w[i])+1.0f));bad+=out[i]!=e[i];}std::ofstream f(argv[5],std::ios::binary);f.write((char*)out.data(),out.size()*2);std::cout<<"{\"elements\":2048,\"bf16_mismatches\":"<<bad<<",\"sumsq\":"<<c[0]<<",\"variance\":"<<c[1]<<",\"rstd\":"<<c[2]<<"}\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}
